diff --git a/src/controllers/write/topics.js b/src/controllers/write/topics.js
index d0f860680..0f7eba570 100644
--- a/src/controllers/write/topics.js
+++ b/src/controllers/write/topics.js
@@ -12,24 +12,79 @@ const uploadsController = require('../uploads');

 const Topics = module.exports;

+const postingLocks = new Map();
+
+/**
+ * Provides a lightweight locking mechanism to prevent concurrent posting
+ * actions by the same user or guest session. Ensures that only one
+ * create/reply request is processed at a time per actor.
+ *
+ * The lock is held for the duration of the request, so any other request
+ * from the same user/session that overlaps with an in-flight one is
+ * rejected. Requests are keyed by authenticated uid or, for guests, by the
+ * session ID, matching how sessions are identified elsewhere in core.
+ *
+ * @param {object} req request object containing either `uid` for authenticated
+ *                     users or `sessionID` for guests
+ * @param {string} error error message to raise when a concurrent posting
+ *                       attempt is detected
+ * @returns {Promise<string>} key (`posting<id>`) that uniquely identifies the
+ *                            lock for the user/session
+ */
+async function lockPosting(req, error) {
+	const id = req.uid > 0 ? req.uid : req.sessionID;
+	const key = `posting${id}`;
+
+	if (postingLocks.has(key)) {
+		throw new Error(error);
+	}
+
+	postingLocks.set(key, req);
+	return key;
+}
+
+/**
+ * Releases a posting lock previously acquired with {@link lockPosting}.
+ * Only the request that acquired the lock may release it.
+ *
+ * @param {string} key lock key as returned by {@link lockPosting}
+ * @param {object} req request object that acquired the lock
+ */
+function releasePostingLock(key, req) {
+	if (postingLocks.get(key) === req) {
+		postingLocks.delete(key);
+	}
+}
+
 Topics.get = async (req, res) => {
 	helpers.formatApiResponse(200, res, await api.topics.get(req, req.params));
 };

 Topics.create = async (req, res) => {
-	const payload = await api.topics.create(req, req.body);
-	if (payload.queued) {
-		helpers.formatApiResponse(202, res, payload);
-	} else {
-		helpers.formatApiResponse(200, res, payload);
+	const key = await lockPosting(req, '[[error:posting-in-progress]]');
+	try {
+		const payload = await api.topics.create(req, req.body);
+		if (payload.queued) {
+			helpers.formatApiResponse(202, res, payload);
+		} else {
+			helpers.formatApiResponse(200, res, payload);
+		}
+	} finally {
+		releasePostingLock(key, req);
 	}
 };

 Topics.reply = async (req, res) => {
-	const payload = await api.topics.reply(req, { ...req.body, tid: req.params.tid });
-	helpers.formatApiResponse(200, res, payload);
+	const key = await lockPosting(req, '[[error:posting-in-progress]]');
+	try {
+		const payload = await api.topics.reply(req, { ...req.body, tid: req.params.tid });
+		helpers.formatApiResponse(200, res, payload);
+	} finally {
+		releasePostingLock(key, req);
+	}
 };

+
 Topics.delete = async (req, res) => {
 	await api.topics.delete(req, { tids: [req.params.tid] });
 	helpers.formatApiResponse(200, res);
diff --git a/test/concurrent-topic-create.js b/test/concurrent-topic-create.js
new file mode 100644
index 000000000..0de2a2cb5
--- /dev/null
+++ b/test/concurrent-topic-create.js
@@ -0,0 +1,82 @@
+'use strict';
+
+const assert = require('assert');
+const request = require('request');
+const util = require('util');
+const nconf = require('nconf');
+
+const db = require('./mocks/databasemock');
+const categories = require('../src/categories');
+const user = require('../src/user');
+const groups = require('../src/groups');
+const helpers = require('./helpers');
+
+const post = util.promisify(request.post).bind(request);
+
+describe('Concurrent topic creation', () => {
+	let categoryObj;
+	let adminJar;
+	let csrfToken;
+
+	before(async () => {
+		const adminUid = await user.create({ username: 'conccurrent-admin', password: '123456' });
+		await groups.join('administrators', adminUid);
+		const login = await helpers.loginUser('conccurrent-admin', '123456');
+		adminJar = login.jar;
+		csrfToken = login.csrf_token;
+		categoryObj = await categories.create({ name: 'concurrent-test-category' });
+	});
+
+	function createOpts() {
+		return {
+			url: `${nconf.get('url')}/api/v3/topics`,
+			form: {
+				cid: categoryObj.cid,
+				title: 'Concurrent burst topic',
+				content: 'Concurrent burst topic content',
+			},
+			jar: adminJar,
+			headers: { 'x-csrf-token': csrfToken },
+			json: true,
+		};
+	}
+
+	it('should accept exactly one of several concurrent create requests from the same user', async () => {
+		const N = 5;
+		const results = await Promise.all(
+			Array.from({ length: N }, () => post(createOpts()))
+		);
+
+		const ok = results.filter(r => r.statusCode === 200 && r.body.status.code === 'ok');
+		const bad = results.filter(r => r.statusCode === 400 && r.body.status.code === 'bad-request');
+
+		assert.strictEqual(ok.length, 1, `expected exactly 1 success, got ${ok.length} (codes: ${results.map(r => r.statusCode).join(',')})`);
+		assert.strictEqual(bad.length, N - 1, `expected ${N - 1} rejections, got ${bad.length}`);
+
+		// successful payload shape
+		assert.strictEqual(ok[0].body.response.title, 'Concurrent burst topic');
+		assert.ok(ok[0].body.response.tid > 0);
+	}, 25000);
+
+	it('should have created exactly one topic and keep counters consistent', async () => {
+		const globalObj = await db.getObject('global');
+		const globalTopicCount = parseInt(globalObj.topicCount, 10);
+		const categoryCount = parseInt(await db.getObjectField(`category:${categoryObj.cid}`, 'topic_count'), 10);
+		assert.strictEqual(categoryCount, 1, `category topic_count should be 1, got ${categoryCount}`);
+		assert.ok(globalTopicCount >= 1, `global topicCount should be >= 1, got ${globalTopicCount}`);
+
+		// no duplicates: exactly one tid should be tracked for this category
+		const tids = await db.getSortedSetRange(`cid:${categoryObj.cid}:tids`, 0, -1);
+		assert.strictEqual(tids.length, 1, `expected exactly 1 tid in category set, got ${tids.length}`);
+	}, 25000);
+
+	it('should allow a fresh create request after the burst has completed', async () => {
+		const { statusCode, body } = await post(createOpts());
+		assert.strictEqual(statusCode, 200, JSON.stringify(body));
+		assert.strictEqual(body.status.code, 'ok');
+		assert.strictEqual(body.response.title, 'Concurrent burst topic');
+
+		const tids = await db.getSortedSetRange(`cid:${categoryObj.cid}:tids`, 0, -1);
+		assert.strictEqual(tids.length, 2, `expected 2 tids after follow-up create, got ${tids.length}`);
+	}, 25000);
+});

