+
+	async function isExemptFromMaintenanceMode(uid) {
+		if (!meta.config.groupsExemptFromMaintenanceMode || !meta.config.groupsExemptFromMaintenanceMode.length) {
+			meta.config.groupsExemptFromMaintenanceMode = MAINTENANCE_EXEMPT_GROUPS;
+		}
+
+		if (!uid) {
+			// Unauthenticated visitors are treated as members of the guests group
+			return meta.config.groupsExemptFromMaintenanceMode.includes('guests');
