diff --git a/test/maintenance-exemption.js b/test/maintenance-exemption.js
new file mode 100644
index 000000000..b5ce6ddb1
--- /dev/null
+++ b/test/maintenance-exemption.js
@@ -0,0 +1,220 @@
+'use strict';
+
+const assert = require('assert');
+const nconf = require('nconf');
+const request = require('request');
+const requestAsync = require('request-promise-native');
+
+const db = require('./mocks/databasemock');
+const user = require('../src/user');
+const groups = require('../src/groups');
+const meta = require('../src/meta');
+const helpers = require('./helpers');
+
+describe('Maintenance Mode - Group Exemption', () => {
+	let adminUid;
+	let modUid;
+	let regularUid;
+	let memberUid;
+	let customGroupUid;
+	let adminJar;
+	let adminCsrf;
+
+	const maintenanceExemptGroups = 'groupsExemptFromMaintenanceMode';
+
+	before(async () => {
+		// Create an admin
+		adminUid = await user.create({ username: 'maintadmin', password: 'barbar', gdpr_consent: true });
+		await groups.join('administrators', adminUid);
+
+		// Create a global moderator (but NOT an admin)
+		modUid = await user.create({ username: 'maintmod', password: 'barbar', gdpr_consent: true });
+		await groups.join('Global Moderators', modUid);
+
+		// Create a regular user in a custom group
+		await groups.create({ name: 'special-access', description: 'Users that need access during maintenance' });
+		regularUid = await user.create({ username: 'maintuser', password: 'barbar', gdpr_consent: true });
+		await groups.join('special-access', regularUid);
+
+		// A second member of the custom group (to verify membership check)
+		memberUid = await user.create({ username: 'maintmember', password: 'barbar', gdpr_consent: true });
+		await groups.join('special-access', memberUid);
+
+		// A user NOT in any exempt group
+		customGroupUid = await user.create({ username: 'maintoutsider', password: 'barbar', gdpr_consent: true });
+
+		({ jar: adminJar, csrf_token: adminCsrf } = await helpers.loginUser('maintadmin', 'barbar'));
+	});
+
+	afterEach(async () => {
+		meta.config.maintenanceMode = 0;
+		delete meta.config[maintenanceExemptGroups];
+		await groups.cache.reset();
+	});
+
+	it('should expose settingsController.advanced that renders the advanced template', async () => {
+		const controller = require('../src/controllers/admin/settings');
+		assert.strictEqual(typeof controller.advanced, 'function', 'settingsController.advanced must be a function');
+
+		// It should render admin/settings/advanced and pass the group data
+		const rendered = [];
+		const fakeRes = {
+			render: (tpl, data) => rendered.push({ tpl, data }),
+		};
+		const fakeReq = {};
+		await controller.advanced(fakeReq, fakeRes);
+		assert.ok(rendered.length === 1, 'controller should render once');
+		assert.strictEqual(rendered[0].tpl, 'admin/settings/advanced', 'renders admin/settings/advanced template');
+		assert.ok(Array.isArray(rendered[0].data.groupsExemptFromMaintenanceMode), 'passes groups data');
+		const names = rendered[0].data.groupsExemptFromMaintenanceMode.map(g => g.name);
+		assert.ok(names.includes('special-access'), 'non-privileged group appears in the list');
+	});
+
+	it('should allow the /admin/settings/advanced admin route', async () => {
+		const body = await requestAsync({
+			url: `${nconf.get('url')}/admin/settings/advanced`,
+			jar: adminJar,
+			// follow redirects to see the final status
+			resolveWithFullResponse: true,
+			simple: false,
+		});
+		assert.strictEqual(body.statusCode, 200, `expected 200, got ${body.statusCode}`);
+		assert.ok(body.body.includes('groupsExemptFromMaintenanceMode'), 'page includes the exemption multi-select');
+	});
+
+	it('should let an admin bypass maintenance mode (default config)', async () => {
+		meta.config.maintenanceMode = 1;
+		const res = await requestAsync({
+			url: `${nconf.get('url')}/api/recent`,
+			jar: adminJar,
+			resolveWithFullResponse: true,
+			simple: false,
+		});
+		assert.strictEqual(res.statusCode, 200, 'admin should bypass maintenance');
+	});
+
+	it('should let a Global Moderator bypass maintenance mode (default config)', async () => {
+		meta.config.maintenanceMode = 1;
