+const helpers = require('./helpers');
+const utils = require('../src/utils');
+const accountHelpers = require('../src/controllers/accounts/helpers');
+
+describe('privileged chat', () => {
+	const mocks = { foo: {}, herp: {} };
+	let chatMessageDelay;
+
+	const callv3API = async (method, path, body, user) => {
+		const options = {
+			method,
+			body,
+			json: true,
+			jar: mocks.users ? mocks.users[user].jar : mocks[user].jar,
+			resolveWithFullResponse: true,
+			simple: false,
+		};
+		if (method !== 'get') {
+			options.headers = { 'x-csrf-token': mocks[user].csrf };
+		}
+		return request(`${nconf.get('url')}/api/v3${path}`, options);
+	};
+
+	before(async () => {
+		({ foo: mocks.foo.uid, herp: mocks.herp.uid } = await utils.promiseParallel({
+			foo: User.create({ username: 'pfoo', password: 'barbar' }),
+			herp: User.create({ username: 'pherp', password: 'derpderp' }),
+		}));
+		await Groups.join('administrators', mocks.foo.uid);
+		({ jar: mocks.foo.jar, csrf_token: mocks.foo.csrf } = await helpers.loginUser('pfoo', 'barbar'));
+		({ jar: mocks.herp.jar, csrf_token: mocks.herp.csrf } = await helpers.loginUser('pherp', 'derpderp'));
+		chatMessageDelay = meta.config.chatMessageDelay;
+		meta.config.chatMessageDelay = 0;
+	});
+
+	after(() => {
+		meta.config.chatMessageDelay = chatMessageDelay;
+	});
+
+	it('privileges.global.can returns boolean for string', async () => {
+		const result = await Privileges.global.can('chat', mocks.herp.uid);
+		assert.strictEqual(typeof result, 'boolean');
+	});
+
+	it('privileges.global.can returns array for array input', async () => {
+		const result = await Privileges.global.can(['chat', 'chat:privileged'], mocks.herp.uid);
+		assert(Array.isArray(result));
+		assert.strictEqual(result.length, 2);
+		assert(result.every(v => typeof v === 'boolean'));
+	});
+
+	it('privileges.global.can array reflects admin override', async () => {
+		const result = await Privileges.global.can(['chat', 'chat:privileged'], mocks.foo.uid);
+		assert(Array.isArray(result));
+		assert(result.includes(true));
+	});
+
+	it('herp cannot message admin foo without chat:privileged', async () => {
+		await assert.rejects(messaging.canMessageUser(mocks.herp.uid, mocks.foo.uid), {
+			message: '[[error:no-privileges]]',
+		});
+	});
+
+	it('admin foo can message herp', async () => {
+		await messaging.canMessageUser(mocks.foo.uid, mocks.herp.uid);
+	});
+
+	it('giving herp chat:privileged allows herp to message foo', async () => {
+		await Privileges.global.give(['chat:privileged'], 'registered-users');
+		// ensure the privilege group list key is populated (group-privilege grant path)
+		const key = `group:cid:0:privileges:groups:chat:privileged:members`;
+		if (!(await db.isSortedSetMember(key, 'registered-users'))) {
+			await db.sortedSetAdd(key, Date.now(), 'registered-users');
+		}
+		// clear stale membership caches for all test users
+		[1, 2, 3, 4, 5].forEach(u => Groups.cache.del([`${u}:cid:0:privileges:groups:chat:privileged`]));
+		// verify the privilege is actually effective before attempting the message
+		const can = await Privileges.global.can('chat:privileged', mocks.herp.uid);
+		assert.strictEqual(can, true, 'chat:privileged should be effective for herp after grant');
+		await messaging.canMessageUser(mocks.herp.uid, mocks.foo.uid);
+	});
+
+	it('POST /api/v3/chats to privileged target fails with no-privileges', async () => {
