+}
+
+/**
+ * Displays a device/session's name (its display name, or its device id when no
+ * display name has been set) and lets the user rename it inline.
+ *
+ * Triggering the rename action swaps the read view for an editable form with a
+ * Save / Cancel pair. Saving only persists the name when it has actually
+ * changed (an empty string is a valid value); on success the new name is shown
+ * immediately and the form closes. Cancelling restores the original view.
+ */
+const DeviceDetailHeading: React.FC<Props> = ({ device, saveDeviceName }) => {
+    const [isEditing, setIsEditing] = useState(false);
+    const [draftName, setDraftName] = useState<string | undefined>(device.display_name);
+    const [isSaving, setIsSaving] = useState(false);
+    const [error, setError] = useState<string | undefined>();
+    const inputRef = useRef<HTMLInputElement>(null);
+
+    const deviceName = device.display_name ?? device.device_id;
+    const isNameDirty = (draftName ?? '') !== (device.display_name ?? '');
+
+    const onRenameClick = (): void => {
+        setError(undefined);
+        setDraftName(device.display_name);
+        setIsEditing(true);
+    };
+
+    const onCancel = (): void => {
+        setError(undefined);
+        setIsEditing(false);
+    };
+
+    const onSave = async (): Promise<void> => {
+        if (isSaving) {
+            return;
+        }
+        // only persist when the name actually changed; an empty string is valid
+        if (!isNameDirty) {
+            onCancel();
+            return;
+        }
+        setIsSaving(true);
+        setError(undefined);
+        try {
+            await saveDeviceName(device.device_id, draftName ?? '');
+            setIsEditing(false);
+        } catch (e) {
+            logger.error("Error saving device display name", e);
+            setError(_t('Failed to set display name.'));
+        } finally {
+            setIsSaving(false);
+        }
+    };
+
+    if (isEditing) {
+        return <div className="mx_DeviceDetailHeading" data-testid="device-detail-heading-edit">
+            <form onSubmit={(e) => { e.preventDefault(); void onSave(); }}>
+                <Field
+                    label={_t('Display Name')}
+                    type="text"
+                    maxLength={MAX_DEVICE_NAME_LENGTH}
+                    value={draftName ?? ''}
+                    inputRef={inputRef}
+                    data-testid="device-detail-heading-input"
+                    onChange={(ev) => {
+                        setDraftName((ev.target as HTMLInputElement).value);
+                        setError(undefined);
+                    }}
+                    autoFocus
+                />
+                <p className="mx_DeviceDetailHeading_notice" data-testid="device-detail-heading-visibility">
+                    { _t('Session names may be visible to other people you communicate with.') }
+                </p>
+                { error &&
+                    <p className="mx_DeviceDetailHeading_error" data-testid="device-detail-heading-error">
+                        { error }
+                    </p>
+                }
+                <div className="mx_DeviceDetailHeading_actions">
+                    <AccessibleButton
+                        kind="primary_sm"
+                        onClick={onSave}
+                        disabled={isSaving}
+                        data-testid="device-detail-heading-save"
+                    >
+                        { isSaving
+                            ? <Spinner w={16} h={16} />
+                            : _t('Save') }
+                    </AccessibleButton>
+                    <AccessibleButton
+                        kind="cancel_sm"
+                        onClick={onCancel}
+                        disabled={isSaving}
+                        data-testid="device-detail-heading-cancel"
+                    >
+                        { _t('Cancel') }
+                    </AccessibleButton>
+                </div>
+            </form>
+        </div>;
+    }
+
+    return <div className="mx_DeviceDetailHeading" data-testid="device-detail-heading-read">
+        <div className="mx_DeviceDetailHeading_nameContainer">
+            <Heading size="h3" data-testid="device-detail-heading-name">{ deviceName }</Heading>
+            <AccessibleButton
+                kind="link_inline"
+                onClick={onRenameClick}
+                data-testid="device-detail-heading-rename"
+            >
+                { _t('Rename') }
+            </AccessibleButton>
+        </div>
+    </div>;
+};
+
+export default DeviceDetailHeading;
