+import React from 'react';
+import { render } from '@testing-library/react';
+
+import { useOwnDevices } from '../../../../../src/components/views/settings/devices/useOwnDevices';
+import MatrixClientContext from '../../../../../src/contexts/MatrixClientContext';
+import { flushPromises, getMockClientWithEventEmitter, mockClientMethodsUser } from '../../../../test-utils';
+
+describe('useOwnDevices', () => {
+    const aliceId = '@alice:domain';
+    const deviceId = 'some_device';
+
+    const mockClient = getMockClientWithEventEmitter({
+        ...mockClientMethodsUser(aliceId),
+        getStoredCrossSigningForUser: jest.fn().mockReturnValue(null),
+        getDevices: jest.fn().mockResolvedValue({ devices: [] }),
+        getDeviceId: jest.fn().mockReturnValue(deviceId),
+        setDeviceDetails: jest.fn().mockResolvedValue({}),
+    });
+
+    // Renders nothing and hands the hook's result out for assertion.
+    const HookConsumer = ({ onResult }: { onResult: (r: ReturnType<typeof useOwnDevices>) => void }) => {
+        const result = useOwnDevices();
+        onResult(result);
+        return null;
+    };
+
+    const renderHook = () => {
+        let result!: ReturnType<typeof useOwnDevices>;
+        render(
+            <MatrixClientContext.Provider value={mockClient}>
+                <HookConsumer onResult={(r) => { result = r; }} />
+            </MatrixClientContext.Provider>,
+        );
+        return { result };
+    };
+
+    beforeEach(() => {
+        jest.clearAllMocks();
+        mockClient.getDevices.mockResolvedValue({ devices: [] });
+        mockClient.setDeviceDetails.mockResolvedValue({});
+    });
+
+    it('exposes saveDeviceName with the expected signature', async () => {
+        const { result } = renderHook();
+        await flushPromises();
+        expect(result.saveDeviceName).toBeDefined();
+        expect(typeof result.saveDeviceName).toEqual('function');
+    });
+
+    it('persists the new name via setDeviceDetails', async () => {
+        const { result } = renderHook();
+        await flushPromises();
+
+        await result.saveDeviceName(deviceId, 'Work Laptop');
+
+        expect(mockClient.setDeviceDetails).toHaveBeenCalledWith(deviceId, { display_name: 'Work Laptop' });
+    });
+
+    it('propagates an error with a clear message when the save fails', async () => {
+        mockClient.setDeviceDetails.mockRejectedValue(new Error('network down'));
+        const { result } = renderHook();
+        await flushPromises();
+
+        await expect(result.saveDeviceName(deviceId, 'Work Laptop'))
+            .rejects
+            .toThrow('Failed to set display name.');
+    });
+});

