+import React from "react";
+import { act } from "react-dom/test-utils";
+// eslint-disable-next-line deprecate/import
+import { mount, ReactWrapper } from "enzyme";
+import { AuthType } from "matrix-js-sdk/src/interactive-auth";
+
+import getEntryComponentForLoginType, {
+    DEFAULT_PHASE,
+    RegistrationTokenAuthEntry,
+} from "../../../../src/components/views/auth/InteractiveAuthEntryComponents";
+import { getMockClientWithEventEmitter, unmockClientPeg } from "../../../test-utils";
+
+describe("RegistrationTokenAuthEntry", function () {
+    const mockClient = getMockClientWithEventEmitter({});
+
+    const defaultProps = {
+        matrixClient: mockClient,
+        loginType: AuthType.RegistrationToken,
+        authSessionId: "sess",
+        submitAuthDict: jest.fn(),
+        onPhaseChange: jest.fn(),
+    };
+
+    const getComponent = (props = {}): ReactWrapper =>
+        mount(<RegistrationTokenAuthEntry {...defaultProps} {...props} />);
+
+    beforeEach(function () {
+        jest.clearAllMocks();
+    });
+
+    afterAll(() => {
+        unmockClientPeg();
+    });
+
+    it("should be registered as the entry component for the stable login type", () => {
+        expect(getEntryComponentForLoginType(AuthType.RegistrationToken)).toBe(RegistrationTokenAuthEntry);
+    });
+
+    it("should be registered as the entry component for the unstable login type", () => {
+        expect(getEntryComponentForLoginType(AuthType.UnstableRegistrationToken)).toBe(RegistrationTokenAuthEntry);
+    });
+
+    it("should expose the stable login type", () => {
+        expect(RegistrationTokenAuthEntry.LOGIN_TYPE).toBe(AuthType.RegistrationToken);
+    });
+
+    it("should notify the default phase on mount", () => {
+        getComponent();
+        expect(defaultProps.onPhaseChange).toHaveBeenCalledWith(DEFAULT_PHASE);
+    });
+
+    it("should render a token field, label and help text", () => {
+        const wrapper = getComponent();
+        expect(wrapper.find('input[name="registrationTokenField"]')).toHaveLength(1);
+        expect(wrapper.find("label").text()).toBe("Registration token");
+        expect(wrapper.text()).toContain("Enter a registration token provided by the homeserver administrator.");
+    });
+
+    it("should auto-focus the token field", () => {
+        const wrapper = getComponent();
+        expect(wrapper.find('input[name="registrationTokenField"]').props().autoFocus).toBe(true);
+    });
+
+    it("should render a primary accessible button, disabled while empty", () => {
+        const wrapper = getComponent();
+        const button = wrapper.find("AccessibleButton").filterWhere((n) => n.prop("kind") === "primary");
+        expect(button).toHaveLength(1);
+        expect(button.props().disabled).toBe(true);
+    });
+
+    it("should not submit while the field is empty", () => {
+        const wrapper = getComponent();
+        act(() => {
+            wrapper.find("form").simulate("submit");
+        });
+        expect(defaultProps.submitAuthDict).not.toHaveBeenCalled();
+    });
+
+    it("should enable the button and submit {type, token} when a value is entered", () => {
+        const wrapper = getComponent();
+        act(() => {
+            wrapper.find('input[name="registrationTokenField"]').simulate("change", { target: { value: "my-token" } });
+        });
+        wrapper.update();
+        expect(
+            wrapper
+                .find("AccessibleButton")
+                .filterWhere((n) => n.prop("kind") === "primary")
+                .props().disabled,
+        ).toBe(false);
+
+        act(() => {
+            wrapper.find("form").simulate("submit");
+        });
+
+        // type should be the login type advertised by the server, session is handled upstream
+        expect(defaultProps.submitAuthDict).toHaveBeenCalledTimes(1);
+        expect(defaultProps.submitAuthDict).toHaveBeenCalledWith({
+            type: AuthType.RegistrationToken,
+            token: "my-token",
+        });
+    });
+
+    it("should submit using the unstable type when the server advertised it", () => {
+        const wrapper = getComponent({ loginType: AuthType.UnstableRegistrationToken });
+        act(() => {
+            wrapper.find('input[name="registrationTokenField"]').simulate("change", { target: { value: "tok" } });
+        });
+        act(() => {
+            wrapper.find("form").simulate("submit");
+        });
+        expect(defaultProps.submitAuthDict).toHaveBeenCalledWith({
+            type: AuthType.UnstableRegistrationToken,
+            token: "tok",
+        });
+    });
+
+    it("should show a spinner and block duplicate submissions while busy", () => {
+        const wrapper = getComponent({ busy: true });
+        expect(wrapper.find("Spinner")).toHaveLength(1);
+        expect(wrapper.find("AccessibleButton").filterWhere((n) => n.prop("kind") === "primary")).toHaveLength(0);
+
+        act(() => {
+            wrapper.find("form").simulate("submit");
+        });
+        expect(defaultProps.submitAuthDict).not.toHaveBeenCalled();
+    });
+
+    it("should display the error text with role=alert", () => {
+        const wrapper = getComponent({ errorText: "Token rejected" });
+        const error = wrapper.find('div[role="alert"]');
+        expect(error).toHaveLength(1);
+        expect(error.hasClass("error")).toBe(true);
+        expect(error.text()).toBe("Token rejected");
+    });
+});

