new file mode 100644
index 0000000000..3bd197aab5
--- /dev/null
+++ b/src/components/views/rooms/EventPreview.tsx
@@ -0,0 +1,173 @@
+/*
+Copyright 2025 New Vector Ltd.
+Copyright 2025 The Matrix.org Foundation C.I.C.
+
+SPDX-License-Identifier: AGPL-3.0-only OR GPL-3.0-only
+Please see LICENSE files in the repository root for full details.
+*/
+
+import React, { JSX, useEffect, useMemo, useRef, useState } from "react";
+import classNames from "classnames";
+import { M_POLL_START, MatrixEvent, MatrixEventEvent, MsgType } from "matrix-js-sdk/src/matrix";
+
+import { _t } from "../../../languageHandler";
+import { useAsyncMemo } from "../../../hooks/useAsyncMemo";
+import MatrixClientContext from "../../../contexts/MatrixClientContext";
+import { MessagePreviewStore } from "../../../stores/room-list/MessagePreviewStore";
+
+/**
+ * A preview for a matrix event, with an optional prefix (e.g. "Image", "Audio").
+ */
+export type Preview = [preview: string, prefix: string | null];
+
+/**
+ * The props for the {@link EventPreview} component.
+ */
+export interface EventPreviewProps extends Omit<React.HTMLAttributes<HTMLSpanElement>, "children"> {
+    /**
+     * The event to preview.
+     */
+    mxEvent: MatrixEvent;
+}
+
+/**
+ * The props for the {@link EventPreviewTile} component.
+ */
+export interface EventPreviewTileProps extends React.HTMLAttributes<HTMLSpanElement> {
+    /**
+     * The preview to display.
+     */
+    preview: Preview;
+}
+
+/**
+ * A component that displays a preview string along with an optional prefix in a styled span.
+ * @param props The props for the component.
+ * @returns The rendered React element (a `<span>`) or `null`.
+ */
+export function EventPreviewTile({ preview, className, ...props }: EventPreviewTileProps): JSX.Element | null {
+    if (!preview) return null;
+    const [previewText, prefix] = preview;
+    if (!previewText) return null;
+
+    return (
+        <span className={classNames("mx_EventPreview", className)} {...props}>
+            {prefix && (
+                <span className="mx_EventPreview_prefix">
+                    {prefix}:{" "}
+                </span>
+            )}
+            <span className="mx_EventPreview_text">{previewText}</span>
+        </span>
+    );
+}
+
+/**
+ * A component that renders a message preview with an optional type prefix for a given event.
+ * @param props The props for the component.
+ * @returns The rendered preview component or null if no preview is available.
+ */
+export function EventPreview({ mxEvent, className, ...props }: EventPreviewProps): JSX.Element | null {
+    const preview = useEventPreview(mxEvent);
+    if (!preview) return null;
+    return <EventPreviewTile preview={preview} className={className} {...props} />;
+}
+
+/**
+ * Get the prefix for the preview based on the type and the message type of the event.
+ * Plain text and sticker events are not prefixed.
+ * @param mxEvent The event to get the prefix for.
+ * @returns The prefix, or null if the event should not be prefixed.
+ */
+export function getPreviewPrefix(mxEvent: MatrixEvent): string | null {
+    switch (mxEvent.getType()) {
+        case M_POLL_START.name:
+        case M_POLL_START.altName:
+            return _t("event_preview|prefix|poll");
+    }
+
+    switch (mxEvent.getContent().msgtype as MsgType) {
+        case MsgType.Audio:
+            return _t("event_preview|prefix|audio");
+        case MsgType.Image:
+            return _t("event_preview|prefix|image");
+        case MsgType.Video:
+            return _t("event_preview|prefix|video");
+        case MsgType.File:
+            return _t("event_preview|prefix|file");
+        default:
+            return null;
+    }
+}
+
+/**
+ * Generate the preview text for an event, returning null if no preview can be generated.
+ */
+function generatePreviewForEvent(mxEvent: MatrixEvent): string | null {
+    if (mxEvent.isRedacted() || mxEvent.isDecryptionFailure()) return null;
+    const text = MessagePreviewStore.instance.generatePreviewForEvent(mxEvent);
+    return text || null;
+}
+
+/**
+ * A hook that generates a preview string and an optional message type prefix for a given event.
+ * The preview is automatically updated when the event is replaced, decrypted, or its content is edited.
+ * Uses `useAsyncMemo` to defer expensive operations like decryption and preview generation.
+ * @param mxEvent The event object for which to generate the preview.
+ * @returns A tuple of the preview text and an optional prefix, or null if no preview can be generated.
+ */
+export function useEventPreview(mxEvent: MatrixEvent | undefined): Preview | null {
+    const cli = React.useContext(MatrixClientContext);
+    const eventId = mxEvent?.getId();
+
+    // Compute the preview synchronously from the current event state.
+    // This ensures the preview is always correct on first render and when the event changes.
+    const syncPreview = useMemo<Preview | null>(() => {
+        if (!mxEvent) return null;
+        const text = generatePreviewForEvent(mxEvent);
+        if (!text) return null;
+        return [text, getPreviewPrefix(mxEvent)];
+    }, [eventId]); // eslint-disable-line react-hooks/exhaustive-deps
+
+    // Track whether the event's content has changed since the last sync computation.
+    // This triggers a re-run of the async memo to pick up edits/decryption.
+    const [contentVersion, setContentVersion] = useState(0);
+    const prevEventRef = useRef<MatrixEvent | undefined>(undefined);
+    useEffect(() => {
+        // When the event changes, bump the version to force async recompute
+        if (prevEventRef.current !== mxEvent) {
+            prevEventRef.current = mxEvent;
+            setContentVersion((v) => v + 1);
+        }
+        if (!mxEvent) return;
+        const onContentChange = (): void => {
+            setContentVersion((v) => v + 1);
+        };
+        mxEvent.on(MatrixEventEvent.Replaced, onContentChange);
+        mxEvent.on(MatrixEventEvent.Decrypted, onContentChange);
+        return () => {
+            mxEvent.removeListener(MatrixEventEvent.Replaced, onContentChange);
+            mxEvent.removeListener(MatrixEventEvent.Decrypted, onContentChange);
+        };
+    }, [mxEvent]);
+
+    // Use useAsyncMemo to defer expensive operations (decryption + preview generation).
+    // The sync preview is used as the initial/fallback value so the UI is never blank.
+    const preview = useAsyncMemo<Preview | null>(
+        async () => {
+            if (!mxEvent || mxEvent.isRedacted() || mxEvent.isDecryptionFailure()) return null;
+            await cli?.decryptEventIfNeeded(mxEvent);
+            const text = MessagePreviewStore.instance.generatePreviewForEvent(mxEvent);
+            if (!text) return null;
+            return [text, getPreviewPrefix(mxEvent)];
+        },
+        [mxEvent, contentVersion],
+        syncPreview,
+    );
+
+    // Always prefer the sync preview when it is available, as it is computed
+    // from the current event state and is never stale. The async preview only
+    // adds value after decryption completes for encrypted events.
+    if (syncPreview) return syncPreview;
+    return preview;
+}
