+import { logger } from 'matrix-js-sdk/src/logger';
+
+import { handleEvent } from '../src/legacy/LegacyCallHandler/handleEvent';
+import SettingsStore from '../src/settings/SettingsStore';
+
+function evt(type: string, el: HTMLMediaElement): Event {
+    const e = new Event(type);
+    Object.defineProperty(e, 'target', { value: el });
+    return e;
+}
+
+describe('handleEvent', () => {
+    let el: HTMLMediaElement;
+
+    beforeEach(() => {
+        el = { id: 'ringAudio' } as unknown as HTMLMediaElement;
+        // keep the real logger but make it quiet; we spy on it below
+        logger.setLevel(0); // TRACE - allow all, but our spies swallow the output
+    });
+
+    afterEach(() => {
+        jest.restoreAllMocks();
+    });
+
+    it('logs a structured error (with the element id) for error-class events', () => {
+        const errorSpy = jest.spyOn(logger, 'error').mockImplementation(() => {});
+        handleEvent(evt('error', el));
+        expect(errorSpy).toHaveBeenCalledTimes(1);
+        expect(errorSpy.mock.calls[0][0]).toContain('ringAudio');
+    });
+
+    it('ignores event types that are neither error- nor debug-class', () => {
+        const errorSpy = jest.spyOn(logger, 'error').mockImplementation(() => {});
+        const debugSpy = jest.spyOn(logger, 'debug').mockImplementation(() => {});
+        handleEvent(evt('some-unknown-type', el));
+        expect(errorSpy).not.toHaveBeenCalled();
+        expect(debugSpy).not.toHaveBeenCalled();
+    });
+
+    it('does not log debug-class events when the debug setting is off', () => {
+        const debugSpy = jest.spyOn(logger, 'debug').mockImplementation(() => {});
+        jest.spyOn(SettingsStore, 'getValue').mockReturnValue(false);
+        handleEvent(evt('pause', el));
+        expect(debugSpy).not.toHaveBeenCalled();
+    });
+
+    it('logs debug-class events (with the element id) when the debug setting is on', () => {
+        const debugSpy = jest.spyOn(logger, 'debug').mockImplementation(() => {});
+        jest.spyOn(SettingsStore, 'getValue').mockReturnValue(true);
+        handleEvent(evt('pause', el));
+        expect(debugSpy).toHaveBeenCalledTimes(1);
+        expect(debugSpy.mock.calls[0][0]).toContain('ringAudio');
+    });
+});

