@@ -0,0 +1,119 @@
+import React from "react";
+import { render, screen, fireEvent, waitFor } from "@testing-library/react";
+
+import ExportE2eKeysDialog from "../src/async-components/views/dialogs/security/ExportE2eKeysDialog";
+import { createTestClient } from "./test-utils";
+import FileSaver from "file-saver";
+
+const mockSaveAs = jest.fn();
+
+jest.mock("file-saver", () => ({
+    saveAs: (...args) => mockSaveAs(...args),
+}));
+
+const NEW_PARAGRAPH =
+    "The exported file will allow anyone who can read it to decrypt any encrypted messages that you can " +
+    "see, so you should be careful to keep it secure. To help with this, you should enter a unique " +
+    "passphrase below, which will only be used to encrypt the exported data. It will only be possible " +
+    "to import the data by using the same passphrase.";
+
+function renderDialog(exportRoomKeysImpl = jest.fn().mockResolvedValue({})) {
+    const matrixClient = {
+        ...createTestClient(),
+        exportRoomKeys: exportRoomKeysImpl,
+    };
+    const onFinished = jest.fn();
+    const utils = render(<ExportE2eKeysDialog matrixClient={matrixClient} onFinished={onFinished} />);
+    const inputs = Array.from(utils.container.querySelectorAll('input[type="password"]')) as HTMLInputElement[];
+    return { matrixClient, onFinished, utils, inputs };
+}
+
+function getFields(container) {
+    return container.querySelectorAll('input[type="password"]');
+}
+
+describe("ExportE2eKeysDialog (verification)", () => {
+    beforeEach(() => {
+        mockSaveAs.mockClear();
+        jest.clearAllMocks();
+    });
+
+    it("renders the verbatim explanatory paragraph via i18n", () => {
+        renderDialog();
+        expect(screen.getByText(NEW_PARAGRAPH)).toBeInTheDocument();
+    });
+
+    it("shows labels 'Enter passphrase' and 'Confirm passphrase'", () => {
+        renderDialog();
+        expect(screen.getByLabelText("Enter passphrase")).toBeInTheDocument();
+        expect(screen.getByLabelText("Confirm passphrase")).toBeInTheDocument();
+    });
+
+    it("submit button is present and enabled by default (not disabled)", () => {
+        const { utils } = renderDialog();
+        const submit = utils.container.querySelector('input[type="submit"]');
+        expect(submit).toBeTruthy();
+        expect(submit).not.toBeDisabled();
+        expect(submit).toHaveValue("Export");
+    });
+
+    it("does not export when both passphrases are empty", async () => {
+        const { matrixClient, onFinished } = renderDialog();
+        const { utils } = { utils: renderDialog().utils };
+        fireEvent.click(utils.container.querySelector('input[type="submit"]')!);
+        await waitFor(() => expect(matrixClient.exportRoomKeys).not.toHaveBeenCalled());
+        expect(onFinished).not.toHaveBeenCalled();
+    });
+
+    it("blocks export for a weak/top-10 passphrase and shows the top-10 warning", async () => {
+        const { matrixClient, onFinished, utils, inputs } = renderDialog();
+        fireEvent.change(inputs[0], { target: { value: "password" } });
+        fireEvent.change(inputs[1], { target: { value: "password" } });
+        // allow debounced + async zxcvbn validation to settle
+        await waitFor(() => expect(screen.getByText("This is a top-10 common password")).toBeInTheDocument());
+        fireEvent.click(utils.container.querySelector('input[type="submit"]')!);
+        await new Promise((r) => setTimeout(r, 50));
+        expect(matrixClient.exportRoomKeys).not.toHaveBeenCalled();
+        expect(onFinished).not.toHaveBeenCalled();
+    });
+
+    it("shows 'Passphrases must match' for mismatched entries and blocks export", async () => {
+        const { matrixClient, onFinished, utils, inputs } = renderDialog();
+        fireEvent.change(inputs[0], { target: { value: "Str0ng!Passphrase" } });
+        fireEvent.change(inputs[1], { target: { value: "Str0ng!Passphr4se" } });
+        await new Promise((r) => setTimeout(r, 300));
+        // Focus the confirm field so its error tooltip is rendered.
+        fireEvent.focus(inputs[1]);
+        await new Promise((r) => setTimeout(r, 100));
+        expect(screen.getByText("Passphrases must match")).toBeInTheDocument();
+        fireEvent.click(utils.container.querySelector('input[type="submit"]')!);
+        await new Promise((r) => setTimeout(r, 50));
+        expect(matrixClient.exportRoomKeys).not.toHaveBeenCalled();
+        expect(onFinished).not.toHaveBeenCalled();
+    });
+
+    it("shows 'Passphrase must not be empty' when confirm is empty and blocks export", async () => {
+        const { matrixClient, onFinished, utils, inputs } = renderDialog();
+        fireEvent.change(inputs[0], { target: { value: "Str0ng!Passphrase" } });
+        // leave confirm empty
+        await new Promise((r) => setTimeout(r, 300));
+        fireEvent.click(utils.container.querySelector('input[type="submit"]')!);
+        await new Promise((r) => setTimeout(r, 100));
+        expect(matrixClient.exportRoomKeys).not.toHaveBeenCalled();
+        expect(onFinished).not.toHaveBeenCalled();
+    });
+
+    it("performs the export when all checks pass (strong + matching)", async () => {
+        const keys = { sessions: {}, groups: {} };
+        const { matrixClient, onFinished, utils, inputs } = renderDialog(jest.fn().mockResolvedValue(keys));
+        const strong = "Cor!ng#2024-Str0ngPassphrase";
+        fireEvent.change(inputs[0], { target: { value: strong } });
+        fireEvent.change(inputs[1], { target: { value: strong } });
+        await new Promise((r) => setTimeout(r, 300));
+        fireEvent.click(utils.container.querySelector('input[type="submit"]')!);
+        await waitFor(() => expect(matrixClient.exportRoomKeys).toHaveBeenCalledTimes(1));
+        // In jsdom window.crypto.subtle is unavailable, so the MegolmExportEncryption
+        // step can't complete; we only assert that the export pipeline was reached.
+        expect(onFinished).not.toHaveBeenCalled();
+    });
+});

