+import { TypedEventEmitter, ListenerMap } from "matrix-js-sdk/src/models/typed-event-emitter";
+import { MatrixClient } from "matrix-js-sdk/src/client";
+import { MatrixEvent } from "matrix-js-sdk/src/models/event";
+import { RelationType } from "matrix-js-sdk/src/matrix";
+import { RoomEvent } from "matrix-js-sdk/src/models/room";
+import { RoomStateEvent } from "matrix-js-sdk/src/models/room-state";
+
+import type { Room } from "matrix-js-sdk/src/models/room";
+import {
+    VoiceBroadcastInfoEventContent,
+    VoiceBroadcastInfoEventType,
+    VoiceBroadcastInfoState,
+} from "..";
+
+export enum VoiceBroadcastRecordingEvent {
+    StateChanged = "voice_broadcast_recording_state_changed",
+}
+
+interface VoiceBroadcastRecordingEventHandlerMap extends ListenerMap<VoiceBroadcastRecordingEvent> {
+    [VoiceBroadcastRecordingEvent.StateChanged]: (
+        recording: VoiceBroadcastRecording,
+        prev: VoiceBroadcastInfoState,
+        next: VoiceBroadcastInfoState,
+    ) => void;
+}
+
+/**
+ * A voice broadcast recording.
+ *
+ * A `VoiceBroadcastRecording` represents the lifecycle and state of a single
+ * voice broadcast, which is initiated by a "started" info state event and
+ * terminated by a "stopped" info state event that references the former.
+ */
+export class VoiceBroadcastRecording
+    extends TypedEventEmitter<VoiceBroadcastRecordingEvent, VoiceBroadcastRecordingEventHandlerMap> {
+    private _state: VoiceBroadcastInfoState;
+
+    /**
+     * @param client The matrix client.
+     * @param infoEvent The info state event that initiated the broadcast.
+     * @param state The initial state of the broadcast.
+     */
+    constructor(
+        private readonly client: MatrixClient,
+        private readonly infoEvent: MatrixEvent,
+        state: VoiceBroadcastInfoState = VoiceBroadcastInfoState.Started,
+    ) {
+        super();
+        this._state = state;
+    }
+
+    /**
+     * The ID of the room in which the broadcast is being recorded.
+     */
+    public get roomId(): string {
+        return this.infoEvent.getRoomId()!;
+    }
+
+    /**
+     * The ID of the info state event that initiated the broadcast.
+     */
+    public get id(): string {
+        return this.infoEvent.getId();
+    }
+
+    /**
+     * The room in which the broadcast is being recorded.
+     */
+    public get room(): Room {
+        return this.client.getRoom(this.roomId)!;
+    }
+
+    /**
+     * The current state of the broadcast.
+     */
+    public get state(): VoiceBroadcastInfoState {
+        return this._state;
+    }
+
+    /**
+     * Whether the broadcast is currently live (not stopped).
+     */
+    public get isLive(): boolean {
+        return this.state !== VoiceBroadcastInfoState.Stopped;
+    }
+
+    /**
+     * Gets the room ID of the room in which the broadcast is being recorded.
+     * @returns The room ID.
+     */
+    public getRoomId(): string {
+        return this.roomId;
+    }
+
+    /**
+     * Gets the ID of the info state event that initiated the broadcast.
+     * @returns The info event ID.
+     */
+    public getId(): string {
+        return this.id;
+    }
+
+    /**
+     * Subscribes the recording to the room's current state updates so that its
+     * state stays in sync with the latest info state event in the room.
+     */
+    public subscribe(): void {
+        const room = this.room;
+        room.on(RoomEvent.CurrentStateUpdated, this.onRoomStateUpdated);
+        room.currentState?.on(RoomStateEvent.Update, this.onRoomStateUpdated);
+        this.onRoomStateUpdated();
+    }
+
+    /**
+     * Unsubscribes the recording from the room's current state updates.
+     */
+    public unsubscribe(): void {
+        const room = this.room;
+        room.off(RoomEvent.CurrentStateUpdated, this.onRoomStateUpdated);
+        room.currentState?.off(RoomStateEvent.Update, this.onRoomStateUpdated);
+    }
+
+    private onRoomStateUpdated = (): void => {
+        const state = this.room.currentState
+            ?.getStateEvents(VoiceBroadcastInfoEventType, this.client.getUserId()!)
+            ?.getContent<VoiceBroadcastInfoEventContent>()
+            ?.state;
+        if (state && state !== this._state) {
+            this.setState(state);
+        }
+    };
+
+    private setState(state: VoiceBroadcastInfoState): void {
+        const prev = this._state;
+        this._state = state;
+        this.emit(VoiceBroadcastRecordingEvent.StateChanged, this, prev, state);
+    }
+
+    /**
+     * Stops the broadcast by sending a "stopped" info state event to the room,
+     * referencing the original info event, and updating the recording's state.
+     * @returns A promise that resolves once the stop event has been sent.
+     */
+    public async stop(): Promise<void> {
+        await this.client.sendStateEvent(
+            this.roomId,
+            VoiceBroadcastInfoEventType,
+            {
+                state: VoiceBroadcastInfoState.Stopped,
+                ["m.relates_to"]: {
+                    rel_type: RelationType.Reference,
+                    event_id: this.getId(),
+                },
+            } as VoiceBroadcastInfoEventContent,
+            this.client.getUserId()!,
+        );
+        this.setState(VoiceBroadcastInfoState.Stopped);
+    }
+}
