+import { MatrixClient } from "matrix-js-sdk/src/client";
+import { MatrixEvent } from "matrix-js-sdk/src/models/event";
+import { RoomEvent } from "matrix-js-sdk/src/models/room";
+import { RoomStateEvent } from "matrix-js-sdk/src/models/room-state";
+
+import type { Room } from "matrix-js-sdk/src/models/room";
+import type { RoomState } from "matrix-js-sdk/src/models/room-state";
+import {
+    VoiceBroadcastInfoEventContent,
+    VoiceBroadcastInfoEventType,
+    VoiceBroadcastInfoState,
+} from "..";
+import type { VoiceBroadcastRecording } from "../models";
+import { VoiceBroadcastRecordingsStore } from "../stores";
+
+/**
+ * The default length of each voice broadcast chunk, in milliseconds.
+ */
+const CHUNK_LENGTH_MS = 42;
+
+/**
+ * Starts a new voice broadcast in the given room.
+ *
+ * Sends the initial "started" info state event, waits until it appears in the
+ * room's current state, then creates a {@link VoiceBroadcastRecording} for it,
+ * sets it as the current recording in the store, and returns it.
+ * @param client The matrix client.
+ * @param roomId The ID of the room to start the broadcast in.
+ * @returns The newly created {@link VoiceBroadcastRecording}.
+ */
+export async function startNewVoiceBroadcastRecording(
+    client: MatrixClient,
+    roomId: string,
+): Promise<VoiceBroadcastRecording> {
+    const room: Room = client.getRoom(roomId)!;
+    const roomState: RoomState = room.currentState!;
+    const userId = client.getUserId()!;
+
+    // Resolves the recording for a given info state event: caches (or reuses)
+    // the recording in the store and sets it as the current recording.
+    const resolveRecording = (infoEvent: MatrixEvent): VoiceBroadcastRecording => {
+        const recording = VoiceBroadcastRecordingsStore.instance.getOrCreateRecording(
+            client,
+            infoEvent,
+            VoiceBroadcastInfoState.Started,
+        );
+        VoiceBroadcastRecordingsStore.instance.setCurrent(recording);
+        return recording;
+    };
+
+    // If the broadcast was already started (e.g. local echo), use the existing
+    // info state event rather than sending a duplicate.
+    const existing = roomState.getStateEvents(VoiceBroadcastInfoEventType, userId);
+    if (existing) return resolveRecording(existing);
+
+    // Subscribe to the room's current state updates so we can detect once the
+    // initial info state event has landed.
+    const onCurrentStateUpdated = (_room: Room, _prev: RoomState, state: RoomState): void =>
+        checkInfoEvent(state);
+    const onRoomStateUpdated = (state: RoomState): void =>
+        checkInfoEvent(state);
+
+    let resolvePromise: (recording: VoiceBroadcastRecording) => void;
+    const finished = new Promise<VoiceBroadcastRecording>(res => resolvePromise = res);
+
+    const checkInfoEvent = (state: RoomState): void => {
+        const infoEvent = state.getStateEvents(VoiceBroadcastInfoEventType, userId);
+        if (!infoEvent) return;
+        cleanup();
+        resolvePromise(resolveRecording(infoEvent));
+    };
+
+    const cleanup = (): void => {
+        room.off(RoomEvent.CurrentStateUpdated, onCurrentStateUpdated);
+        roomState.off(RoomStateEvent.Update, onRoomStateUpdated);
+    };
+
+    room.on(RoomEvent.CurrentStateUpdated, onCurrentStateUpdated);
+    roomState.on(RoomStateEvent.Update, onRoomStateUpdated);
+
+    // Send the initial "started" info state event.
+    await client.sendStateEvent(
+        roomId,
+        VoiceBroadcastInfoEventType,
+        {
+            state: VoiceBroadcastInfoState.Started,
+            chunk_length: CHUNK_LENGTH_MS,
+        } as VoiceBroadcastInfoEventContent,
+        userId,
+    );
+
+    // Wait for the state event to appear in the room's current state.
+    return finished;
+}

