+func TestCacheControlUnaryInterceptor_NoStore(t *testing.T) {
+	tests := []struct {
+		name   string
+		header string
+		want   bool
+	}{
+		{name: "no-store exact", header: "no-store", want: true},
+		{name: "case-insensitive NO-STORE", header: "NO-STORE", want: true},
+		{name: "mixed-case No-Store", header: "No-Store", want: true},
+		{name: "combined directives with no-store", header: "public, no-store, max-age=0", want: true},
+		{name: "combined directives without no-store", header: "public, max-age=0", want: false},
+		{name: "no-store trailing comma", header: "no-store, ", want: true},
+		{name: "other directive max-age", header: "max-age=60", want: false},
+		{name: "prefix no-store-cache should not match", header: "no-store-cache", want: false},
+	}
+
+	for _, tt := range tests {
+		t.Run(tt.name, func(t *testing.T) {
+			calls := 0
+			var ctxGot context.Context
+			handler := func(ctx context.Context, r interface{}) (interface{}, error) {
+				calls++
+				ctxGot = ctx
+				return "ok", nil
+			}
+
+			mdin := metadata.Pairs("cache-control", tt.header)
+			ctx := metadata.NewOutgoingContext(context.Background(), mdin)
+
+			got, err := CacheControlUnaryInterceptor(ctx, &struct{}{}, &grpc.UnaryServerInfo{}, handler)
+			require.NoError(t, err)
