+// validateDatabase validates the database configuration, either in URL or
+// key/value form. When both forms are present, the URL takes precedence.
+func (c *Config) ValidateDatabase() error {
+	// URL takes precedence over key/value fields
+	if c.Database.URL != "" {
+		return nil
+	}
+
+	if c.Database.Protocol == 0 {
+		return fmt.Errorf("%s cannot be empty when %s is not set", dbProtocol, dbURL)
+	}
+
+	if c.Database.Protocol == SQLite {
+		if c.Database.Name == "" {
+			return fmt.Errorf("%s cannot be empty when %s is not set", dbName, dbURL)
+		}
+		return nil
+	}
+
+	if c.Database.Host == "" {
+		return fmt.Errorf("%s cannot be empty when %s is not set", dbHost, dbURL)
+	}
+
+	if c.Database.Name == "" {
+		return fmt.Errorf("%s cannot be empty when %s is not set", dbName, dbURL)
