+// connectionURL returns the database connection URL for the configured
+// database. When a URL is explicitly set, it is returned as-is. Otherwise
+// the URL is built from the individual key/value fields.
+func (c *Config) ConnectionURL() (string, error) {
+	if c.Database.URL != "" {
+		return c.Database.URL, nil
+	}
+
+	protocol := c.Database.Protocol
+
+	// SQLite uses the name field as the file path
+	if protocol == SQLite {
+		return protocol.String() + ":" + c.Database.Name, nil
+	}
+
+	// default to the protocol's standard port when not set
+	port := c.Database.Port
+	if port == 0 {
+		port = defaultPorts[protocol]
+	}
+
+	authority := ""
+	if c.Database.User != "" {
+		if c.Database.Password != "" {
+			authority = url.UserPassword(c.Database.User, c.Database.Password).String()
+		} else {
+			authority = url.User(c.Database.User).String()
+		}
+		authority += "@"
+	}
+
+	return fmt.Sprintf("%s://%s%s:%d/%s",
+		protocol.String(),
+		authority,
+		c.Database.Host,
+		port,
+		c.Database.Name), nil
+}
