+
+// redact masks any credentials (user:pass@) in the given URL so that
+// sensitive values are never leaked in logs or error messages.
+func redact(rawurl string) string {
+	u, err := url.Parse(rawurl)
+	if err != nil {
+		return redactFallback(rawurl)
+	}
+
+	if u.User != nil {
+		u.User = url.UserPassword(u.User.Username(), "****")
+	}
+
+	return u.String()
+}
+
+// redactFallback masks credentials in a URL that could not be parsed.
+func redactFallback(rawurl string) string {
+	at := strings.LastIndex(rawurl, "@")
+	if at == -1 {
+		return rawurl
+	}
+
+	cred := rawurl[:at]
+	rest := rawurl[at:]
+
+	colon := strings.LastIndex(cred, ":")
+	if colon == -1 {
+		return rawurl
+	}
+
+	return cred[:colon+1] + "****" + rest
+}
