+// TestConnectionURLKeyValue verifies that a database configured with discrete
+// key/value fields yields the same connection target as the equivalent URL,
+// and that the derived URL parses to the correct driver, host and name.
+func TestConnectionURLKeyValue(t *testing.T) {
+	tests := []struct {
+		name    string
+		cfg     config.DatabaseConfig
+		wantURL string
+		wantDrv Driver
+		wantErr bool
+	}{
+		{
+			name: "postgres key/value",
+			cfg: config.DatabaseConfig{
+				Protocol: config.Postgres,
+				Host:     "localhost",
+				User:     "pguser",
+				Password: "pgpass",
+				Name:     "flipt",
+			},
+			wantURL: "postgres://pguser:***@localhost:5432/flipt",
+			wantDrv: Postgres,
+		},
+		{
+			name: "sqlite key/value",
+			cfg: config.DatabaseConfig{
+				Protocol: config.SQLite,
+				Name:     "flipt.db",
+			},
+			wantURL: "sqlite3:flipt.db",
+			wantDrv: SQLite,
+		},
+		{
+			name: "url takes precedence",
+			cfg: config.DatabaseConfig{
+				URL:      "postgres://pguser@localhost:***@localhost:5432/flipt",
+				Protocol: config.SQLite,
+				Name:     "ignored.db",
+			},
+			wantURL: "postgres://pguser@localhost:***@localhost:5432/flipt",
+			wantDrv: Postgres,
+		},
+	}
+
+	for _, tt := range tests {
+		t.Run(tt.name, func(t *testing.T) {
+			c := &config.Config{Database: tt.cfg}
+
+			require.NoError(t, c.ValidateDatabase())
+
+			got, err := c.ConnectionURL()
+			require.NoError(t, err)
+
+			if tt.wantErr {
+				require.Error(t, err)
+				return
+			}
+
+			// derive the driver the same way the real connection flow does
+			_, url, err := parse(got, false)
+			require.NoError(t, err)
+			assert.Equal(t, tt.wantDrv, urlToDriver(url))
+		})
+	}
+}
+
+// urlToDriver maps a parsed dburl URL to our Driver, mirroring the logic in
+// parse() so the test can assert the correct engine is selected.
+func urlToDriver(u *dburl.URL) Driver {
+	return stringToDriver[u.Driver]
+}
