+// IsTrivySupportedLib returns whether type is a library scan type that
+// Vuls can handle via trivy's library vulnerability DB.
+func IsTrivySupportedLib(family string) bool {
+	supportedLibs := []string{
+		ftypes.Bundler,
+		ftypes.Cargo,
+		ftypes.Composer,
+		ftypes.Npm,
+		ftypes.Yarn,
+		ftypes.Pipenv,
+		ftypes.Poetry,
+		ftypes.GoMod,
+	}
+	for _, supportedLib := range supportedLibs {
+		if family == supportedLib {
+			return true
+		}
+	}
+	return false
+}
