+// GetCveContentTypes maps an OS family to all of its corresponding CVE
+// content types. Some families (e.g. RedHat, Debian, Ubuntu) can have multiple
+// CVE content sources, so every source associated with the family is returned
+// in a stable order. If the family has no known mapping, nil is returned.
+//
+//	RedHat, CentOS, Alma, Rocky  -> [RedHat, RedHatAPI]
+//	Debian, Raspbian             -> [Debian, DebianSecurityTracker]
+//	Ubuntu                       -> [Ubuntu, UbuntuAPI]
+//	(unsupported families)       -> nil
+func GetCveContentTypes(family string) CveContentTypes {
+	switch family {
+	case "redhat", "centos", "alma", "rocky":
+		return CveContentTypes{RedHat, RedHatAPI}
+	case "debian", "raspbian":
+		return CveContentTypes{Debian, DebianSecurityTracker}
+	case "ubuntu":
+		return CveContentTypes{Ubuntu, UbuntuAPI}
+	}
+	return nil
+}
