+// portScanTimeout is the per-connection timeout used for the fast, low-noise
+// TCP reachability probe of listening endpoints.
+const portScanTimeout = 3 * time.Second
+
+// scanPortsSorted dials each "ip:port" destination with a short TCP timeout and
+// returns the confirmed-reachable destinations in a deterministic (sorted) order.
+// Destinations that do not accept a TCP connection are dropped.
+func (l *base) scanPortsSorted(dests []string) []string {
+	success := map[string]struct{}{}
+	for _, dest := range dests {
+		if conn, err := net.DialTimeout("tcp", dest, portScanTimeout); err == nil {
+			_ = conn.Close()
+			success[dest] = struct{}{}
+		}
+	}
+	sorted := make([]string, 0, len(success))
+	for d := range success {
+		sorted = append(sorted, d)
+	}
+	sort.Strings(sorted)
+	return sorted
