+	// and wildcard addresses ("*:80") are handled correctly.
+	if idx := strings.LastIndex(s, ":"); idx < 0 {
+		// No port component (no colon). Keep the whole string as the address.
+		lp.Address = s
+		return lp
+	} else {
+		lp.Address = s[:idx]
+		lp.Port = s[idx+1:]
+	}
