+func Test_base_updatePortStatus(t *testing.T) {
+	// Start a real in-process listener so updatePortStatus's TCP dial succeeds
+	// for 127.0.0.1:<port> but fails for a closed port.
+	ln, err := net.Listen("tcp", "127.0.0.1:0")
+	if err != nil {
+		t.Fatalf("failed to start listener: %v", err)
+	}
+	defer ln.Close()
+	openPort := fmt.Sprintf("%d", ln.Addr().(*net.TCPAddr).Port)
+	go func() {
+		for {
+			c, e := ln.Accept()
+			if e != nil {
+				return
+			}
+			_ = c.Close()
+		}
+	}()
+	// Find a port that is closed.
+	closedPort := openPort
+	{
+		ln2, _ := net.Listen("tcp", "127.0.0.1:0")
+		closedPort = fmt.Sprintf("%d", ln2.Addr().(*net.TCPAddr).Port)
+		ln2.Close()
+	}
+
+	l := &base{
+		ServerInfo: config.ServerInfo{IPv4Addrs: []string{"127.0.0.1"}},
+		osPackages: osPackages{
+			Packages: models.Packages{
+				"nginx": models.Package{
+					AffectedProcs: []models.AffectedProcess{
+						{PID: "1", Name: "nginx", ListenPorts: []models.ListenPort{
+							{Address: "*", Port: openPort},
+							{Address: "127.0.0.1", Port: closedPort},
+						}},
+					},
+				},
+			},
+		},
+	}
+	// detectScanDest derives "127.0.0.1:<openPort>" (wildcard expanded) and
+	// "127.0.0.1:<closedPort>" (concrete). Only the open one is reachable.
+	l.updatePortStatus(l.detectScanDest())
+
+	p := l.Packages["nginx"]
+	if !p.HasPortScanSuccessOn() {
+		t.Errorf("expected package to have a successful port scan")
+	}
+	lp0 := p.AffectedProcs[0].ListenPorts[0]
+	if !reflect.DeepEqual(lp0.PortScanSuccessOn, []string{"127.0.0.1"}) {
+		t.Errorf("wildcard PortScanSuccessOn = %v, want [127.0.0.1]", lp0.PortScanSuccessOn)
+	}
+	lp1 := p.AffectedProcs[0].ListenPorts[1]
+	if !reflect.DeepEqual(lp1.PortScanSuccessOn, []string{}) {
+		t.Errorf("concrete no-match PortScanSuccessOn = %v, want []", lp1.PortScanSuccessOn)
+	}
+}
+
+func TestPackage_HasPortScanSuccessOn(t *testing.T) {
+	// no affected procs
+	if (models.Package{Name: "a"}).HasPortScanSuccessOn() {
+		t.Errorf("empty package should not have scan success")
+	}
+	// port present but no successful scan
+	if (models.Package{Name: "b", AffectedProcs: []models.AffectedProcess{
+		{PID: "1", ListenPorts: []models.ListenPort{{Address: "*", Port: "80"}}},
+	}}).HasPortScanSuccessOn() {
+		t.Errorf("no successful scan should be false")
+	}
+	// one port has a successful scan
+	if !(models.Package{Name: "c", AffectedProcs: []models.AffectedProcess{
+		{PID: "1", ListenPorts: []models.ListenPort{{Address: "*", Port: "80", PortScanSuccessOn: []string{"10.0.0.1"}}}},
+	}}).HasPortScanSuccessOn() {
+		t.Errorf("expected true when a port scan succeeded")
+	}
+}
