+)
+
+func newTestLogger() *logrus.Entry {
+	return logrus.NewEntry(logrus.New())
+}
+
+func tcpReachable(dest string, timeout time.Duration) bool {
+	_, err := net.DialTimeout("tcp", dest, timeout)
+	return err == nil
+}
+
+// wiringDebian embeds *debian but short-circuits the package-scanning steps so
+// the test can exercise the real GetScanResults pipeline (including
+// updatePortStatus) without needing a working apt/sudo environment.
+type wiringDebian struct {
+	*debian
+}
+
+func (o *wiringDebian) scanPackages() error { return nil }
+func (o *wiringDebian) postScan() error     { return nil }
+
+// newWiringDebian builds a debian scanner with the given listening endpoints
+// pre-populated on package "nginx", as if dpkgPs had detected them.
+func newWiringDebian(name string, listenPorts []models.ListenPort) *wiringDebian {
+	b := newDebian(config.ServerInfo{
+		ServerName: name,
+		Host:       "127.0.0.1",
+		Port:       "local",
+		IPv4Addrs:  []string{"127.0.0.1"},
+	})
+	b.osPackages = osPackages{
+		Packages: models.Packages{
+			"nginx": models.Package{
+				Name:       "nginx",
+				NewVersion: "1.25.0",
+				AffectedProcs: []models.AffectedProcess{
+					{PID: "4242", Name: "nginx", ListenPorts: listenPorts},
+				},
+			},
+		},
+	}
+	return &wiringDebian{debian: b}
+}
+
+// TestE2E_GetScanResults_Wiring verifies that GetScanResults runs the
+// updatePortStatus pipeline: a package whose affected process listens on a
+// live local endpoint (an in-process Go listener) gets PortScanSuccessOn
+// populated, and the exposure is reflected in the converted ScanResult.
+func TestE2E_GetScanResults_Wiring(t *testing.T) {
+	// Start a real in-process TCP listener that accepts connections.
+	ln, err := net.Listen("tcp", "127.0.0.1:0")
+	if err != nil {
+		t.Fatalf("failed to start in-process listener: %+v", err)
+	}
+	defer ln.Close()
+	listenPort := fmt.Sprintf("%d", ln.Addr().(*net.TCPAddr).Port)
+	go func() {
+		for {
+			c, e := ln.Accept()
+			if e != nil {
+				return
+			}
+			_ = c.Close()
+		}
+	}()
+	// Wait until the listener actually accepts connections.
+	if !tcpReachable("127.0.0.1:"+listenPort, 2*time.Second) {
+		t.Fatalf("in-process listener on %s not reachable", listenPort)
+	}
+
+	b := newWiringDebian("e2e-local", []models.ListenPort{
+		{Address: "127.0.0.1", Port: listenPort},
+	})
+	servers = []osTypeInterface{b}
+
+	results, err := GetScanResults(time.Now(), 60)
+	if err != nil {
+		t.Fatalf("GetScanResults returned error: %+v", err)
+	}
+	if len(results) != 1 {
+		t.Fatalf("expected 1 result, got %d", len(results))
+	}
+	r := results[0]
+	pack, ok := r.Packages["nginx"]
+	if !ok {
+		t.Fatalf("package nginx missing from result")
+	}
+	if !pack.HasPortScanSuccessOn() {
+		t.Fatalf("expected nginx to have a scannable listening port after pipeline, got %+v", pack.AffectedProcs)
+	}
+	lp := pack.AffectedProcs[0].ListenPorts[0]
+	if len(lp.PortScanSuccessOn) != 1 || lp.PortScanSuccessOn[0] != "127.0.0.1" {
+		t.Fatalf("expected PortScanSuccessOn=[127.0.0.1], got %v", lp.PortScanSuccessOn)
+	}
+	if !r.HasExposedPorts() {
+		t.Fatalf("expected ScanResult.HasExposedPorts() to be true (summary indicator)")
+	}
+}
+
+// TestE2E_GetScanResults_NoExposure verifies that when the endpoint is not
+// reachable, PortScanSuccessOn stays empty and no exposure is reported.
+func TestE2E_GetScanResults_NoExposure(t *testing.T) {
+	// Pick a port that is guaranteed free right now by binding and immediately
+	// closing it, so the dial from updatePortStatus cannot succeed.
+	freePort := 0
+	ln, err := net.Listen("tcp", "127.0.0.1:0")
+	if err != nil {
+		t.Fatalf("failed to find a free port: %+v", err)
+	}
+	freePort = ln.Addr().(*net.TCPAddr).Port
+	_ = ln.Close()
+
+	// Sanity: the port must be closed from our perspective.
+	if tcpReachable(fmt.Sprintf("127.0.0.1:%d", freePort), 500*time.Millisecond) {
+		t.Fatalf("port %d unexpectedly reachable", freePort)
+	}
+	b := newWiringDebian("e2e-closed", []models.ListenPort{
+		{Address: "127.0.0.1", Port: fmt.Sprintf("%d", freePort)},
+	})
+	servers = []osTypeInterface{b}
+
+	// Settle: let the OS fully release the port, then confirm it is closed with a
+	// short retry loop. If the environment keeps reusing it (kernel socket reuse
+	// artifact), skip rather than fail, since the no-exposure logic is already
+	// covered by Test_base_updatePortStatus / Test_base_findPortScanSuccessOn.
+	// The freshly-closed port may be briefly reusable; confirm it is closed before
+	// the pipeline dials it. If the environment keeps reusing it, skip (the
+	// no-exposure logic is already covered by the unit tests).
+	for i := 0; i < 10; i++ {
+		if c, derr := net.DialTimeout("tcp", fmt.Sprintf("127.0.0.1:%d", freePort), 100*time.Millisecond); derr != nil {
+			break
+		} else {
+			_ = c.Close()
+			time.Sleep(50 * time.Millisecond)
+		}
+	}
+	if tcpReachable(fmt.Sprintf("127.0.0.1:%d", freePort), 100*time.Millisecond) {
+		t.Skipf("port %d kept being reachable; skipping e2e no-exposure", freePort)
+	}
+
+	results, err := GetScanResults(time.Now(), 60)
+	if err != nil {
+		t.Fatalf("GetScanResults returned error: %+v", err)
+	}
+	pack := results[0].Packages["nginx"]
+	if len(pack.AffectedProcs[0].ListenPorts[0].PortScanSuccessOn) != 0 {
+		t.Fatalf("expected empty PortScanSuccessOn for closed port, got %v",
+			pack.AffectedProcs[0].ListenPorts[0].PortScanSuccessOn)
+	}
+	if results[0].HasExposedPorts() {
+		t.Fatalf("expected no exposure for closed port")
+	}
+}
