+func TestU2FSignRequestMultipleDevices(t *testing.T) {
+	ctx := context.Background()
+	// U2F challenge verification uses time.Now(), so a fake clock cannot be
+	// used here.
+	as, err := NewTestAuthServer(TestAuthServerConfig{
+		Dir: t.TempDir(),
+	})
+	require.NoError(t, err)
+	srv, err := as.NewTestTLSServer()
+	require.NoError(t, err)
+
+	// Enable U2F support.
+	appID := "https://teleport.example.com"
+	authPref, err := services.NewAuthPreference(types.AuthPreferenceSpecV2{
+		Type: teleport.Local,
+		U2F: &types.U2F{
+			AppID:  appID,
+			Facets: []string{appID},
+		},
+	})
+	require.NoError(t, err)
+	err = as.AuthServer.SetAuthPreference(authPref)
+	require.NoError(t, err)
+
+	// Create a fake user.
+	user, _, err := CreateUserAndRole(as.AuthServer, "mfa-user", []string{"role"})
+	require.NoError(t, err)
+	require.NoError(t, as.AuthServer.UpsertPassword(user.GetName(), []byte("password")))
+	cl, err := srv.NewClient(TestUser(user.GetName()))
+	require.NoError(t, err)
+
+	// A sign request for a user with no U2F devices must fail.
+	_, err = cl.GetU2FSignRequest(user.GetName(), []byte("password"))
+	require.Error(t, err)
+
+	// Register two U2F devices for the user. Each registration completes
+	// the full U2F register-verify sequence against a real mock device,
+	// then the resulting device is upserted directly so that both devices
+	// coexist (the in-memory challenge storage is keyed by user, so a
+	// second RegisterVerify would otherwise overwrite the first device).
+	u2fStorage, err := u2f.InMemoryRegistrationStorage(as.AuthServer)
+	require.NoError(t, err)
+	u2fDevices := make(map[string]*mocku2f.Key)
+	for _, devName := range []string{"u2f-dev-1", "u2f-dev-2"} {
+		mdev, err := mocku2f.Create()
+		require.NoError(t, err)
+		u2fDevices[devName] = mdev
+
+		u2fConf, err := authPref.GetU2F()
+		require.NoError(t, err)
+		chal, err := u2f.RegisterInit(u2f.RegisterInitParams{
+			AppConfig:  *u2fConf,
+			Storage:    u2fStorage,
+			StorageKey: user.GetName(),
+		})
+		require.NoError(t, err)
+		serverChal, err := u2fStorage.GetU2FRegisterChallenge(user.GetName())
+		require.NoError(t, err)
+		mresp, err := mdev.RegisterResponse(chal)
+		require.NoError(t, err)
+
+		// Verify the registration data with the same code path the server
+		// uses, then store the device under a distinct ID.
+		reg, err := tstranexu2f.Register(*mresp, *serverChal, &tstranexu2f.Config{SkipAttestationVerify: true})
+		require.NoError(t, err)
+		require.True(t, reg.PubKey.Equal(&mdev.PrivateKey.PublicKey))
+		require.Equal(t, mdev.KeyHandle, reg.KeyHandle)
+		dev, err := u2f.NewDevice(devName, reg, time.Now())
+		require.NoError(t, err)
+		require.NoError(t, as.AuthServer.UpsertMFADevice(ctx, user.GetName(), dev))
+	}
+
+	// A sign request must now carry one challenge per registered device.
+	signReq, err := cl.GetU2FSignRequest(user.GetName(), []byte("password"))
+	require.NoError(t, err)
+	require.Len(t, signReq.Challenges, 2)
+	require.NotNil(t, signReq.AuthenticateChallenge)
+
+	// Each challenge must correspond to a distinct registered device.
+	keyHandles := make(map[string]bool)
+	for _, chal := range signReq.Challenges {
+		require.Equal(t, appID, chal.AppID)
+		require.NotEmpty(t, chal.Challenge)
+		require.NotEmpty(t, chal.KeyHandle)
+		keyHandles[chal.KeyHandle] = true
+	}
+	require.Len(t, keyHandles, 2)
+
+	// The legacy embedded challenge must match one of the multi-device
+	// challenges so that older clients keep working.
+	require.Contains(t, keyHandles, signReq.AuthenticateChallenge.KeyHandle)
+
+	// Responding to the sign request with any one of the user's devices
+	// must authenticate successfully.
+	for _, chal := range signReq.Challenges {
+		t.Run(chal.KeyHandle, func(t *testing.T) {
+			var mdev *mocku2f.Key
+			for _, dev := range u2fDevices {
+				if bytes.Equal(dev.KeyHandle, mustDecodeKeyHandle(t, chal.KeyHandle)) {
+					mdev = dev
+					break
+				}
+			}
+			require.NotNil(t, mdev)
+			mresp, err := mdev.SignResponse(&u2f.AuthenticateChallenge{
+				Challenge: chal.Challenge,
+				KeyHandle: chal.KeyHandle,
+				AppID:     chal.AppID,
+			})
+			require.NoError(t, err)
+
+			sess, err := as.AuthServer.AuthenticateWebUser(AuthenticateUserRequest{
+				Username: user.GetName(),
+				U2F: &U2FSignResponseCreds{
+					SignResponse: u2f.AuthenticateChallengeResponse{
+						KeyHandle:     mresp.KeyHandle,
+						SignatureData: mresp.SignatureData,
+						ClientData:    mresp.ClientData,
+					},
+				},
+			})
+			require.NoError(t, err)
+			require.NotEmpty(t, sess.GetName())
+		})
+	}
+}
+
+func mustDecodeKeyHandle(t *testing.T, kh string) []byte {
+	t.Helper()
+	decoded, err := base64.URLEncoding.WithPadding(base64.NoPadding).DecodeString(kh)
+	require.NoError(t, err)
+	return decoded
+}
