+package auth
+
+import (
+	"context"
+	"encoding/json"
+
+	"github.com/gravitational/trace"
+
+	"github.com/gravitational/teleport/api/types"
+	"github.com/gravitational/teleport/lib/auth/u2f"
+)
+
+// U2FAuthenticateChallenge is a JSON-serializable U2F authentication challenge
+// payload. It carries the legacy single-device challenge fields (version,
+// challenge, keyHandle, appId) in a flat wire format so that older clients
+// continue to work unchanged, and additionally exposes a list of challenges,
+// one for each of the user's registered U2F devices, for multi-device flows.
+type U2FAuthenticateChallenge struct {
+	// AuthenticateChallenge carries the single-device challenge selected for
+	// backward compatibility with older clients.
+	AuthenticateChallenge *u2f.AuthenticateChallenge
+
+	// Challenges carries one challenge for each of the user's registered U2F
+	// devices. Newer clients may present all of them to the user and accept a
+	// response from any of the user's devices.
+	Challenges []u2f.AuthenticateChallenge
+}
+
+// UnmarshalJSON decodes both the legacy flat challenge format
+//
+//	{"version":"U2F_V2","challenge":"...","keyHandle":"...","appId":"..."}
+//
+// and the new multi-device format
+//
+//	{"version":"U2F_V2","challenge":"...","keyHandle":"...","appId":"...","challenges":[...]}
+//
+// so that clients of any version can consume the payload.
+func (c *U2FAuthenticateChallenge) UnmarshalJSON(data []byte) error {
+	var legacy u2f.AuthenticateChallenge
+	if err := json.Unmarshal(data, &legacy); err != nil {
+		return trace.Wrap(err)
+	}
+	c.AuthenticateChallenge = &legacy
+	var withChallenges struct {
+		Challenges []u2f.AuthenticateChallenge `json:"challenges"`
+	}
+	if err := json.Unmarshal(data, &withChallenges); err != nil {
+		return trace.Wrap(err)
+	}
+	c.Challenges = withChallenges.Challenges
+	return nil
+}
+
+// MarshalJSON encodes the payload in the legacy flat challenge format with
+// the multi-device challenge list added alongside it. The flat legacy fields
+// are always taken from the first challenge so that older clients, which
+// only understand the flat format, keep working.
+func (c *U2FAuthenticateChallenge) MarshalJSON() ([]byte, error) {
+	var legacy u2f.AuthenticateChallenge
+	switch {
+	case c.AuthenticateChallenge != nil:
+		legacy = *c.AuthenticateChallenge
+	case len(c.Challenges) > 0:
+		legacy = c.Challenges[0]
+	}
+	out := struct {
+		u2f.AuthenticateChallenge
+		Challenges []u2f.AuthenticateChallenge `json:"challenges,omitempty"`
+	}{
+		AuthenticateChallenge: legacy,
+		Challenges:            c.Challenges,
+	}
+	return json.Marshal(&out)
+}
+
+func (a *Server) U2FSignRequest(user string, password []byte) (*U2FAuthenticateChallenge, error) {
+	ctx := context.TODO()
+	caps, err := a.GetAuthPreference()
+	if err != nil {
+		return nil, trace.Wrap(err)
+	}
+
+	u2fConfig, err := caps.GetU2F()
+	if err != nil {
+		return nil, trace.Wrap(err)
+	}
+
+	err = a.WithUserLock(user, func() error {
+		return a.CheckPasswordWOToken(user, password)
+	})
+	if err != nil {
+		return nil, trace.Wrap(err)
+	}
+
+	devs, err := a.GetMFADevices(ctx, user)
+	if err != nil {
+		return nil, trace.Wrap(err)
+	}
+	var u2fDevs []*types.MFADevice
+	for _, dev := range devs {
+		if dev.GetU2F() == nil {
+			continue
+		}
+		u2fDevs = append(u2fDevs, dev)
+	}
+	if len(u2fDevs) == 0 {
+		return nil, trace.NotFound("no U2F devices found for user %q", user)
+	}
+
+	challenges := make([]u2f.AuthenticateChallenge, 0, len(u2fDevs))
+	var first *u2f.AuthenticateChallenge
+	for _, dev := range u2fDevs {
+		chal, err := u2f.AuthenticateInit(ctx, u2f.AuthenticateInitParams{
+			Dev:        dev,
+			AppConfig:  *u2fConfig,
+			StorageKey: user,
+			Storage:    a.Identity,
+		})
+		if err != nil {
+			return nil, trace.Wrap(err)
+		}
+		challenges = append(challenges, *chal)
+		if first == nil {
+			first = chal
+		}
+	}
+
+	return &U2FAuthenticateChallenge{
+		AuthenticateChallenge: first,
+		Challenges:            challenges,
+	}, nil
+}
