+	count    int
+	finished bool
+}
+
+// Add increments the streamed token count by one. It returns an error if the
+// counter has already been finalized by a call to TokenCount.
+func (a *AsynchronousTokenCounter) Add() error {
+	a.mu.Lock()
+	defer a.mu.Unlock()
+
+	if a.finished {
+		return trace.Errorf("cannot add to an asynchronous token counter that has already been finalized")
+	}
+
+	a.count++
+
+	return nil
+}
+
+// TokenCount finalizes the counter and returns the total token count,
+// including perRequest. It is idempotent and non-blocking. Subsequent calls
+// to Add return an error.
+func (a *AsynchronousTokenCounter) TokenCount() int {
+	a.mu.Lock()
+	defer a.mu.Unlock()
+
+	a.finished = true
+
