+func TestTopRequestsCollectedByDefault(t *testing.T) {
+	component := "top-default-comp"
+	r := newTestReporter(t, component, 1000)
+	ctx := context.Background()
+	_, _ = r.Get(ctx, []byte("/users/teleport"))
+	set, total := metricLabelSet(t, component)
+	if total != 1 {
+		t.Fatalf("expected 1 tracked request key by default, got %d (set=%v)", total, set)
+	}
+	if _, ok := set["/users/teleport"]; !ok {
+		t.Fatalf("expected request key /users/teleport to be tracked, got set=%v", set)
+	}
+}
+
+// TestTopRequestsDefaultLimit verifies that when no limit is specified the
+// limit defaults to 1000.
+func TestTopRequestsDefaultLimit(t *testing.T) {
+	cfg := ReporterConfig{
+		Backend:   newMockBackend(),
+		Component: "top-default-limit-comp",
+		// TopRequestsLimit intentionally left at zero.
+	}
+	if err := cfg.CheckAndSetDefaults(); err != nil {
+		t.Fatalf("CheckAndSetDefaults failed: %v", err)
+	}
+	if cfg.TopRequestsLimit != 1000 {
+		t.Fatalf("expected default top requests limit of 1000, got %d", cfg.TopRequestsLimit)
+	}
+}
+
+// TestTopRequestsLimitCapped verifies that the number of unique request keys
+// tracked is capped at the configured limit.
+func TestTopRequestsLimitCapped(t *testing.T) {
+	const limit = 5
+	component := "top-limit-capped-comp"
+	r := newTestReporter(t, component, limit)
+	ctx := context.Background()
+	// Insert 10 distinct keys; only the most recent 5 should be tracked.
+	for i := 0; i < 10; i++ {
+		key := []byte("/top/key" + string(rune('a'+i)))
+		_, _ = r.Get(ctx, key)
+	}
+	set, total := metricLabelSet(t, component)
+	if total != limit {
+		t.Fatalf("expected at most %d tracked request keys, got %d (set=%v)", limit, total, set)
+	}
+	if r.topRequests.Len() != limit {
+		t.Fatalf("expected LRU cache to hold %d entries, got %d", limit, r.topRequests.Len())
+	}
+	// The most recently added keys should still be present.
+	for _, suffix := range []string{"f", "g", "h", "i", "j"} {
+		if _, ok := set["/top/key"+suffix]; !ok {
+			t.Fatalf("expected recently used key /top/key%s to be tracked, got set=%v", suffix, set)
+		}
+	}
+	// The oldest keys should have been evicted.
+	for _, suffix := range []string{"a", "b", "c"} {
+		if _, ok := set["/top/key"+suffix]; ok {
+			t.Fatalf("expected oldest key /top/key%s to be evicted, but it is still tracked (set=%v)", suffix, set)
+		}
+	}
+}
+
+// TestTopRequestsEvictionRemovesLabel verifies that when a key is evicted its
+// label is removed from the Prometheus metric, capping cardinality.
+func TestTopRequestsEvictionRemovesLabel(t *testing.T) {
+	const limit = 3
+	component := "top-eviction-removes-label-comp"
+	r := newTestReporter(t, component, limit)
+	ctx := context.Background()
+
+	// Fill the cache with three keys.
+	for _, k := range []string{"/top/a", "/top/b", "/top/c"} {
+		_, _ = r.Get(ctx, []byte(k))
+	}
+	if _, total := metricLabelSet(t, component); total != limit {
+		t.Fatalf("expected %d tracked keys, got %d", limit, total)
+	}
+
+	// Add a fourth key: the least recently used (/top/a) must be evicted and
+	// its label removed from the metric.
+	_, _ = r.Get(ctx, []byte("/top/d"))
+	set, total := metricLabelSet(t, component)
+	if total != limit {
+		t.Fatalf("after eviction expected %d tracked keys, got %d (set=%v)", limit, total, set)
+	}
+	if _, ok := set["/top/a"]; ok {
+		t.Fatalf("evicted key /top/a should have been removed from the metric, got set=%v", set)
+	}
+	for _, k := range []string{"/top/b", "/top/c", "/top/d"} {
+		if _, ok := set[k]; !ok {
+			t.Fatalf("expected key %s to be tracked after eviction, got set=%v", k, set)
+		}
+	}
+}
+
+// TestTopRequestsRecencyRefresh verifies that accessing an existing key
+// refreshes its recency so it is not the next to be evicted.
+func TestTopRequestsRecencyRefresh(t *testing.T) {
+	const limit = 3
+	component := "top-recency-refresh-comp"
+	r := newTestReporter(t, component, limit)
+	ctx := context.Background()
+
+	// Insert a, b, c (c is newest).
+	for _, k := range []string{"/top/a", "/top/b", "/top/c"} {
+		_, _ = r.Get(ctx, []byte(k))
+	}
+	// Touch /top/a so it becomes the most recently used. The eviction order
+	// should now be b (oldest), c, a.
+	_, _ = r.Get(ctx, []byte("/top/a"))
+	// Add a new key /top/d; the least recently used /top/b should be evicted.
+	_, _ = r.Get(ctx, []byte("/top/d"))
+	set, total := metricLabelSet(t, component)
+	if total != limit {
+		t.Fatalf("expected %d tracked keys, got %d (set=%v)", limit, total, set)
+	}
+	if _, ok := set["/top/b"]; ok {
+		t.Fatalf("expected /top/b (least recently used) to be evicted, got set=%v", set)
+	}
+	for _, k := range []string{"/top/a", "/top/c", "/top/d"} {
+		if _, ok := set[k]; !ok {
+			t.Fatalf("expected key %s to be tracked, got set=%v", k, set)
+		}
+	}
+}
+
+// TestTopRequestsRangeKey verifies that range queries are tracked as distinct
+// keys from single-key queries (the range label differs).
+func TestTopRequestsRangeKey(t *testing.T) {
+	component := "top-range-key-comp"
+	r := newTestReporter(t, component, 100)
+	ctx := context.Background()
+	_, _ = r.Get(ctx, []byte("/users/u1"))
+	_, _ = r.GetRange(ctx, []byte("/users/u1"), []byte("/users/z"), 0)
+	set, total := metricLabelSet(t, component)
+	if total != 2 {
+		t.Fatalf("expected 2 tracked keys (single + range), got %d (set=%v)", total, set)
+	}
+	if !set["/users/u1"][teleport.TagFalse] {
+		t.Fatalf("expected non-range query to be tracked, got set=%v", set)
+	}
+	if !set["/users/u1"][teleport.TagTrue] {
+		t.Fatalf("expected range query to be tracked, got set=%v", set)
+	}
+}
+
+// TestTopRequestsKeyTruncation verifies that request keys are truncated to the
+// first three parts (as split by the backend separator) to bound cardinality.
+// A key with four or more parts is stored using only its first three parts, so
+// deeply nested keys do not explode the metric's cardinality.
+func TestTopRequestsKeyTruncation(t *testing.T) {
+	component := "top-key-truncation-comp"
+	r := newTestReporter(t, component, 100)
+	ctx := context.Background()
+	// /a/b/c/d splits into ["", "a", "b", "c", "d"]; only the first three
+	// parts (["", "a", "b"]) are kept, giving the tracked key "/a/b".
+	_, _ = r.Get(ctx, []byte("/a/b/c/d"))
+	// A different deeper key sharing the same first three parts must collapse
+	// into the same tracked key.
+	_, _ = r.Get(ctx, []byte("/a/b/c/e"))
+	set, total := metricLabelSet(t, component)
+	if total != 1 {
+		t.Fatalf("expected the two keys to collapse into 1 tracked key, got %d (set=%v)", total, set)
+	}
+	if _, ok := set["/a/b"]; !ok {
+		t.Fatalf("expected key to be truncated to first 3 split parts (/a/b), got set=%v", set)
+	}
+}
+
+// TestTopRequestsCounterIncrements verifies that repeated requests to the same
+// key increment the counter (and do not create duplicate labels).
+func TestTopRequestsCounterIncrements(t *testing.T) {
+	component := "top-counter-increments-comp"
+	r := newTestReporter(t, component, 100)
+	ctx := context.Background()
+	for i := 0; i < 3; i++ {
+		_, _ = r.Get(ctx, []byte("/users/u1"))
+	}
+	if got := metricValue(t, component, "/users/u1", teleport.TagFalse); got != 3 {
+		t.Fatalf("expected counter value 3, got %v", got)
+	}
+	if _, total := metricLabelSet(t, component); total != 1 {
+		t.Fatalf("expected exactly 1 label set, got %d", total)
+	}
+}
