+// their correct DynamoDB types (strings, numbers, booleans, nested objects,
+// and arrays). The resulting map is semantically equivalent to the original
+// JSON document.
+func jsonToFieldsMap(data []byte) (map[string]*dynamodb.AttributeValue, error) {
+	if len(data) == 0 {
+		return nil, nil
+	}
+
+	var intermediate map[string]interface{}
+	if err := utils.FastUnmarshal(data, &intermediate); err != nil {
+		return nil, trace.WrapWithMessage(err, "failed to decode event fields JSON")
+	}
+
+	fieldsMap, err := dynamodbattribute.MarshalMap(intermediate)
+	if err != nil {
+		return nil, trace.WrapWithMessage(err, "failed to convert event fields to a DynamoDB map")
+	}
