+// order-insensitive deep equality check. This guarantees no field was
+// dropped, renamed, or altered in value during the conversion while remaining
+// robust to map-key ordering differences.
+func validateFieldsMapConversion(fields string, fieldsMap map[string]*dynamodb.AttributeValue) error {
+	var original interface{}
+	if err := utils.FastUnmarshal([]byte(fields), &original); err != nil {
+		return trace.WrapWithMessage(err, "failed to decode original Fields JSON for validation")
+	}
+
+	var migrated interface{}
+	if err := dynamodbattribute.UnmarshalMap(fieldsMap, &migrated); err != nil {
+		return trace.WrapWithMessage(err, "failed to decode migrated FieldsMap for validation")
+	}
+
+	if err := deepEqualJSON(original, migrated); err != nil {
+		return trace.WrapWithMessage(err, "migrated FieldsMap is not semantically equivalent to the original Fields attribute")
+	}
