+			return trace.CompareFailed("number mismatch: expected %v but got %v", av, bv)
+		}
+		return nil
+	case bool:
+		bv, ok := b.(bool)
+		if !ok {
+			return trace.CompareFailed("expected a boolean but got type %T", b)
+		}
+		if av != bv {
+			return trace.CompareFailed("boolean mismatch: expected %v but got %v", av, bv)
+		}
+		return nil
+	case string:
+		bv, ok := b.(string)
+		if !ok {
+			return trace.CompareFailed("expected a string but got type %T", b)
+		}
+		if av != bv {
+			return trace.CompareFailed("string mismatch: expected %q but got %q", av, bv)
+		}
+		return nil
+	default:
+		return trace.CompareFailed("unexpected type %T in event fields", a)
+	}
+}
+
+// isEmptyJSONContainer reports whether v is an empty JSON object or array.
+func isEmptyJSONContainer(v interface{}) bool {
+	switch c := v.(type) {
+	case map[string]interface{}:
+		return len(c) == 0
+	case []interface{}:
+		return len(c) == 0
+	default:
+		return false
+	}
+}
+
+// fieldsMapMigrated reports whether the `Fields` -> `FieldsMap` migration has
+// already completed for this table, as recorded by the feature/migration flag
+// stored in the backend. A missing flag simply means the migration has not
+// (yet) completed; a corrupt value is treated as not-migrated so the migration
+// re-runs (it is idempotent and cheap on an already-migrated table).
+func (l *Log) fieldsMapMigrated(ctx context.Context) (bool, error) {
+	item, err := l.backend.Get(ctx, backend.FlagKey(fieldsMapMigrationFlag))
+	if err != nil {
+		if trace.IsNotFound(err) {
+			return false, nil
+		}
+		return false, trace.Wrap(err)
+	}
+	return string(item.Value) == "true", nil
+}
+
+// setFieldsMapMigrated records the `Fields` -> `FieldsMap` migration completion
+// flag in the backend.
+func (l *Log) setFieldsMapMigrated(ctx context.Context) error {
+	_, err := l.backend.Put(ctx, backend.Item{
+		Key:   backend.FlagKey(fieldsMapMigrationFlag),
+		Value: []byte("true"),
+	})
+	return trace.Wrap(err)
+}
+
+// migrateFieldsMapWithRetry repeatedly attempts the `Fields` -> `FieldsMap`
+// migration until it succeeds, so that transient errors do not permanently
+// prevent the migration from running.
+func (l *Log) migrateFieldsMapWithRetry(ctx context.Context) {
+	for {
+		err := l.migrateFieldsMap(ctx)
+
+		if err == nil {
+			break
+		}
+
+		delay := utils.HalfJitter(time.Minute)
+		log.WithError(err).Errorf("FieldsMap migration failed, retrying in %f seconds", delay.Seconds())
+		select {
+		case <-time.After(delay):
+		case <-ctx.Done():
+			log.WithError(ctx.Err()).Error("FieldsMap migration cancelled")
+			return
+		}
+	}
+}
+
+// migrateFieldsMap converts existing events that still carry only the legacy
+// JSON string `Fields` attribute into the new native `FieldsMap` attribute,
+// while retaining `Fields` for backward compatibility.
+//
+// Properties:
+//   - It is idempotent: already-migrated records are skipped, so re-running it
+//     is a no-op.
+//   - It is resumable: the scan drives off DynamoDB's own iterator
+//     (LastEvaluatedKey), so an interrupted run can be resumed by simply
+//     running this function again.
+//   - It is efficient: records are read with a consistent read and updated in
+//     batches of `DynamoBatchSize`, uploaded concurrently by up to
+//     `maxMigrationWorkers` workers, mirroring the RFD 24 migration.
+//   - It is safe in an HA setup: the whole migration runs under the
+//     `fieldsMapMigrationLock` distributed lock, so at most one auth server
+//     migrates at a time.
+//   - It validates every converted record before writing, guaranteeing the
+//     migrated `FieldsMap` preserves the semantic content of `Fields`.
+//
+// Invariants:
+//   - This function must not be called concurrently with itself (enforced by
+//     the distributed lock in migrateRFD24-style callers).
+//   - The record's primary-key attributes are preserved; only `FieldsMap` is
+//     added, so no data is lost.
+func (l *Log) migrateFieldsMap(ctx context.Context) error {
+	if done, err := l.fieldsMapMigrated(ctx); err != nil {
+		return trace.Wrap(err)
+	} else if done {
+		return nil
+	}
+
+	return backend.RunWhileLocked(ctx, l.backend, fieldsMapMigrationLock, rfd24MigrationLockTTL, func(ctx context.Context) error {
+		// Re-check the flag under the lock in case another server finished the
+		// migration between our first check and acquiring the lock.
+		if done, err := l.fieldsMapMigrated(ctx); err != nil {
+			return trace.Wrap(err)
+		} else if done {
+			return nil
+		}
+
+		if err := l.runFieldsMapMigration(ctx); err != nil {
+			return trace.Wrap(err)
+		}
+
+		// All legacy records now carry a native `FieldsMap`. Record the
+		// completion flag so subsequent starts skip the (now no-op) scan.
+		if err := l.setFieldsMapMigrated(ctx); err != nil {
+			return trace.WrapWithMessage(err, "failed to record FieldsMap migration completion flag")
+		}
+		return nil
+	})
+}
+
+// runFieldsMapMigration performs the actual scan-convert-validate-write loop
+// that converts legacy records to the `FieldsMap` format.
+func (l *Log) runFieldsMapMigration(ctx context.Context) error {
+	var startKey map[string]*dynamodb.AttributeValue
+	workerCounter := atomic.NewInt32(0)
+	totalProcessed := atomic.NewInt64(0)
+	totalSkipped := atomic.NewInt64(0)
+	workerErrors := make(chan error, maxMigrationWorkers)
+	workerBarrier := sync.WaitGroup{}
+
+	log.Info("Starting event migration from Fields (JSON string) to FieldsMap (native map)")
+
+	for {
+		// Check for worker errors and escalate if found.
+		select {
+		case err := <-workerErrors:
+			return trace.Wrap(err)
+		default:
+		}
+
+		c := &dynamodb.ScanInput{
+			ExclusiveStartKey: startKey,
+			ConsistentRead:    aws.Bool(true),
+			// `DynamoBatchSize*maxMigrationWorkers` is the maximum concurrent
+			// event uploads.
+			Limit:     aws.Int64(DynamoBatchSize * maxMigrationWorkers),
+			TableName: aws.String(l.Tablename),
+			// Only legacy records (those without a native `FieldsMap`) need to
+			// be migrated. New records always write `FieldsMap`, so once every
+			// legacy record is converted this scan returns nothing and the
+			// migration completes.
+			FilterExpression: aws.String("attribute_not_exists(" + keyFieldsMap + ") AND attribute_exists(Fields)"),
+		}
+
+		scanOut, err := l.svc.Scan(c)
+		if err != nil {
+			return trace.Wrap(convertError(err))
+		}
+
+		writeRequests := make([]*dynamodb.WriteRequest, 0, DynamoBatchSize*maxMigrationWorkers)
+
+		for _, item := range scanOut.Items {
+			fieldsAttr, ok := item["Fields"]
+			if !ok || fieldsAttr.S == nil {
+				// Defensive: the scan filter guarantees a `Fields` attribute,
+				// but skip (and log) anything unexpected rather than failing the
+				// whole migration.
+				l.Warnf("Skipping event without a readable Fields attribute")
+				totalSkipped.Add(1)
+				continue
+			}
+			fieldsJSON := *fieldsAttr.S
+
+			fieldsMap, err := jsonToFieldsMap([]byte(fieldsJSON))
+			if err != nil {
+				return trace.Wrap(err)
+			}
+
+			// Validate that the conversion preserved the semantic content before
+			// we write anything, so we never corrupt an event's metadata.
+			if err := validateFieldsMapConversion(fieldsJSON, fieldsMap); err != nil {
+				return trace.WrapWithMessage(err, "aborting FieldsMap migration: conversion validation failed")
+			}
+
+			// Add the native attribute to the (already fully populated) item.
+			// A top-level `FieldsMap` attribute is itself a DynamoDB map, so the
+			// per-field attribute map is wrapped in an outer M-typed attribute.
+			// All other attributes, including the legacy `Fields` string, are
+			// preserved.
+			item[keyFieldsMap] = &dynamodb.AttributeValue{
+				M: fieldsMap,
+			}
+
+			writeRequests = append(writeRequests, &dynamodb.WriteRequest{
+				PutRequest: &dynamodb.PutRequest{
+					Item: item,
+				},
+			})
+		}
+
+		for len(writeRequests) > 0 {
+			var top int
+			if len(writeRequests) > DynamoBatchSize {
+				top = DynamoBatchSize
+			} else {
+				top = len(writeRequests)
+			}
+
+			// Copy the slice so subslicing the outer slice cannot mutate the
+			// batch handed to a worker.
+			batch := append(make([]*dynamodb.WriteRequest, 0, DynamoBatchSize), writeRequests[:top]...)
+			writeRequests = writeRequests[top:]
+
+			// Don't exceed the maximum number of concurrent workers.
+			for workerCounter.Load() >= maxMigrationWorkers {
+				select {
+				case <-time.After(time.Millisecond * 50):
+				case <-ctx.Done():
+					return trace.Wrap(ctx.Err())
+				}
+			}
+
+			workerCounter.Add(1)
+			workerBarrier.Add(1)
+			go func() {
+				defer workerCounter.Sub(1)
+				defer workerBarrier.Done()
+				amountProcessed := len(batch)
+
+				if err := l.uploadBatch(batch); err != nil {
+					workerErrors <- trace.Wrap(err)
+					return
+				}
+
+				total := totalProcessed.Add(int64(amountProcessed))
+				l.Infof("Migrated %d total events to FieldsMap format...", total)
+			}()
+		}
+
+		// Resume the scan where the previous one stopped so we do not
+		// re-process records that have already been converted.
+		startKey = scanOut.LastEvaluatedKey
+
+		// No LastEvaluatedKey means the whole dataset has been scanned.
+		if scanOut.LastEvaluatedKey == nil {
+			break
+		}
+	}
+
+	// Wait for all in-flight uploads to finish.
+	workerBarrier.Wait()
+
+	// Check for worker errors and escalate if found.
+	select {
+	case err := <-workerErrors:
+		return trace.Wrap(err)
+	default:
+	}
+
+	l.Infof("Finished FieldsMap migration: %d migrated, %d skipped", totalProcessed.Load(), totalSkipped.Load())
+	return nil
+}
+
