+
+package dynamoevents
+
+import (
+	"testing"
+	"time"
+
+	"github.com/aws/aws-sdk-go/aws"
+	"github.com/aws/aws-sdk-go/service/dynamodb"
+	"github.com/aws/aws-sdk-go/service/dynamodb/dynamodbattribute"
+	"github.com/gravitational/teleport/lib/backend"
+	"github.com/stretchr/testify/require"
+)
+
+// TestFlagKey verifies that backend.FlagKey builds keys under the internal
+// ".flags" prefix using the standard separator.
+func TestFlagKey(t *testing.T) {
+	require.Equal(t, []byte(".flags/dynamo/fieldsmap-migrated"),
+		backend.FlagKey("dynamo", "fieldsmap-migrated"))
+	require.Equal(t, []byte(".flags/foo"), backend.FlagKey("foo"))
+	// It must not collide with the lock key prefix.
+	require.NotEqual(t, []byte(".locks/foo"), backend.FlagKey("foo"))
+}
+
+// TestJSONToFieldsMap verifies that a JSON-encoded event Fields string is
+// converted into a native DynamoDB attribute map with the correct types, and
+// that the conversion preserves the semantic content of the original JSON.
+func TestJSONToFieldsMap(t *testing.T) {
+	raw := `{"user":"bob","type":"user.local_login","success":true,"count":3,"score":42.5,"attrs":{"roles":["admin","editor"]}}`
+
+	fieldsMap, err := jsonToFieldsMap([]byte(raw))
+	require.NoError(t, err)
+	require.NotEmpty(t, fieldsMap)
+
+	// Spot-check the native types.
+	require.Equal(t, aws.String("bob"), fieldsMap["user"].S)
+	require.Equal(t, aws.String("3"), fieldsMap["count"].N)
+	require.True(t, aws.BoolValue(fieldsMap["success"].BOOL))
+	require.NotNil(t, fieldsMap["attrs"].M)
+
+	// The conversion must validate cleanly (semantic content preserved).
+	require.NoError(t, validateFieldsMapConversion(raw, fieldsMap))
+}
+
+// TestJSONToFieldsMapEmpty covers the empty-document and empty-container
+// edge cases.
+func TestJSONToFieldsMapEmpty(t *testing.T) {
+	// Empty document.
+	m, err := jsonToFieldsMap([]byte(`{}`))
+	require.NoError(t, err)
+	require.Empty(t, m)
+
+	// Null payload is treated as no fields.
+	m, err = jsonToFieldsMap(nil)
+	require.NoError(t, err)
+	require.Nil(t, m)
+}
+
+// TestValidateDetectsMismatch verifies that validation rejects a FieldsMap that
+// has lost, gained, or altered a field relative to the original JSON.
+func TestValidateDetectsMismatch(t *testing.T) {
+	raw := `{"user":"bob","count":7}`
+	fieldsMap, err := jsonToFieldsMap([]byte(raw))
+	require.NoError(t, err)
+
+	// Dropping a field must be detected.
+	missing := map[string]*dynamodb.AttributeValue{"user": fieldsMap["user"]}
+	require.Error(t, validateFieldsMapConversion(raw, missing))
+
+	// Changing a value must be detected.
+	changed := map[string]*dynamodb.AttributeValue{
+		"user":  {S: aws.String("alice")},
+		"count": {N: aws.String("7")},
+	}
+	require.Error(t, validateFieldsMapConversion(raw, changed))
+
+	// An extra field must be detected.
+	extra := map[string]*dynamodb.AttributeValue{
+		"user":  {S: aws.String("bob")},
+		"count": {N: aws.String("7")},
+		"junk":  {S: aws.String("extra")},
+	}
+	require.Error(t, validateFieldsMapConversion(raw, extra))
+
+	// A type change (string where a number belongs) must be detected.
+	wrongType := map[string]*dynamodb.AttributeValue{
+		"user":  {S: aws.String("bob")},
+		"count": {S: aws.String("7")},
+	}
+	require.Error(t, validateFieldsMapConversion(raw, wrongType))
+}
+
+// TestValidateNested verifies deep comparison of nested objects and arrays.
+func TestValidateNested(t *testing.T) {
+	raw := `{"outer":{"inner":[1,2,3],"flag":true,"name":"x"},"list":[{"a":1},{"a":2}]}`
+	fieldsMap, err := jsonToFieldsMap([]byte(raw))
+	require.NoError(t, err)
+	require.NoError(t, validateFieldsMapConversion(raw, fieldsMap))
+
+	// Corrupt a nested value; validation must catch it.
+	corrupted := jsonToFieldsMapMust(`{"outer":{"inner":[1,2,99],"flag":true,"name":"x"},"list":[{"a":1},{"a":2}]}`)
+	require.Error(t, validateFieldsMapConversion(raw, corrupted))
+}
+
+func jsonToFieldsMapMust(raw string) map[string]*dynamodb.AttributeValue {
+	m, err := jsonToFieldsMap([]byte(raw))
+	if err != nil {
+		panic(err)
+	}
+	return m
+}
+
+// TestUnmarshalEventLegacy verifies that a pre-migration record (legacy JSON
+// `Fields` string only, no `FieldsMap`) is read correctly and that the
+// `FieldsMap` is reconstructed from the legacy string.
+func TestUnmarshalEventLegacy(t *testing.T) {
+	fieldsJSON := `{"user":"bob","type":"user.local_login","count":3}`
+	item, err := dynamodbattribute.MarshalMap(struct {
+		SessionID  string
+		EventIndex int64
+		EventType  string
+		CreatedAt  int64
+		Fields     string
+	}{
+		SessionID:  "sess-1",
+		EventIndex: 1,
+		EventType:  "user.local_login",
+		CreatedAt:  100,
+		Fields:     fieldsJSON,
+	})
+	require.NoError(t, err)
+
+	var e event
+	require.NoError(t, unmarshalEvent(item, &e))
+	require.Equal(t, "sess-1", e.SessionID)
+	require.Equal(t, int64(1), e.EventIndex)
+	require.Equal(t, "user.local_login", e.EventType)
+	require.Equal(t, int64(100), e.CreatedAt)
+	require.Equal(t, fieldsJSON, e.Fields)
+	require.NotEmpty(t, e.FieldsMap, "FieldsMap should be reconstructed from the legacy Fields string")
+
+	fields, err := eventFields(&e)
+	require.NoError(t, err)
+	require.Equal(t, "bob", fields.GetString("user"))
+	require.Equal(t, 3, fields.GetInt("count"))
+}
+
+// TestUnmarshalEventNative verifies that a post-migration record (native
+// `FieldsMap` attribute, no legacy string) is read correctly, including the
+// nested map attribute that a direct struct unmarshal cannot handle.
+func TestUnmarshalEventNative(t *testing.T) {
+	fieldsMap, err := jsonToFieldsMap([]byte(`{"user":"alice","count":5}`))
+	require.NoError(t, err)
+
+	item := map[string]*dynamodb.AttributeValue{
+		"SessionID":  &dynamodb.AttributeValue{S: aws.String("sess-2")},
+		"EventIndex": &dynamodb.AttributeValue{N: aws.String("2")},
+		"EventType":  &dynamodb.AttributeValue{S: aws.String("user.local_login")},
+		"CreatedAt":  &dynamodb.AttributeValue{N: aws.String("200")},
+		"FieldsMap":  &dynamodb.AttributeValue{M: fieldsMap},
+	}
+
+	var e event
+	require.NoError(t, unmarshalEvent(item, &e))
+	require.Equal(t, "sess-2", e.SessionID)
+	require.Equal(t, int64(2), e.EventIndex)
+	require.NotEmpty(t, e.FieldsMap)
+	require.Empty(t, e.Fields, "legacy string should be absent on a native record")
+
+	fields, err := eventFields(&e)
+	require.NoError(t, err)
+	require.Equal(t, "alice", fields.GetString("user"))
+	require.Equal(t, 5, fields.GetInt("count"))
+}
+
+// TestEventFieldsFallback verifies eventFields reads from the native map when
+// present, falls back to the legacy string when it is not, and errors when
+// neither is present.
+func TestEventFieldsFallback(t *testing.T) {
+	// Legacy string only.
+	f, err := eventFields(&event{Fields: `{"k":"v","n":5}`})
+	require.NoError(t, err)
+	require.Equal(t, "v", f.GetString("k"))
+	require.Equal(t, 5, f.GetInt("n"))
+
+	// Native map only.
+	m, err := jsonToFieldsMap([]byte(`{"a":"b"}`))
+	require.NoError(t, err)
+	f, err = eventFields(&event{FieldsMap: m})
+	require.NoError(t, err)
+	require.Equal(t, "b", f.GetString("a"))
+
+	// Neither.
+	_, err = eventFields(&event{})
+	require.Error(t, err)
+}
+
+// TestUnmarshalEventPreservesExpiryAndDate ensures the read helper preserves
+// the expiry and date attributes that the RFD 24 migration adds.
+func TestUnmarshalEventPreservesExpiryAndDate(t *testing.T) {
+	item, err := dynamodbattribute.MarshalMap(struct {
+		SessionID      string
+		EventIndex     int64
+		EventType      string
+		CreatedAt      int64
+		Expires        *int64
+		EventNamespace string
+		CreatedAtDate  string
+		Fields         string
+	}{
+		SessionID:      "sess-3",
+		EventIndex:     3,
+		EventType:      "user.local_login",
+		CreatedAt:      123,
+		Expires:        aws.Int64(9999999999),
+		EventNamespace: "default",
+		CreatedAtDate:  "2021-04-10",
+		Fields:         `{"user":"bob"}`,
+	})
+	require.NoError(t, err)
+
+	var e event
+	require.NoError(t, unmarshalEvent(item, &e))
+	require.Equal(t, "default", e.EventNamespace)
+	require.Equal(t, "2021-04-10", e.CreatedAtDate)
+	require.NotNil(t, e.Expires)
+	require.Equal(t, int64(9999999999), *e.Expires)
+	require.True(t, time.Unix(*e.Expires, 0).After(time.Now()))
+}

