+// See the License for the specific language governing permissions and
+// limitations under the License.
+
+package resumption
+
+import (
+	"io"
+	"net"
+	"sync"
+	"time"
+
+	"github.com/gravitational/trace"
+	"github.com/jonboulle/clockwork"
+)
+
+// maxBufferSize is the maximum number of bytes the managed connection will
+// stage in its internal buffers before back-pressure kicks in.
+const maxBufferSize = 16 * 1024 * 1024
+
+// initialCapacity is the size of the backing array a byte buffer allocates
+// on first use.
+const initialCapacity = 16 * 1024
+
+// byteBuf is a growable ring buffer. It lazily allocates a 16 KiB backing
+// array on first use, never shrinks as data is advanced, and exposes its
+// contents and free space as up to two contiguous slices each (to avoid
+// allocating on wraparound).
+type byteBuf struct {
+	// data is the backing storage.
+	data []byte
+	// head is the offset of the first buffered byte.
+	head int
+	// tail is the offset one past the last buffered byte.
+	tail int
+}
+
+// newByteBuf returns an empty ring buffer. The backing array is allocated
+// on first use, not up front.
+func newByteBuf() *byteBuf {
+	return &byteBuf{}
+}
+
+// cap returns the current total capacity of the backing storage.
+func (b *byteBuf) cap() int {
+	return len(b.data)
+}
+
+// len returns the number of bytes currently buffered.
+func (b *byteBuf) len() int {
+	if b.tail >= b.head {
+		return b.tail - b.head
+	}
+	return b.cap() - b.head + b.tail
+}
+
+func (b *byteBuf) freeLen() int {
+	return b.cap() - b.len()
+}
+
+// initCapacity guarantees at least cap bytes of backing storage,
+// reallocating and copying buffered data as needed. It never shrinks
+// existing storage.
+func (b *byteBuf) initCapacity(cap int) {
+	if cap <= 0 {
+		cap = initialCapacity
+	}
+	// Keep doubling the requested capacity until it is at least as large as
+	// the current one (doubling from the current size meets the requirement
+	// while preserving the power-of-two growth pattern).
+	for len(b.data) > 0 && cap < len(b.data) {
+		cap *= 2
+	}
+	if len(b.data) >= cap {
+		return
+	}
+	old := b.data
+	oldCap := len(old)
+	data := make([]byte, cap)
+	if oldCap > 0 {
+		// Copy the existing buffered data, compacting it to the start of
+		// the new storage. The old head/tail are offsets into the old
+		// storage, so they must be interpreted relative to oldCap.
+		n := 0
+		if b.len() > 0 {
+			// Unwrapped: a single copy from head to tail.
+			if b.tail >= b.head {
+				n = copy(data, old[b.head:b.tail])
+			} else {
+				// Wrapped: copy head-to-end, then 0-to-tail.
+				n = copy(data, old[b.head:])
+				n += copy(data[n:], old[:b.tail])
+			}
+		}
+		b.tail = n
+	}
+	b.data = data
+	b.head = 0
+}
+
+// reserve ensures that the buffer has enough free space to accommodate
+// want bytes, reallocating its internal storage if needed. If the current
+// capacity is insufficient, it computes a new capacity by doubling the
+// current one until it meets the requirement, then reallocate and restore
+// the existing buffered data.
+func (b *byteBuf) reserve(want int) {
+	if b.freeLen() >= want {
+		return
+	}
+	need := b.len() + want
+	cap := initialCapacity
+	for len(b.data) > 0 && need > b.cap() {
+		cap = b.cap()
+		for cap < need {
+			cap *= 2
+		}
+		break
+	}
+	if need > cap {
+		for cap < need {
+			cap *= 2
+		}
+	}
+	b.initCapacity(cap)
+}
+
+// buffered returns up to two contiguous slices containing the buffered
+// data, starting at the head. b2 is empty unless the data wraps around
+// the end of the backing storage. len(b1)+len(b2) == b.len().
+func (b *byteBuf) buffered() (b1, b2 []byte) {
+	if b.len() == 0 {
+		return nil, nil
+	}
+	if b.tail >= b.head {
+		return b.data[b.head:b.tail], nil
+	}
+	if b.len() == b.cap() {
+		// The buffer is full: the tail has lapped the head exactly.
+		// The whole storage is one contiguous window starting at the
+		// head.
+		return b.data[b.head:], nil
+	}
+	// Wrapped: the head runs to the end of storage, then resumes at 0.
+	return b.data[b.head:], b.data[:b.tail]
+}
+
+// free returns up to two contiguous slices of unused storage, starting at
+// the tail. f2 is empty unless the free space wraps around the end of the
+// backing storage. len(f1)+len(f2) == b.cap()-b.len().
+func (b *byteBuf) free() (f1, f2 []byte) {
+	free := b.freeLen()
+	if free == 0 {
+		return nil, nil
+	}
+	if b.tail == b.head {
+		// Buffer is empty: the whole storage is one contiguous window
+		// starting at the head (which equals the tail).
+		return b.data[:free], nil
+	}
+	// Free space runs from the tail to the end of storage, then from 0
+	// up to the head. The first window is from tail to the end.
+	tailFree := b.cap() - b.tail
+	if tailFree >= free {
+		// All the free space is in the tail-to-end window.
+		return b.data[b.tail : b.tail+free], nil
+	}
+	// The free space wraps: return tail-to-end and 0-to-head.
+	return b.data[b.tail:], b.data[:free-tailFree]
+}
+
+// write appends data to the tail of the buffer. It returns the number of
+// bytes actually appended; once the buffer has reached or surpassed
+// maxBufferSize it returns 0.
+func (b *byteBuf) write(p []byte) int {
+	if b.len() >= maxBufferSize {
+		return 0
+	}
+	want := len(p)
+	if b.len()+want > maxBufferSize {
+		want = maxBufferSize - b.len()
+	}
+	if want == 0 {
+		return 0
+	}
+	p = p[:want]
+	b.reserve(want)
+	b1, b2 := b.free()
+	n := copy(b1, p)
+	if n < len(p) {
+		n += copy(b2, p[n:])
+	}
+	b.tail = (b.tail + n) % b.cap()
+	return n
+}
+
+// advance moves the buffer's start position forward by n, effectively
+// discarding that amount of data from the head. If this advancement passes
+// the current end, the end position is also updated to match the new start,
+// maintaining a consistent empty state.
+func (b *byteBuf) advance(n int) {
+	n = min(n, b.len())
+	b.head = (b.head + n) % b.cap()
+	if b.len() == 0 {
+		b.tail = b.head
+	}
+}
+
+// read fills dst with as much data as available from the buffer, using the
+// result of buffered to perform two copy operations. It advances the
+// internal buffer position by the number of bytes copied and returns it.
+func (b *byteBuf) read(dst []byte) int {
+	b1, b2 := b.buffered()
+	n := copy(dst, b1)
+	if n < len(dst) {
+		n += copy(dst[n:], b2)
+	}
+	b.advance(n)
+	return n
+}
+
+// deadline tracks a single deadline using a mutex, a reusable timer, and a
+// condition variable so waiters can block until the deadline fires.
+type deadline struct {
+	// mu guards the fields below.
+	mu sync.Mutex
+	// timer is the (reusable) timer that fires when the deadline is
+	// reached.
+	timer clockwork.Timer
+	// timeout is set once the deadline has passed.
+	timeout bool
+	// stopped indicates the timer is initialized but currently inactive.
+	stopped bool
+	// c is notified when the deadline is reached or cleared.
+	c *sync.Cond
+	// clock is used to create the timer for the deadline.
+	clock clockwork.Clock
+}
+
+// newDeadline returns a deadline wired to the given condition variable and
+// clock.
+func newDeadline(c *sync.Cond, clock clockwork.Clock) *deadline {
+	return &deadline{
+		c:     c,
+		clock: clock,
+	}
+}
+
+// setDeadline sets the deadline to d. Passing a zero Time clears the
+// deadline (disables it). Passing a past time marks the deadline as
+// already timed out.
+func (dl *deadline) setDeadline(d time.Time) {
+	dl.mu.Lock()
+	defer dl.mu.Unlock()
+	dl.setDeadlineLocked(d)
+}
+
+// setDeadlineLocked sets the deadline; the caller must hold dl.mu.
+//
+// It stops any existing timer (waiting for it to finish if necessary),
+// sets the timeout flag immediately if the deadline is in the past, or
+// schedules a new timer using the clock to trigger the timeout and notify
+// waiters when the deadline is reached.
+func (dl *deadline) setDeadlineLocked(d time.Time) {
+	// Stop the existing timer first.
+	if dl.timer != nil {
+		dl.timer.Stop()
+		// Drain the timer channel so a pending fire cannot leak.
+		select {
+		case <-dl.timer.Chan():
+		default:
+		}
+		dl.timer = nil
+	}
+	if d.IsZero() {
+		// Clear the deadline: disabled, no timeout.
+		dl.timeout = false
+		dl.stopped = false
+		return
+	}
+	now := dl.clock.Now()
+	if !d.After(now) {
+		// The deadline is in the past: it is already expired.
+		dl.timeout = true
+		dl.stopped = true
+		dl.c.Broadcast()
+		return
+	}
+	dl.timeout = false
+	dl.stopped = false
+	timer := dl.clock.NewTimer(d.Sub(now))
+	dl.timer = timer
+	go func() {
+		<-timer.Chan()
+		dl.mu.Lock()
+		defer dl.mu.Unlock()
+		if dl.timer != timer {
+			// Replaced or cleared before this timer fired.
+			return
+		}
+		dl.timer = nil
+		dl.timeout = true
+		dl.stopped = true
+		dl.c.Broadcast()
+	}()
+}
+
+// reset clears the deadline and stops any active timer.
+func (dl *deadline) reset() {
+	dl.mu.Lock()
+	defer dl.mu.Unlock()
+	if dl.timer != nil {
+		dl.timer.Stop()
+		select {
+		case <-dl.timer.Chan():
+		default:
+		}
+		dl.timer = nil
+	}
+	dl.timeout = false
+	dl.stopped = false
+}
+
+// timedOut reports whether the deadline has already expired.
+func (dl *deadline) timedOut() bool {
+	dl.mu.Lock()
+	defer dl.mu.Unlock()
+	return dl.timeout
+}
+
+// managedConn is a bidirectional network connection with internal
+// buffering, deadlines, and synchronization via a mutex and a condition
+// variable.
+type managedConn struct {
+	// conn is the underlying connection.
+	conn net.Conn
+
+	// mu guards all fields below and is shared with the condition
+	// variable.
+	mu sync.Mutex
+
+	// c is the condition variable notified on state changes (deadline
+	// expiry, close, data availability).
+	c *sync.Cond
+
+	// clock is used to schedule deadline timers.
+	clock clockwork.Clock
+
+	// readDeadline and writeDeadline track the respective deadlines.
+	readDeadline  *deadline
+	writeDeadline *deadline
+
+	// readBuf stages incoming bytes; writeBuf stages outgoing bytes.
+	readBuf  *byteBuf
+	writeBuf *byteBuf
+
+	// locallyClosed indicates Close() has been called.
+	locallyClosed bool
+	// remotelyClosed indicates the remote peer closed the connection.
+	remotelyClosed bool
+}
+
+// newManagedConn wraps conn in a managed connection, initializing the
+// condition variable with the connection mutex.
+func newManagedConn(conn net.Conn) *managedConn {
+	m := &managedConn{
+		conn:     conn,
+		clock:    clockwork.NewRealClock(),
+		readBuf:  newByteBuf(),
+		writeBuf: newByteBuf(),
+	}
+	m.c = sync.NewCond(&m.mu)
+	m.readDeadline = newDeadline(m.c, m.clock)
+	m.writeDeadline = newDeadline(m.c, m.clock)
+	return m
+}
+
+// Close marks the connection as locally closed, stops any active deadline
+// timers, and notifies waiters via the condition variable. It returns
+// net.ErrClosed if the connection is already closed.
+func (m *managedConn) Close() error {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+	if m.locallyClosed {
+		return net.ErrClosed
+	}
+	m.locallyClosed = true
+	m.readDeadline.reset()
+	m.writeDeadline.reset()
+	m.c.Broadcast()
+	return nil
+}
+
+// Read implements io.Reader. It returns an error on local closure or an
+// expired read deadline, allows zero-length reads unconditionally, returns
+// data when available (notifying waiters), and returns io.EOF if the remote
+// is closed and no data remains.
+func (m *managedConn) Read(p []byte) (int, error) {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+	if len(p) == 0 {
+		return 0, nil
+	}
+	if m.locallyClosed {
+		return 0, net.ErrClosed
+	}
+	if m.readDeadline.timedOut() {
+		return 0, net.ErrClosed
+	}
+	for m.readBuf.len() == 0 && !m.remotelyClosed {
+		m.c.Wait()
+		if m.locallyClosed {
+			return 0, net.ErrClosed
+		}
+		if m.readDeadline.timedOut() {
+			return 0, net.ErrClosed
+		}
+	}
+	n := m.readBuf.read(p)
+	if n > 0 {
+		// Notify waiters that buffer space has been freed.
+		m.c.Signal()
+		return n, nil
+	}
+	if m.remotelyClosed {
+		return 0, io.EOF
+	}
+	return 0, nil
+}
+
+// Write implements io.Writer. It returns an error if the connection is
+// locally closed, the write deadline has passed, or the remote side is
+// closed. Zero-length inputs are silently accepted.
+func (m *managedConn) Write(p []byte) (int, error) {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+	if len(p) == 0 {
+		return 0, nil
+	}
+	if m.locallyClosed {
+		return 0, net.ErrClosed
+	}
+	if m.writeDeadline.timedOut() {
+		return 0, net.ErrClosed
+	}
+	if m.remotelyClosed {
+		return 0, trace.BadParameter("connection is closed by remote peer")
+	}
+	n := m.writeBuf.write(p)
+	if n < len(p) {
+		// Back-pressure: the buffer is full.
+		return n, trace.LimitExceeded("write buffer is full")
+	}
+	m.c.Signal()
+	return n, nil
+}
+
+// SetDeadline sets the read and write deadlines.
+func (m *managedConn) SetDeadline(t time.Time) error {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+	if m.locallyClosed {
+		return net.ErrClosed
+	}
+	m.readDeadline.setDeadlineLocked(t)
+	m.writeDeadline.setDeadlineLocked(t)
+	return nil
+}
+
+// SetReadDeadline sets the read deadline.
+func (m *managedConn) SetReadDeadline(t time.Time) error {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+	if m.locallyClosed {
+		return net.ErrClosed
+	}
+	m.readDeadline.setDeadlineLocked(t)
+	return nil
+}
+
+// SetWriteDeadline sets the write deadline.
+func (m *managedConn) SetWriteDeadline(t time.Time) error {
+	m.mu.Lock()
+	defer m.mu.Unlock()
+	if m.locallyClosed {
+		return net.ErrClosed
+	}
+	m.writeDeadline.setDeadlineLocked(t)
+	return nil
+}
+
+// LocalAddr returns the local address of the underlying connection.
+func (m *managedConn) LocalAddr() net.Addr {
+	return m.conn.LocalAddr()
+}
+
+// RemoteAddr returns the remote address of the underlying connection.
+func (m *managedConn) RemoteAddr() net.Addr {
+	return m.conn.RemoteAddr()
+}
+
+var _ net.Conn = (*managedConn)(nil)
