+func TestByteBufWraparound(t *testing.T) {
+	b := newByteBuf()
+	data := make([]byte, 300)
+	for i := range data {
+		data[i] = byte(i)
+	}
+	n := b.write(data)
+	if n != 300 {
+		t.Fatalf("wrote %d, want 300", n)
+	}
+	if b.len() != 300 {
+		t.Fatalf("len = %d, want 300", b.len())
+	}
+	b1, b2 := b.buffered()
+	if len(b1)+len(b2) != 300 {
+		t.Fatalf("buffered len = %d+%d, want 300", len(b1), len(b2))
+	}
+	got := make([]byte, 0, 300)
+	got = append(got, b1...)
+	got = append(got, b2...)
+	for i := 0; i < 300; i++ {
+		if got[i] != data[i] {
+			t.Fatalf("byte %d = %d, want %d", i, got[i], data[i])
+		}
+	}
+
+	dst := make([]byte, 150)
+	if r := b.read(dst); r != 150 {
+		t.Fatalf("read %d, want 150", r)
+	}
+	if b.len() != 150 {
+		t.Fatalf("after read len = %d, want 150", b.len())
+	}
+	f1, f2 := b.free()
+	if len(f1)+len(f2) != b.cap()-b.len() {
+		t.Fatalf("free = %d+%d, want %d", len(f1), len(f2), b.cap()-b.len())
+	}
+}
+
+func TestByteBufForceWrap(t *testing.T) {
+	b := newByteBuf()
+	// Write enough to force the tail to lap the head.
+	b.write(make([]byte, 16000)) // 16000 < 16384, no wrap yet
+	b.advance(15000)             // 1000 buffered, head=15000
+	b.write(make([]byte, 5000))  // wraps: tail goes past 16384
+	if b.len() != 6000 {
+		t.Fatalf("len = %d, want 6000", b.len())
+	}
+	if b.tail >= b.head {
+		t.Fatalf("expected wraparound: tail=%d head=%d", b.tail, b.head)
+	}
+	b1, b2 := b.buffered()
+	if len(b1) == 0 || len(b2) == 0 {
+		t.Fatalf("wrapped buffered should have both slices: %d+%d", len(b1), len(b2))
+	}
+	if len(b1)+len(b2) != 6000 {
+		t.Fatalf("buffered = %d+%d, want 6000", len(b1), len(b2))
+	}
+	f1, f2 := b.free()
+	if len(f1)+len(f2) != b.cap()-b.len() {
+		t.Fatalf("free = %d+%d, want %d", len(f1), len(f2), b.cap()-b.len())
+	}
+}
+
+func TestByteBufEmpty(t *testing.T) {
+	b := newByteBuf()
+	b.write([]byte{1})
+	b.advance(1)
+	b1, b2 := b.buffered()
+	if len(b1)+len(b2) != 0 {
+		t.Fatalf("empty buffer has data: %d+%d", len(b1), len(b2))
+	}
+	f1, f2 := b.free()
+	if len(f1)+len(f2) != b.cap() {
+		t.Fatalf("empty free = %d+%d, want %d", len(f1), len(f2), b.cap())
+	}
+}
+
+func TestByteBufInitialCapacity(t *testing.T) {
+	b := newByteBuf()
+	b.write([]byte{1})
+	if b.cap() != 16384 {
+		t.Fatalf("initial cap = %d, want 16384", b.cap())
+	}
+	b.advance(1)
+	if b.cap() != 16384 {
+		t.Fatalf("cap after advance = %d, want 16384 (must not shrink)", b.cap())
+	}
+	f1, f2 := b.free()
+	if len(f1)+len(f2) != 16384 {
+		t.Fatalf("free after drain = %d+%d, want 16384", len(f1), len(f2))
+	}
+}
+
+func TestByteBufGrow(t *testing.T) {
+	b := newByteBuf()
+	b.write(make([]byte, 10000))
+	b.advance(1000) // 9000 buffered
+	capBefore := b.cap()
+	b.write(make([]byte, 9000)) // 18000 > 16384, must grow
+	if b.len() != 18000 {
+		t.Fatalf("len = %d, want 18000", b.len())
+	}
+	if b.cap() <= capBefore {
+		t.Fatalf("cap = %d, want > %d", b.cap(), capBefore)
+	}
+	got := make([]byte, 18000)
+	if r := b.read(got); r != 18000 {
+		t.Fatalf("read %d, want 18000", r)
+	}
+	if b.len() != 0 {
+		t.Fatalf("len after drain = %d, want 0", b.len())
+	}
+}
+
+func TestByteBufAdvancePastEnd(t *testing.T) {
+	b := newByteBuf()
+	b.write([]byte{1, 2, 3})
+	b.advance(10) // past end
+	if b.len() != 0 {
+		t.Fatalf("len = %d, want 0", b.len())
+	}
+}
+
+func TestManagedConnClose(t *testing.T) {
+	c1, _ := net.Pipe()
+	mc := newManagedConn(c1)
+	if err := mc.Close(); err != nil {
+		t.Fatalf("first close: %v", err)
+	}
+	if err := mc.Close(); err != net.ErrClosed {
+		t.Fatalf("second close = %v, want net.ErrClosed", err)
+	}
+}
+
+func TestManagedConnReadWrite(t *testing.T) {
+	c1, _ := net.Pipe()
+	mc := newManagedConn(c1)
+	if n, err := mc.Read(nil); n != 0 || err != nil {
+		t.Fatalf("zero read: n=%d err=%v", n, err)
+	}
+	if n, err := mc.Write(nil); n != 0 || err != nil {
+		t.Fatalf("zero write: n=%d err=%v", n, err)
+	}
+	done := make(chan struct{})
+	go func() {
+		mc.Read(make([]byte, 1))
+		close(done)
+	}()
+	time.Sleep(10 * time.Millisecond)
+	mc.Close()
+	select {
+	case <-done:
+	case <-time.After(time.Second):
+		t.Fatal("read did not unblock after close")
+	}
+}
+
+func TestManagedConnWriteAfterClose(t *testing.T) {
+	c1, _ := net.Pipe()
+	mc := newManagedConn(c1)
+	if err := mc.Close(); err != nil {
+		t.Fatal(err)
+	}
+	if _, err := mc.Write([]byte{1}); err != net.ErrClosed {
+		t.Fatalf("write after close = %v, want net.ErrClosed", err)
+	}
+	if _, err := mc.Read(make([]byte, 1)); err != net.ErrClosed {
+		t.Fatalf("read after close = %v, want net.ErrClosed", err)
+	}
+}
+
+func TestDeadlinePast(t *testing.T) {
+	c1, _ := net.Pipe()
+	mc := newManagedConn(c1)
+	mc.SetReadDeadline(time.Now().Add(-time.Hour))
+	if _, err := mc.Read(make([]byte, 1)); err == nil {
+		t.Fatal("read with expired deadline should fail")
+	}
+}
+
+func TestDeadlineFires(t *testing.T) {
+	c1, _ := net.Pipe()
+	mc := newManagedConn(c1)
+	mc.SetReadDeadline(time.Now().Add(50 * time.Millisecond))
+	done := make(chan struct{})
+	go func() {
+		mc.Read(make([]byte, 1))
+		close(done)
+	}()
+	select {
+	case <-done:
+	case <-time.After(2 * time.Second):
+		t.Fatal("read did not return after deadline fired")
+	}
+}
+
+func TestManagedConnSetDeadlines(t *testing.T) {
+	c1, _ := net.Pipe()
+	mc := newManagedConn(c1)
+	if err := mc.SetDeadline(time.Now().Add(time.Hour)); err != nil {
+		t.Fatal(err)
+	}
+	if err := mc.SetReadDeadline(time.Time{}); err != nil {
+		t.Fatal(err)
+	}
+	if err := mc.SetWriteDeadline(time.Time{}); err != nil {
+		t.Fatal(err)
+	}
+	if err := mc.SetDeadline(time.Time{}); err != nil {
+		t.Fatal(err)
+	}
+	done := make(chan struct{})
+	go func() {
+		mc.Read(make([]byte, 1))
+		close(done)
+	}()
+	time.Sleep(10 * time.Millisecond)
+	mc.Close()
+	select {
+	case <-done:
+	case <-time.After(time.Second):
+		t.Fatal("read did not unblock")
+	}
+}

