+// TLSAcceptableCAsSize returns the total size, in bytes, of the CA subjects
+// that would be advertised to a TLS client in the CertificateRequest
+// message: each subject gets a separate 2-byte length prefix per
+// https://tools.ietf.org/html/rfc5246#section-7.4.4. The message can't
+// exceed 2^16-1 bytes (due to the 2-byte length encoding) and the
+// crypto/tls stack panics if it does.
+func TLSAcceptableCAsSize(pool *x509.CertPool) int {
+	total := 0
+	for _, s := range pool.Subjects() {
+		total += 2 + len(s)
+	}
+	return total
+}
+
+// ClientHostCertPool returns a pool containing only the certificate
+// authorities of the given cluster's Host CA. It is a minimal, valid subset
+// of ClientCertPool used when the full list of trusted CAs would exceed the
+// TLS handshake size limit (see TLSAcceptableCAsSize): clients connecting
+// to a cluster's endpoints are signed by one of that cluster's CAs, and
+// crypto/tls verifies client certificates against ClientCAs rather than the
+// advertised (acceptable) CA subjects.
+func ClientHostCertPool(client AccessCache, clusterName string) (*x509.CertPool, error) {
+	pool := x509.NewCertPool()
+	hostCAs, err := client.GetCertAuthorities(services.HostCA, false, services.SkipValidation())
+	if err != nil {
+		return nil, trace.Wrap(err)
+	}
+	for _, hostCA := range hostCAs {
+		if hostCA.GetClusterName() != clusterName {
+			continue
+		}
+		for _, keyPair := range hostCA.GetTLSKeyPairs() {
+			cert, err := tlsca.ParseCertificatePEM(keyPair.Cert)
+			if err != nil {
+				return nil, trace.Wrap(err)
+			}
+			log.Debugf("ClientHostCertPool -> %v", CertInfo(cert))
+			pool.AddCert(cert)
+		}
+	}
+	return pool, nil
+}
