+// ---------- test CA / certificate helpers ----------
+
+// newTestCA generates a self-signed CA with the organization name set to
+// clusterName (the same way Teleport generates cluster CAs) and wraps it
+// into a CertAuthority resource of the given type.
+func newTestCA(t *testing.T, clusterName string, caType services.CertAuthType) services.CertAuthority {
+	t.Helper()
+	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
+	if err != nil {
+		t.Fatal(err)
+	}
+	serialNumberLimit := new(big.Int).Lsh(big.NewInt(1), 128)
+	serial, err := rand.Int(rand.Reader, serialNumberLimit)
+	if err != nil {
+		t.Fatal(err)
+	}
+	// pad the subject so CA subjects are large enough that a root cluster
+	// with hundreds of trusted leaf clusters exceeds the TLS handshake
+	// limit (real cluster names / CAs are of similar size)
+	padded := clusterName
+	for len(padded) < 120 {
+		padded += "a"
+	}
+	template := x509.Certificate{
+		SerialNumber:          serial,
+		Subject:               pkix.Name{CommonName: "test-ca", Organization: []string{padded}},
+		NotBefore:             time.Now().Add(-time.Hour),
+		NotAfter:              time.Now().Add(24 * time.Hour),
+		KeyUsage:              x509.KeyUsageCertSign,
+		BasicConstraintsValid: true,
+		IsCA:                  true,
+	}
+	der, err := x509.CreateCertificate(rand.Reader, &template, &template, &key.PublicKey, key)
+	if err != nil {
+		t.Fatal(err)
+	}
+	certPEM := pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: der})
+	keyDER, err := x509.MarshalPKCS8PrivateKey(key)
+	if err != nil {
+		t.Fatal(err)
+	}
+	keyPEM := pem.EncodeToMemory(&pem.Block{Type: "PRIVATE KEY", Bytes: keyDER})
+	return types.NewCertAuthority(types.CertAuthoritySpecV2{
+		ClusterName: clusterName,
+		Type:        caType,
+		TLSKeyPairs: []types.TLSKeyPair{{Cert: certPEM, Key: keyPEM}},
+	})
+}
+
+func caKey(t *testing.T, ca services.CertAuthority) *ecdsa.PrivateKey {
+	t.Helper()
+	keyPairs := ca.GetTLSKeyPairs()
+	if len(keyPairs) == 0 {
+		t.Fatal("CA has no key pairs")
+	}
+	key, err := tlsca.ParsePrivateKeyPEM(keyPairs[0].Key)
+	if err != nil {
+		t.Fatal(err)
+	}
+	ecdsaKey, ok := key.(*ecdsa.PrivateKey)
+	if !ok {
+		t.Fatalf("expected ECDSA CA key, got %T", key)
+	}
+	return ecdsaKey
+}
+
+func caCert(t *testing.T, ca services.CertAuthority) *x509.Certificate {
+	t.Helper()
+	keyPairs := ca.GetTLSKeyPairs()
+	if len(keyPairs) == 0 {
+		t.Fatal("CA has no key pairs")
+	}
+	cert, err := tlsca.ParseCertificatePEM(keyPairs[0].Cert)
+	if err != nil {
+		t.Fatal(err)
+	}
+	return cert
+}
+
+// newTestClientCert generates a client certificate (with
+// ExtKeyUsageClientAuth) signed by the given CA.
+func newTestClientCert(t *testing.T, ca services.CertAuthority, commonName string) tls.Certificate {
+	t.Helper()
+	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
+	if err != nil {
+		t.Fatal(err)
+	}
+	serialNumberLimit := new(big.Int).Lsh(big.NewInt(1), 128)
+	serial, err := rand.Int(rand.Reader, serialNumberLimit)
+	if err != nil {
+		t.Fatal(err)
+	}
+	template := x509.Certificate{
+		SerialNumber:          serial,
+		Subject:               pkix.Name{CommonName: commonName, Organization: []string{ca.GetClusterName()}},
+		NotBefore:             time.Now().Add(-time.Hour),
+		NotAfter:              time.Now().Add(24 * time.Hour),
+		KeyUsage:              x509.KeyUsageDigitalSignature,
+		ExtKeyUsage:           []x509.ExtKeyUsage{x509.ExtKeyUsageClientAuth},
+		BasicConstraintsValid: true,
+	}
+	der, err := x509.CreateCertificate(rand.Reader, &template, caCert(t, ca), &key.PublicKey, caKey(t, ca))
+	if err != nil {
+		t.Fatal(err)
+	}
+	return tls.Certificate{Certificate: [][]byte{der}, PrivateKey: key}
+}
+
+// newTestServerCert generates a server certificate signed by the given CA.
+func newTestServerCert(t *testing.T, ca services.CertAuthority) tls.Certificate {
+	t.Helper()
+	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
+	if err != nil {
+		t.Fatal(err)
+	}
+	serialNumberLimit := new(big.Int).Lsh(big.NewInt(1), 128)
+	serial, err := rand.Int(rand.Reader, serialNumberLimit)
+	if err != nil {
+		t.Fatal(err)
+	}
+	template := x509.Certificate{
+		SerialNumber:          serial,
+		Subject:               pkix.Name{CommonName: "127.0.0.1"},
+		NotBefore:             time.Now().Add(-time.Hour),
+		NotAfter:              time.Now().Add(24 * time.Hour),
+		KeyUsage:              x509.KeyUsageDigitalSignature,
+		ExtKeyUsage:           []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth},
+		IPAddresses:           []net.IP{net.ParseIP("127.0.0.1")},
+		DNSNames:              []string{"127.0.0.1"},
+		BasicConstraintsValid: true,
+	}
+	der, err := x509.CreateCertificate(rand.Reader, &template, caCert(t, ca), &key.PublicKey, caKey(t, ca))
+	if err != nil {
+		t.Fatal(err)
+	}
+	return tls.Certificate{Certificate: [][]byte{der}, PrivateKey: key}
+}
