+// testAccessPoint is a minimal auth.AccessPoint implementation (built on
+// top of auth.ClientI) that serves pre-provisioned certificate authorities.
+type testAccessPoint struct {
+	auth.ClientI
+
+	clusterName string
+	hostCAs     []services.CertAuthority
+	userCAs     []services.CertAuthority
+}
+
+func (f *testAccessPoint) GetCertAuthority(id services.CertAuthID, loadKeys bool, opts ...services.MarshalOption) (services.CertAuthority, error) {
+	list := f.hostCAs
+	if id.Type == services.UserCA {
+		list = f.userCAs
+	}
+	for _, ca := range list {
+		if ca.GetClusterName() == id.DomainName {
+			return ca, nil
+		}
+	}
+	return nil, trace.NotFound("cert authority %v not found", id)
+}
+
+func (f *testAccessPoint) GetCertAuthorities(caType services.CertAuthType, loadKeys bool, opts ...services.MarshalOption) ([]services.CertAuthority, error) {
+	if caType == services.UserCA {
+		return f.userCAs, nil
+	}
+	return f.hostCAs, nil
+}
