+func (f *testAccessPoint) GetClusterConfig(opts ...services.MarshalOption) (services.ClusterConfig, error) {
+	cc, err := services.NewClusterConfig(services.ClusterConfigSpecV3{})
+	if err != nil {
+		return nil, trace.Wrap(err)
+	}
+	return cc, nil
+}
+
+func (f *testAccessPoint) GetClusterName(opts ...services.MarshalOption) (services.ClusterName, error) {
