+// newTestTLSServer builds a kubernetes proxy TLSServer. The returned server
+// is not serving; tests either call GetConfigForClient directly or start
+// Serve on a listener.
+func newTestTLSServer(t *testing.T, ap *testAccessPoint, baseConfig *tls.Config) *TLSServer {
+	t.Helper()
+	server, err := NewTLSServer(TLSServerConfig{
+		ForwarderConfig: ForwarderConfig{
+			ClusterName:       ap.clusterName,
+			DataDir:           t.TempDir(),
+			ServerID:          "test-proxy",
+			AuthClient:        ap,
+			CachingAuthClient: ap,
+			Authz:             testAuthorizer{},
+			Keygen:            testauthority.New(),
+			StreamEmitter:     events.NewDiscardEmitter(),
+		},
+		TLS:         baseConfig,
+		AccessPoint: ap,
+	})
+	if err != nil {
+		t.Fatal(err)
+	}
+	t.Cleanup(func() { server.Close() })
+	return server
+}
+
+func newTestBaseTLSConfig(t *testing.T) *tls.Config {
+	t.Helper()
+	serverCA := newTestCA(t, "test-server-ca", services.HostCA)
+	serverCert := newTestServerCert(t, serverCA)
+	pool := x509.NewCertPool()
+	pool.AddCert(caCert(t, serverCA))
+	return &tls.Config{
+		Certificates: []tls.Certificate{serverCert},
+		ClientAuth:   tls.RequireAndVerifyClientCert,
+		ClientCAs:    pool,
+		RootCAs:      pool,
+		MinVersion:   tls.VersionTLS12,
+	}
+}
+
+// startServing starts the server on a random localhost port and returns the
+// address.
+func startServing(t *testing.T, server *TLSServer) string {
+	t.Helper()
+	listener, err := net.Listen("tcp", "127.0.0.1:0")
+	if err != nil {
+		t.Fatal(err)
+	}
+	addr := listener.Addr().String()
+	go func() {
+		server.Serve(listener)
+	}()
+	t.Cleanup(func() { listener.Close() })
+	return addr
+}
