+// ---------- tests ----------
+
+// TestGetConfigForClientFullList verifies that when the client CA list fits
+// within TLS handshake limits, GetConfigForClient returns a per-connection
+// clone of the base config whose ClientCAs include all trusted cluster CAs,
+// with all other base settings preserved and the base config untouched.
+func TestGetConfigForClientFullList(t *testing.T) {
+	const rootClusterName = "root-cluster"
+	ap := &testAccessPoint{
+		clusterName: rootClusterName,
+		hostCAs: []services.CertAuthority{
+			newTestCA(t, rootClusterName, services.HostCA),
+			newTestCA(t, "leaf-cluster-1", services.HostCA),
+			newTestCA(t, "leaf-cluster-2", services.HostCA),
+		},
+		userCAs: []services.CertAuthority{newTestCA(t, rootClusterName+"-user", services.UserCA)},
+	}
+	base := newTestBaseTLSConfig(t)
+	server := newTestTLSServer(t, ap, base)
+
+	cfg, err := server.GetConfigForClient(&tls.ClientHelloInfo{ServerName: ""})
+	if err != nil {
+		t.Fatal(err)
+	}
+	// per-connection config, not the base config
+	if cfg == base {
+		t.Fatal("GetConfigForClient returned the base config instead of a per-connection copy")
+	}
+	// all other base settings preserved (ClientAuth is set to
+	// VerifyClientCertIfGiven by NewTLSServer, both on the base config and
+	// on every per-connection clone)
+	if cfg.ClientAuth != tls.VerifyClientCertIfGiven {
+		t.Fatalf("ClientAuth not preserved: got %v, want %v", cfg.ClientAuth, tls.VerifyClientCertIfGiven)
+	}
+	if len(cfg.Certificates) != len(base.Certificates) {
+		t.Fatalf("Certificates not preserved: got %d, want %d", len(cfg.Certificates), len(base.Certificates))
+	}
+	if cfg.MinVersion != base.MinVersion {
+		t.Fatalf("MinVersion not preserved: got %v, want %v", cfg.MinVersion, base.MinVersion)
+	}
+	if cfg.RootCAs != base.RootCAs {
+		t.Fatal("RootCAs not preserved")
+	}
+	// ClientCAs must include all trusted cluster CAs (3 host + 1 user)
+	fullPool, err := auth.ClientCertPool(ap, "")
+	if err != nil {
+		t.Fatal(err)
+	}
+	if len(fullPool.Subjects()) != 4 {
+		t.Fatalf("expected 4 CAs in full pool, got %d", len(fullPool.Subjects()))
+	}
+	if len(cfg.ClientCAs.Subjects()) != 4 {
+		t.Fatalf("per-connection ClientCAs has %d subjects, want %d (all trusted CAs)",
+			len(cfg.ClientCAs.Subjects()), 4)
+	}
+	// the advertised leaf CA subjects must be present
+	wantLeaf := caCert(t, ap.hostCAs[1]).RawSubject
+	found := false
+	for _, s := range cfg.ClientCAs.Subjects() {
+		if string(s) == string(wantLeaf) {
+			found = true
+		}
+	}
+	if !found {
+		t.Fatalf("trusted leaf CA subject missing from per-connection ClientCAs")
+	}
+	// base config must not be mutated
+	if len(base.ClientCAs.Subjects()) != 1 {
+		t.Fatalf("base config was mutated: ClientCAs now has %d subjects, want 1", len(base.ClientCAs.Subjects()))
+	}
+	if base.ClientAuth != tls.VerifyClientCertIfGiven {
+		t.Fatalf("base config ClientAuth changed: %v", base.ClientAuth)
+	}
+}
+
+// TestGetConfigForClientReducedList verifies that when the client CA list
+// would exceed the TLS handshake size limit (a root cluster with hundreds
+// of trusted leaf clusters), GetConfigForClient returns a per-connection
+// config whose ClientCAs contain only the current cluster's Host CAs, so
+// the handshake does not overflow the 2^16-1 byte limit.
+func TestGetConfigForClientReducedList(t *testing.T) {
+	const rootClusterName = "root-cluster"
+	const numLeafClusters = 500
+	ap := &testAccessPoint{
+		clusterName: rootClusterName,
+		hostCAs:     make([]services.CertAuthority, numLeafClusters+1),
+	}
+	ap.hostCAs[0] = newTestCA(t, rootClusterName, services.HostCA)
+	for i := 1; i <= numLeafClusters; i++ {
+		ap.hostCAs[i] = newTestCA(t, fmt.Sprintf("leaf-cluster-large-%03d", i), services.HostCA)
+	}
+	ap.userCAs = []services.CertAuthority{newTestCA(t, rootClusterName+"-user", services.UserCA)}
+
+	// sanity check: the full list really exceeds the TLS limit
+	fullPool, err := auth.ClientCertPool(ap, "")
+	if err != nil {
+		t.Fatal(err)
+	}
+	if auth.TLSAcceptableCAsSize(fullPool) <= math.MaxUint16-1 {
+		t.Fatalf("test setup broken: full CA pool (%d bytes) should exceed the %d byte TLS handshake limit",
+			auth.TLSAcceptableCAsSize(fullPool), math.MaxUint16-1)
+	}
+
+	base := newTestBaseTLSConfig(t)
+	server := newTestTLSServer(t, ap, base)
+
+	cfg, err := server.GetConfigForClient(&tls.ClientHelloInfo{ServerName: ""})
+	if err != nil {
+		t.Fatal(err)
+	}
+	// per-connection config
+	if cfg == base {
+		t.Fatal("GetConfigForClient returned the base config instead of a per-connection copy")
+	}
+	// ClientCAs must contain exactly the current cluster's Host CAs:
+	// 501 host CAs total, only 1 of which belongs to the current cluster
+	if len(ap.hostCAs) != numLeafClusters+1 {
+		t.Fatalf("test setup broken: expected %d host CAs", numLeafClusters+1)
+	}
+	wantCount := 1 // only the root cluster's own host CA
+	if len(cfg.ClientCAs.Subjects()) != wantCount {
+		t.Fatalf("per-connection ClientCAs has %d subjects, want %d (current cluster Host CA only)",
+			len(cfg.ClientCAs.Subjects()), wantCount)
+	}
+	wantSubject := caCert(t, ap.hostCAs[0]).RawSubject
+	if string(cfg.ClientCAs.Subjects()[0]) != string(wantSubject) {
+		t.Fatalf("per-connection ClientCAs subject = %q, want current cluster Host CA %q",
+			cfg.ClientCAs.Subjects()[0], wantSubject)
+	}
+	// and the advertised size must now fit within the TLS limit
+	if auth.TLSAcceptableCAsSize(cfg.ClientCAs) >= math.MaxUint16 {
+		t.Fatalf("reduced pool still exceeds the TLS handshake limit: %d bytes", auth.TLSAcceptableCAsSize(cfg.ClientCAs))
+	}
+	// other base settings preserved
+	if cfg.ClientAuth != tls.VerifyClientCertIfGiven {
+		t.Fatalf("ClientAuth not preserved: got %v, want %v", cfg.ClientAuth, tls.VerifyClientCertIfGiven)
+	}
+	if len(cfg.Certificates) != len(base.Certificates) {
+		t.Fatal("Certificates not preserved")
+	}
+	if cfg.MinVersion != base.MinVersion {
+		t.Fatalf("MinVersion not preserved: got %v, want %v", cfg.MinVersion, base.MinVersion)
+	}
+	// base config must not be mutated
+	if len(base.ClientCAs.Subjects()) != 1 {
+		t.Fatalf("base config was mutated: ClientCAs now has %d subjects, want 1", len(base.ClientCAs.Subjects()))
+	}
+	if base.ClientAuth != tls.VerifyClientCertIfGiven {
+		t.Fatalf("base config ClientAuth changed: %v", base.ClientAuth)
+	}
+}
