+// TestGetConfigForClientHandshake verifies end-to-end that the mTLS
+// handshake succeeds and that a real TLS client observes the full trusted
+// CA set via CertificateRequestInfo.AcceptableCAs when the list fits
+// within TLS handshake limits.
+func TestGetConfigForClientHandshake(t *testing.T) {
+	const rootClusterName = "root-cluster"
+	ap := &testAccessPoint{
+		clusterName: rootClusterName,
+		hostCAs: []services.CertAuthority{
+			newTestCA(t, rootClusterName, services.HostCA),
+			newTestCA(t, "leaf-cluster-1", services.HostCA),
+			newTestCA(t, "leaf-cluster-2", services.HostCA),
+		},
+		userCAs: []services.CertAuthority{newTestCA(t, rootClusterName+"-user", services.UserCA)},
+	}
+	base := newTestBaseTLSConfig(t)
+	server := newTestTLSServer(t, ap, base)
+	addr := startServing(t, server)
+
+	// client signed by a trusted leaf cluster's CA
+	clientCert := newTestClientCert(t, ap.hostCAs[1], "client-handshake")
+
+	conn, err := tls.Dial("tcp", addr, &tls.Config{
+		Certificates: []tls.Certificate{clientCert},
+		RootCAs:      base.RootCAs, // trust the test server CA
+		ServerName:   "",           // no SNI -> server advertises all CAs
+	})
+	if err != nil {
+		t.Fatalf("mTLS handshake failed: %v", err)
+	}
+	defer conn.Close()
+
+	state := conn.ConnectionState()
+	if len(state.PeerCertificates) == 0 {
+		t.Fatal("no server certificates presented")
+	}
+	if state.PeerCertificates[0].Subject.CommonName != "127.0.0.1" {
