+// laPolicyAvailable checks whether a local authentication policy allows Touch
+// ID (or other biometrics) to be used, without user interaction.
+func laPolicyAvailable() (bool, error) {
+	// First try the biometrics policy, then fall back to the passcode policy.
+	var errMsgC *C.char
+	for _, policy := range []int{policyBiometrics, policyPasscode} {
+		C.free(unsafe.Pointer(errMsgC))
+		switch C.EvaluatePolicy(C.int(policy), &errMsgC) {
+		case 1: // available
+			C.free(unsafe.Pointer(errMsgC))
+			return true, nil
+		case 0: // not available, try next policy
+			C.free(unsafe.Pointer(errMsgC))
+		}
+	}
+	// None of the policies are available.
+	C.free(unsafe.Pointer(errMsgC))
+	return false, nil
+}
+
+const (
+	policyPasscode   = 0 // LAPolicyDeviceOwnerAuthentication
+	policyBiometrics = 1 // LAPolicyDeviceOwnerAuthenticationWithBiometrics
