+// MaskKeyName masks the supplied key name by replacing the first 75% of its
+// bytes with '*' and returns the masked value as a byte slice. The final 25%
+// of the key is left visible, and the masked value always has the same length
+// as the original key.
+func MaskKeyName(keyName string) []byte {
+	masked := []byte(keyName)
+	numAsterisks := int(0.75 * float64(len(masked)))
+	for i := 0; i < numAsterisks; i++ {
+		masked[i] = '*'
+	}
+	return masked
+}
