+// waitForStatusWithRetry waits for the endpoint to report one of the given
+// status codes, retrying for up to the given timeout. The optional action
+// is executed on each retry iteration.
+func waitForStatusWithRetry(diagAddr string, timeout time.Duration, action func(), statusCodes ...int) error {
+	deadline := time.Now().Add(timeout)
+	for {
+		if action != nil {
+			action()
+		}
+		if err := waitForStatus(diagAddr, statusCodes...); err == nil {
+			return nil
+		}
+		if time.Now().After(deadline) {
+			return trace.BadParameter("timeout waiting for status %v", statusCodes)
+		}
+		time.Sleep(250 * time.Millisecond)
+	}
+}
+
