diff --git a/server/subsonic/zz_osx_verify_test.go b/server/subsonic/zz_osx_verify_test.go
new file mode 100644
index 00000000..cfadcbaa
--- /dev/null
+++ b/server/subsonic/zz_osx_verify_test.go
@@ -0,0 +1,99 @@
+package subsonic
+
+import (
+	"encoding/json"
+	"strings"
+	"net/http"
+	"net/http/httptest"
+	"testing"
+
+	"github.com/navidrome/navidrome/server/subsonic/responses"
+	"github.com/navidrome/navidrome/tests"
+)
+
+func TestGetOpenSubsonicExtensionsPublic(t *testing.T) {
+	ds := &tests.MockDataStore{}
+	ds.MockedUser = tests.CreateMockUserRepo()
+	api := New(ds, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil)
+	srv := httptest.NewServer(api.Handler)
+	defer srv.Close()
+
+	checkPublic := func(name, url string) {
+		t.Helper()
+		resp, err := http.Get(url)
+		if err != nil {
+			t.Fatal(err)
+		}
+		defer resp.Body.Close()
+		if resp.StatusCode != 200 {
+			t.Fatalf("%s: status = %d, want 200", name, resp.StatusCode)
+		}
+		var wrapper responses.JsonWrapper
+		if err := json.NewDecoder(resp.Body).Decode(&wrapper); err != nil {
+			t.Fatalf("%s: decode: %v", name, err)
+		}
+		sub := wrapper.Subsonic
+		if sub.Status != "ok" {
+			t.Fatalf("%s: status = %q, want ok", name, sub.Status)
+		}
+		if sub.Error != nil {
+			t.Fatalf("%s: unexpected error %v", name, sub.Error)
+		}
+		extensions := sub.OpenSubsonicExtensions
+		if extensions == nil || len(*extensions) != 3 {
+			t.Fatalf("%s: expected 3 extensions, got %v", name, extensions)
+		}
+		want := map[string]bool{"transcodeOffset": false, "formPost": false, "songLyrics": false}
+		for _, e := range *extensions {
+			if _, ok := want[e.Name]; !ok {
+				t.Fatalf("%s: unexpected extension %q", name, e.Name)
+			}
+			want[e.Name] = true
+		}
+		for n, seen := range want {
+			if !seen {
+				t.Fatalf("%s: missing extension %q", name, n)
+			}
+		}
+	}
+
+	checkPublic("no-creds", srv.URL+"/getOpenSubsonicExtensions?f=json")
+	checkPublic("bogus-creds", srv.URL+"/getOpenSubsonicExtensions?u=foo&p=bar&c=test&v=1.16.1&f=json")
+
+	// form-encoded body (postFormToQueryParams must still convert it)
+	respForm, err := http.Post(srv.URL+"/getOpenSubsonicExtensions", "application/x-www-form-urlencoded",
+		strings.NewReader("f=json&u=foo&p=bar"))
+	if err != nil {
+		t.Fatal(err)
+	}
+	defer respForm.Body.Close()
+	if respForm.StatusCode != 200 {
+		t.Fatalf("form-post: status = %d, want 200", respForm.StatusCode)
+	}
+	var formWrapper responses.JsonWrapper
+	if err := json.NewDecoder(respForm.Body).Decode(&formWrapper); err != nil {
+		t.Fatalf("form-post: decode: %v", err)
+	}
+	if formWrapper.Subsonic.Status != "ok" {
+		t.Fatalf("form-post: status = %q, want ok", formWrapper.Subsonic.Status)
+	}
+	if e := formWrapper.Subsonic.OpenSubsonicExtensions; e == nil || len(*e) != 3 {
+		t.Fatalf("form-post: expected 3 extensions, got %v", e)
+	}
+
+	// Sanity: protected endpoints must STILL require authentication
+	resp, err := http.Get(srv.URL + "/ping?u=foo&p=bar&c=test&v=1.16.1&f=json")
+	if err != nil {
+		t.Fatal(err)
+	}
+	defer resp.Body.Close()
+	var wrapper responses.JsonWrapper
+	if err := json.NewDecoder(resp.Body).Decode(&wrapper); err != nil {
+		t.Fatal(err)
+	}
+	if wrapper.Subsonic.Status != "failed" || wrapper.Subsonic.Error == nil ||
+		wrapper.Subsonic.Error.Code != responses.ErrorAuthenticationFail {
+		t.Fatalf("protected /ping without creds: expected auth failure, got status=%q error=%+v",
+			wrapper.Subsonic.Status, wrapper.Subsonic.Error)
+	}
+}

