new file mode 100644
index 00000000..fb6ab0be
--- /dev/null
+++ b/model/criteria/fields.go
@@ -0,0 +1,62 @@
+package criteria
+
+import (
+	"time"
+)
+
+// fieldMap translates the interface field names (e.g. "title", "loved") to
+// fully qualified SQL column names, so criteria expressions can reference
+// fields without knowing the underlying schema.
+var fieldMap = map[string]string{
+	"title":   "media_file.title",
+	"artist":  "media_file.artist",
+	"album":   "media_file.album",
+	"loved":   "annotation.starred",
+	"year":    "media_file.year",
+	"comment": "media_file.comment",
+}
+
+// GetColumn returns the fully qualified SQL column for the given field name.
+// Unknown fields are returned unchanged.
+func GetColumn(field string) string {
+	if column, ok := fieldMap[field]; ok {
+		return column
+	}
+	return field
+}
+
+// Time is a wrapper around time.Time that serializes to JSON as a string in
+// the ISO 8601 YYYY-MM-DD format.
+type Time time.Time
+
+// TimeLayout is the date layout used by the Time type.
+const TimeLayout = "2006-01-02"
+
+// MarshalJSON serializes Time to JSON as a string in ISO 8601 2006-01-02 format.
+func (t Time) MarshalJSON() ([]byte, error) {
+	return []byte(`"` + time.Time(t).Format(TimeLayout) + `"`), nil
+}
+
+// UnmarshalJSON deserializes Time from a JSON string in ISO 8601 2006-01-02 format.
+func (t *Time) UnmarshalJSON(data []byte) error {
+	s := string(data)
+	if len(s) >= 2 && s[0] == '"' {
+		s = s[1 : len(s)-1]
+	}
+	d, err := time.Parse(TimeLayout, s)
+	if err != nil {
+		return err
+	}
+	*t = Time(d)
+	return nil
+}
+
+// String returns the date formatted as YYYY-MM-DD.
+func (t Time) String() string {
+	return time.Time(t).Format(TimeLayout)
+}
+
+// Time returns the underlying time.Time value.
+func (t Time) Time() time.Time {
+	return time.Time(t)
+}
diff --git a/model/criteria/json.go b/model/criteria/json.go
new file mode 100644
index 00000000..0e49e01b
--- /dev/null
+++ b/model/criteria/json.go
@@ -0,0 +1,341 @@
+package criteria
+
+import (
+	"encoding/json"
+	"fmt"
+	"strconv"
+	"time"
+
+	"github.com/Masterminds/squirrel"
+)
+
+// ---------------------------------------------------------------------------
+// JSON serialization
+// ---------------------------------------------------------------------------
+
+// MarshalJSON serializes Criteria to JSON, producing an object with "all" or
+// "any" fields for the expression (recursively), plus "sort", "order", "max"
+// and "offset" fields for pagination when set.
+func (c Criteria) MarshalJSON() ([]byte, error) {
+	out := make(map[string]interface{})
+	if c.Expression != nil {
+		expr, err := marshalExpression(c.Expression)
+		if err != nil {
+			return nil, err
+		}
+		for k, v := range expr {
+			out[k] = v
+		}
+	}
+	if c.Sort != "" {
+		out["sort"] = c.Sort
+	}
+	if c.Order != "" {
+		out["order"] = c.Order
+	}
+	if c.Max > 0 {
+		out["max"] = c.Max
+	}
+	if c.Offset > 0 {
+		out["offset"] = c.Offset
+	}
+	return json.Marshal(out)
+}
+
+// marshalExpression converts a Sqlizer into a map with a single "all", "any"
+// or operator key, preserving the nested structure.
+func marshalExpression(expr squirrel.Sqlizer) (map[string]interface{}, error) {
+	switch e := expr.(type) {
+	case All:
+		return marshalAll(e)
+	case Any:
+		return marshalAny(e)
+	case squirrel.And:
+		return marshalAll(All(e))
+	case squirrel.Or:
+		return marshalAny(Any(e))
+	case Is:
+		return map[string]interface{}{"is": map[string]interface{}{"field": e.Field, "value": e.Value}}, nil
+	case IsNot:
+		return map[string]interface{}{"isNot": map[string]interface{}{"field": e.Field, "value": e.Value}}, nil
+	case Gt:
+		return map[string]interface{}{"gt": map[string]interface{}{"field": e.Field, "value": e.Value}}, nil
+	case Lt:
+		return map[string]interface{}{"lt": map[string]interface{}{"field": e.Field, "value": e.Value}}, nil
+	case After:
+		return map[string]interface{}{"after": map[string]interface{}{"field": e.Field, "value": e.Value}}, nil
+	case Before:
+		return map[string]interface{}{"before": map[string]interface{}{"field": e.Field, "value": e.Value}}, nil
+	case Contains:
+		return map[string]interface{}{"contains": map[string]interface{}{"field": e.Field, "value": e.Value}}, nil
+	case NotContains:
+		return map[string]interface{}{"notContains": map[string]interface{}{"field": e.Field, "value": e.Value}}, nil
+	case StartsWith:
+		return map[string]interface{}{"startsWith": map[string]interface{}{"field": e.Field, "value": e.Value}}, nil
+	case EndsWith:
+		return map[string]interface{}{"endsWith": map[string]interface{}{"field": e.Field, "value": e.Value}}, nil
+	case InTheRange:
+		return map[string]interface{}{"inTheRange": map[string]interface{}{"field": e.Field, "min": e.Min, "max": e.Max}}, nil
+	case InTheLast:
+		return map[string]interface{}{"inTheLast": map[string]interface{}{"field": e.Field, "days": e.Days}}, nil
+	case NotInTheLast:
+		return map[string]interface{}{"notInTheLast": map[string]interface{}{"field": e.Field, "days": e.Days}}, nil
+	case squirrel.Eq:
+		return marshalEq("is", e)
+	case squirrel.NotEq:
+		return marshalEq("isNot", squirrel.Eq(e))
+	case squirrel.Gt:
+		return marshalEq("gt", squirrel.Eq(e))
+	case squirrel.Lt:
+		return marshalEq("lt", squirrel.Eq(e))
+	case squirrel.GtOrEq:
+		return marshalRange("inTheRange", squirrel.LtOrEq(e), e)
+	case squirrel.NotILike:
+		return marshalLike("notContains", squirrel.ILike(e))
+	case squirrel.ILike:
+		return marshalLike("contains", e)
+	default:
+		return nil, fmt.Errorf("unsupported criteria expression: %T", expr)
+	}
+}
+
+func marshalAll(a All) (map[string]interface{}, error) {
+	items := make([]interface{}, 0, len(a))
+	for _, sub := range a {
+		item, err := marshalExpression(sub)
+		if err != nil {
+			return nil, err
+		}
+		items = append(items, item)
+	}
+	return map[string]interface{}{"all": items}, nil
+}
+
+func marshalAny(a Any) (map[string]interface{}, error) {
+	items := make([]interface{}, 0, len(a))
+	for _, sub := range a {
+		item, err := marshalExpression(sub)
+		if err != nil {
+			return nil, err
+		}
+		items = append(items, item)
+	}
+	return map[string]interface{}{"any": items}, nil
+}
+
+func marshalEq(key string, e squirrel.Eq) (map[string]interface{}, error) {
+	for field, value := range e {
+		return map[string]interface{}{key: map[string]interface{}{"field": field, "value": value}}, nil
+	}
+	return nil, fmt.Errorf("empty expression for key %s", key)
+}
+
+func marshalRange(key string, lte squirrel.LtOrEq, gt squirrel.GtOrEq) (map[string]interface{}, error) {
+	field, min, ok := firstEntry(gt)
+	if !ok {
+		return nil, fmt.Errorf("empty range expression")
+	}
+	_, max, _ := firstEntry(lte)
+	return map[string]interface{}{key: map[string]interface{}{"field": field, "min": min, "max": max}}, nil
+}
+
+func marshalLike(key string, e squirrel.ILike) (map[string]interface{}, error) {
+	for field, pattern := range e {
+		p, ok := pattern.(string)
+		if !ok {
+			return nil, fmt.Errorf("invalid pattern for key %s: %v", key, pattern)
+		}
+		value := p
+		if len(value) >= 2 && value[0] == '%' && value[len(value)-1] == '%' {
+			value = value[1 : len(value)-1]
+		}
+		return map[string]interface{}{key: map[string]interface{}{"field": field, "value": value}}, nil
+	}
+	return nil, fmt.Errorf("empty expression for key %s", key)
+}
+
+func firstEntry(m map[string]interface{}) (string, interface{}, bool) {
+	for k, v := range m {
+		return k, v, true
+	}
+	return "", nil, false
+}
+
+// ---------------------------------------------------------------------------
+// JSON deserialization
+// ---------------------------------------------------------------------------
+
+// UnmarshalJSON deserializes Criteria from JSON, reconstructing the operators
+// from the keys "contains", "notContains", "is", "isNot", "startsWith",
+// "inTheRange", "all" and "any", preserving the nested All/Any hierarchy.
+func (c *Criteria) UnmarshalJSON(data []byte) error {
+	var raw map[string]json.RawMessage
+	if err := json.Unmarshal(data, &raw); err != nil {
+		return err
+	}
+
+	expr, err := unmarshalExpression(raw)
+	if err != nil {
+		return err
+	}
+	c.Expression = expr
+
+	if v, ok := raw["sort"]; ok {
+		if err := json.Unmarshal(v, &c.Sort); err != nil {
+			return err
+		}
+	}
+	if v, ok := raw["order"]; ok {
+		if err := json.Unmarshal(v, &c.Order); err != nil {
+			return err
+		}
+	}
+	if v, ok := raw["max"]; ok {
+		var max int
+		if err := json.Unmarshal(v, &max); err != nil {
+			return err
+		}
+		c.Max = max
+	}
+	if v, ok := raw["offset"]; ok {
+		var offset int
+		if err := json.Unmarshal(v, &offset); err != nil {
+			return err
+		}
+		c.Offset = offset
+	}
+	return nil
+}
+
+// unmarshalExpression reconstructs a Sqlizer from a raw JSON object, using the
+// operator keys to determine the type.
+func unmarshalExpression(raw map[string]json.RawMessage) (squirrel.Sqlizer, error) {
+	if allRaw, ok := raw["all"]; ok {
+		return unmarshalAll(allRaw)
+	}
+	if anyRaw, ok := raw["any"]; ok {
+		return unmarshalAny(anyRaw)
+	}
+	for key, rawValue := range raw {
+		switch key {
+		case "sort", "order", "max", "offset":
+			continue
+		default:
+			return unmarshalOperator(key, rawValue)
+		}
+	}
+	return nil, nil
+}
+
+func unmarshalAll(data json.RawMessage) (squirrel.Sqlizer, error) {
+	var items []map[string]json.RawMessage
+	if err := json.Unmarshal(data, &items); err != nil {
+		return nil, err
+	}
+	all := make(All, 0, len(items))
+	for _, item := range items {
+		expr, err := unmarshalExpression(item)
+		if err != nil {
+			return nil, err
+		}
+		all = append(all, expr)
+	}
+	return all, nil
+}
+
+func unmarshalAny(data json.RawMessage) (squirrel.Sqlizer, error) {
+	var items []map[string]json.RawMessage
+	if err := json.Unmarshal(data, &items); err != nil {
+		return nil, err
+	}
+	anyExpr := make(Any, 0, len(items))
+	for _, item := range items {
+		expr, err := unmarshalExpression(item)
+		if err != nil {
+			return nil, err
+		}
+		anyExpr = append(anyExpr, expr)
+	}
+	return anyExpr, nil
+}
+
+func unmarshalOperator(key string, rawValue json.RawMessage) (squirrel.Sqlizer, error) {
+	var op struct {
+		Field string      `json:"field"`
+		Value interface{} `json:"value"`
+		Min   interface{} `json:"min"`
+		Max   interface{} `json:"max"`
+		Days  interface{} `json:"days"`
+	}
+	if err := json.Unmarshal(rawValue, &op); err != nil {
+		return nil, fmt.Errorf("invalid operator value for key %s: %s", key, err)
+	}
+	switch key {
+	case "is":
+		return Is{Field: op.Field, Value: op.Value}, nil
+	case "isNot":
+		return IsNot{Field: op.Field, Value: op.Value}, nil
+	case "gt":
+		return Gt{Field: op.Field, Value: op.Value}, nil
+	case "lt":
+		return Lt{Field: op.Field, Value: op.Value}, nil
+	case "after":
+		return After{Field: op.Field, Value: parseTime(op.Value)}, nil
+	case "before":
+		return Before{Field: op.Field, Value: parseTime(op.Value)}, nil
+	case "contains":
+		return Contains{Field: op.Field, Value: toString(op.Value)}, nil
+	case "notContains":
+		return NotContains{Field: op.Field, Value: toString(op.Value)}, nil
+	case "startsWith":
+		return StartsWith{Field: op.Field, Value: toString(op.Value)}, nil
+	case "endsWith":
+		return EndsWith{Field: op.Field, Value: toString(op.Value)}, nil
+	case "inTheRange":
+		return InTheRange{Field: op.Field, Min: op.Min, Max: op.Max}, nil
+	case "inTheLast":
+		return InTheLast{Field: op.Field, Days: toInt(op.Days)}, nil
+	case "notInTheLast":
+		return NotInTheLast{Field: op.Field, Days: toInt(op.Days)}, nil
+	default:
+		return nil, fmt.Errorf("unknown operator: %s", key)
+	}
+}
+
+// parseTime converts a JSON value to Time, accepting either a "2006-01-02"
+// string or a numeric timestamp.
+func parseTime(v interface{}) Time {
+	switch t := v.(type) {
+	case string:
+		d, err := time.Parse(TimeLayout, t)
+		if err != nil {
+			return Time{}
+		}
+		return Time(d)
+	case float64:
+		return Time(time.Unix(int64(t), 0))
+	default:
+		return Time{}
+	}
+}
+
+func toString(v interface{}) string {
+	if v == nil {
+		return ""
+	}
+	return fmt.Sprintf("%v", v)
+}
+
+func toInt(v interface{}) int {
+	switch n := v.(type) {
+	case float64:
+		return int(n)
+	case int:
+		return n
+	case string:
+		i, _ := strconv.Atoi(n)
+		return i
+	default:
+		return 0
+	}
+}
diff --git a/model/criteria/operators.go b/model/criteria/operators.go
new file mode 100644
index 00000000..a8c5bdf4
--- /dev/null
+++ b/model/criteria/operators.go
@@ -0,0 +1,197 @@
+package criteria
+
+import (
+	"time"
+
+	"github.com/Masterminds/squirrel"
+)
+
+// ---------------------------------------------------------------------------
+// Logical operators
+// ---------------------------------------------------------------------------
+
+// All is a logical conjunction (AND) of criteria, based on squirrel.And.
+// It generates SQL with parentheses around the conjunction.
+type All squirrel.And
+
+// ToSql generates SQL with AND between the sub-criteria, wrapped in parentheses.
+func (a All) ToSql() (sql string, args []interface{}, err error) {
+	return squirrel.And(a).ToSql()
+}
+
+// Any is a logical disjunction (OR) of criteria, based on squirrel.Or.
+// It generates SQL with parentheses around the disjunction.
+type Any squirrel.Or
+
+// ToSql generates SQL with OR between the sub-criteria, wrapped in parentheses.
+func (a Any) ToSql() (sql string, args []interface{}, err error) {
+	return squirrel.Or(a).ToSql()
+}
+
+// ---------------------------------------------------------------------------
+// Comparison operators
+// ---------------------------------------------------------------------------
+
+// Is is the exact equality operator, based on squirrel.Eq.
+type Is struct {
+	Field string
+	Value interface{}
+}
+
+// ToSql generates equality SQL ("column = ?") using fieldMap for the field.
+func (i Is) ToSql() (sql string, args []interface{}, err error) {
+	return squirrel.Eq{GetColumn(i.Field): i.Value}.ToSql()
+}
+
+// IsNot is the exact inequality operator, based on squirrel.NotEq.
+type IsNot struct {
+	Field string
+	Value interface{}
+}
+
+// ToSql generates inequality SQL ("column <> ?") using fieldMap for the field.
+func (i IsNot) ToSql() (sql string, args []interface{}, err error) {
+	return squirrel.NotEq{GetColumn(i.Field): i.Value}.ToSql()
+}
+
+// Gt is the greater than operator, based on squirrel.Gt.
+type Gt struct {
+	Field string
+	Value interface{}
+}
+
+// ToSql generates greater than SQL ("column > ?") using fieldMap for the field.
+func (g Gt) ToSql() (sql string, args []interface{}, err error) {
+	return squirrel.Gt{GetColumn(g.Field): g.Value}.ToSql()
+}
+
+// Lt is the less than operator, based on squirrel.Lt.
+type Lt struct {
+	Field string
+	Value interface{}
+}
+
+// ToSql generates less than SQL ("column < ?") using fieldMap for the field.
+func (l Lt) ToSql() (sql string, args []interface{}, err error) {
+	return squirrel.Lt{GetColumn(l.Field): l.Value}.ToSql()
+}
+
+// After is the date "is after" operator, based on squirrel.Gt.
+type After struct {
+	Field string
+	Value Time
+}
+
+// ToSql generates greater than SQL ("column > ?") for dates using fieldMap.
+func (a After) ToSql() (sql string, args []interface{}, err error) {
+	return squirrel.Gt{GetColumn(a.Field): a.Value.Time()}.ToSql()
+}
+
+// Before is the date "is before" operator, based on squirrel.Lt.
+type Before struct {
+	Field string
+	Value Time
+}
+
+// ToSql generates less than SQL ("column < ?") for dates using fieldMap.
+func (b Before) ToSql() (sql string, args []interface{}, err error) {
+	return squirrel.Lt{GetColumn(b.Field): b.Value.Time()}.ToSql()
+}
+
+// ---------------------------------------------------------------------------
+// Text operators
+// ---------------------------------------------------------------------------
+
+// Contains is the text search operator, matching values that contain the
+// given string (case insensitive). It uses the "%value%" pattern with ILIKE.
+type Contains struct {
+	Field string
+	Value string
+}
+
+// ToSql generates ILIKE SQL with the "%value%" pattern using fieldMap.
+func (c Contains) ToSql() (sql string, args []interface{}, err error) {
+	return squirrel.ILike{GetColumn(c.Field): "%" + c.Value + "%"}.ToSql()
+}
+
+// NotContains is the text exclusion operator, matching values that do NOT
+// contain the given string. It uses the "%value%" pattern with NOT ILIKE.
+type NotContains struct {
+	Field string
+	Value string
+}
+
+// ToSql generates NOT ILIKE SQL with the "%value%" pattern using fieldMap.
+func (c NotContains) ToSql() (sql string, args []interface{}, err error) {
+	return squirrel.NotILike{GetColumn(c.Field): "%" + c.Value + "%"}.ToSql()
+}
+
+// StartsWith is the prefix search operator, matching values that start with
+// the given string. It uses the "value%" pattern with ILIKE.
+type StartsWith struct {
+	Field string
+	Value string
+}
+
+// ToSql generates ILIKE SQL with the "value%" pattern using fieldMap.
+func (s StartsWith) ToSql() (sql string, args []interface{}, err error) {
+	return squirrel.ILike{GetColumn(s.Field): s.Value + "%"}.ToSql()
+}
+
+// EndsWith is the suffix search operator, matching values that end with the
+// given string. It uses the "%value" pattern with ILIKE.
+type EndsWith struct {
+	Field string
+	Value string
+}
+
+// ToSql generates ILIKE SQL with the "%value" pattern using fieldMap.
+func (e EndsWith) ToSql() (sql string, args []interface{}, err error) {
+	return squirrel.ILike{GetColumn(e.Field): "%" + e.Value}.ToSql()
+}
+
+// ---------------------------------------------------------------------------
+// Range operators
+// ---------------------------------------------------------------------------
+
+// InTheRange is the range operator, matching values between Min and Max
+// (inclusive). It uses squirrel.GtOrEq and squirrel.LtOrEq.
+type InTheRange struct {
+	Field string
+	Min   interface{}
+	Max   interface{}
+}
+
+// ToSql generates SQL with >= and <= conditions using fieldMap for the field.
+func (r InTheRange) ToSql() (sql string, args []interface{}, err error) {
+	return squirrel.And{
+		squirrel.GtOrEq{GetColumn(r.Field): r.Min},
+		squirrel.LtOrEq{GetColumn(r.Field): r.Max},
+	}.ToSql()
+}
+
+// InTheLast is the "in the last N days" operator for dates.
+type InTheLast struct {
+	Field string
+	Days  int
+}
+
+// ToSql generates "column > now - N days" using fieldMap for the field.
+func (l InTheLast) ToSql() (sql string, args []interface{}, err error) {
+	return squirrel.Gt{GetColumn(l.Field): time.Now().Add(time.Duration(-24*l.Days) * time.Hour)}.ToSql()
+}
+
+// NotInTheLast is the "NOT in the last N days" operator for dates. It matches
+// dates older than N days, or null dates (never played).
+type NotInTheLast struct {
+	Field string
+	Days  int
+}
+
+// ToSql generates "(column < now - N days OR column IS NULL)" using fieldMap.
+func (l NotInTheLast) ToSql() (sql string, args []interface{}, err error) {
+	return squirrel.Or{
+		squirrel.Lt{GetColumn(l.Field): time.Now().Add(time.Duration(-24*l.Days) * time.Hour)},
+		squirrel.Eq{GetColumn(l.Field): nil},
+	}.ToSql()
+}

