+}
+
+var backupCmd = &cobra.Command{
+	Use:   "backup",
+	Short: "Backup and restore the Navidrome database",
+	Long:  "Backup, prune and restore the Navidrome database",
+}
+
+var backupCreateCmd = &cobra.Command{
+	Use:   "create",
+	Short: "Create a manual database backup",
+	Long:  "Create a backup of the Navidrome database. This ignores the configured retention count.",
+	Run: func(cmd *cobra.Command, args []string) {
+		runBackupCreate()
+	},
+}
+
+var backupPruneCmd = &cobra.Command{
+	Use:   "prune",
+	Short: "Delete old backups, keeping only the most recent backup.count files",
+	Long: `Delete old backup files, keeping only the most recent backup.count files.
+If backup.count is 0, all backups are eligible for deletion and this command
+asks for confirmation unless --force is provided.`,
+	Run: func(cmd *cobra.Command, args []string) {
+		runBackupPrune()
+	},
+}
+
+var backupRestoreCmd = &cobra.Command{
+	Use:   "restore",
+	Short: "Restore the database from a backup file",
+	Long:  "Restore the Navidrome database from the backup file given by --backup-file.",
+	Run: func(cmd *cobra.Command, args []string) {
