diff --git a/db/backup.go b/db/backup.go
new file mode 100644
index 00000000..7a25592a
--- /dev/null
+++ b/db/backup.go
@@ -0,0 +1,270 @@
+package db
+
+import (
+	"context"
+	"database/sql"
+	"fmt"
+	"io"
+	"os"
+	"path/filepath"
+	"runtime"
+	"sort"
+	"strings"
+	"time"
+
+	"github.com/mattn/go-sqlite3"
+	"github.com/navidrome/navidrome/conf"
+	"github.com/navidrome/navidrome/log"
+)
+
+const (
+	backupFilePrefix = "navidrome_backup_"
+	backupFileSuffix = ".db"
+	backupTimeFormat = "20060102_150405"
+)
+
+// Backup creates an online backup of the current (live) database using
+// SQLite's online backup API, and saves it to the configured backup path
+// (conf.Server.Backup.Path). It returns the path of the created backup file.
+func (d *db) Backup(ctx context.Context) (string, error) {
+	path := conf.Server.Backup.Path
+	if path == "" {
+		return "", fmt.Errorf("backup.path is not configured")
+	}
+	if err := os.MkdirAll(path, os.ModePerm); err != nil {
+		return "", fmt.Errorf("creating backup directory: %w", err)
+	}
+
+	dest := filepath.Join(path, fmt.Sprintf("%s%s%s", backupFilePrefix, time.Now().Format(backupTimeFormat), backupFileSuffix))
+	if err := d.backupTo(dest); err != nil {
+		// Clean up the partial backup file on failure
+		_ = os.Remove(dest)
+		return "", err
+	}
+
+	log.Info(ctx, "Backup created", "file", dest)
+	return dest, nil
+}
+
+// backupTo performs an online backup of the live database to the file at dest
+// using the mattn/go-sqlite3 driver's online backup API. It obtains the raw
+// *sqlite3.SQLiteConn handles of both the live write connection and a new
+// connection to the destination file, and copies the whole database in one
+// step. Because it uses the online backup API, it is safe to run while the
+// server is handling requests.
+func (d *db) backupTo(dest string) error {
+	// Acquire a dedicated write connection from the pool.
+	srcConn, err := d.writeDB.Conn(context.Background())
+	if err != nil {
+		return fmt.Errorf("acquiring write connection: %w", err)
+	}
+	defer srcConn.Close()
+
+	var srcSQLite *sqlite3.SQLiteConn
+	if err := srcConn.Raw(func(driverConn any) error {
+		sc, ok := driverConn.(*sqlite3.SQLiteConn)
+		if !ok {
+			return fmt.Errorf("unexpected source connection type %T", driverConn)
+		}
+		srcSQLite = sc
+		return nil
+	}); err != nil {
+		return fmt.Errorf("getting source SQLite conn: %w", err)
+	}
+
+	// Open a brand new connection to the destination (new) file.
+	destPool, err := sql.Open(Driver, dest)
+	if err != nil {
+		return fmt.Errorf("opening backup file: %w", err)
+	}
+	defer destPool.Close()
+
+	destConn, err := destPool.Conn(context.Background())
+	if err != nil {
+		return fmt.Errorf("acquiring backup file connection: %w", err)
+	}
+	defer destConn.Close()
+
+	var destSQLite *sqlite3.SQLiteConn
+	if err := destConn.Raw(func(driverConn any) error {
+		dc, ok := driverConn.(*sqlite3.SQLiteConn)
+		if !ok {
+			return fmt.Errorf("unexpected destination connection type %T", driverConn)
+		}
+		destSQLite = dc
+		return nil
+	}); err != nil {
+		return fmt.Errorf("getting destination SQLite conn: %w", err)
+	}
+
+	b, err := destSQLite.Backup("main", srcSQLite, "main")
+	if err != nil {
+		return fmt.Errorf("initializing online backup: %w", err)
+	}
+	defer func() { _ = b.Close() }()
+
+	// Copy the whole database in one step.
+	done, err := b.Step(-1)
+	if err != nil {
+		return fmt.Errorf("stepping online backup: %w", err)
+	}
+	if !done {
+		return fmt.Errorf("online backup did not complete")
+	}
+	return nil
+}
+
+// Restore restores the database from the backup file located at path. It first
+// closes the current read/write connections, replaces the live database file
+// with the contents of the backup, and reopens the connections.
+func (d *db) Restore(ctx context.Context, path string) error {
+	fi, err := os.Stat(path)
+	if err != nil {
+		return fmt.Errorf("cannot access backup file: %w", err)
+	}
+	if fi.IsDir() {
+		return fmt.Errorf("backup path is a directory, expected a file: %s", path)
+	}
+	if !isSQLiteFile(path) {
+		return fmt.Errorf("file is not a valid SQLite database: %s", path)
+	}
+
+	// Close the current connections so the database file can be replaced.
+	d.Close()
+
+	srcPath := conf.Server.DbPath
+	if idx := strings.Index(srcPath, "?"); idx >= 0 {
+		srcPath = srcPath[:idx]
+	}
+	if srcPath == "" || srcPath == ":memory:" {
+		return fmt.Errorf("cannot restore into an in-memory database")
+	}
+
+	if err := copyFile(path, srcPath); err != nil {
+		return fmt.Errorf("copying backup over live database: %w", err)
+	}
+	// Remove WAL/SHM sidecar files so the restored DB is clean.
+	for _, suffix := range []string{"-wal", "-shm"} {
+		_ = os.Remove(srcPath + suffix)
+	}
+
+	rdb, wdb, err := openDBConnections()
+	if err != nil {
+		return fmt.Errorf("reopening database after restore: %w", err)
+	}
+	d.readDB = rdb
+	d.writeDB = wdb
+
+	log.Info(ctx, "Database restored", "file", path)
+	return nil
+}
+
+// Prune removes old backup files from the configured backup path, keeping only
+// the most recent conf.Server.Backup.Count files. It returns the number of
+// files that were removed.
+func (d *db) Prune(ctx context.Context) (int, error) {
+	return prune(ctx)
+}
+
+// prune lists the backup files in the configured backup path, sorted by
+// descending timestamp, and deletes everything beyond the most recent
+// conf.Server.Backup.Count files. When the count is 0, all backups are
+// eligible for deletion. It returns the number of files removed.
+func prune(ctx context.Context) (int, error) {
+	path := conf.Server.Backup.Path
+	if path == "" {
+		return 0, fmt.Errorf("backup.path is not configured")
+	}
+	dirEntries, err := os.ReadDir(path)
+	if err != nil {
+		if os.IsNotExist(err) {
+			return 0, nil
+		}
+		return 0, fmt.Errorf("reading backup directory: %w", err)
+	}
+
+	var backups []string
+	for _, entry := range dirEntries {
+		name := entry.Name()
+		if entry.IsDir() {
+			continue
+		}
+		if !strings.HasPrefix(name, backupFilePrefix) || !strings.HasSuffix(name, backupFileSuffix) {
+			continue
+		}
+		// The name embeds the timestamp, so a lexicographic sort is the same
+		// as a chronological sort.
+		backups = append(backups, name)
+	}
+	// Newest first.
+	sort.Sort(sort.Reverse(sort.StringSlice(backups)))
+
+	keep := conf.Server.Backup.Count
+	var pruned int
+	for i, name := range backups {
+		if i < keep {
+			continue
+		}
+		full := filepath.Join(path, name)
+		log.Info(ctx, "Pruning backup", "file", full)
+		if err := os.Remove(full); err != nil {
+			return pruned, fmt.Errorf("removing backup %s: %w", full, err)
+		}
+		pruned++
+	}
+	return pruned, nil
+}
+
+// openDBConnections opens the read and write database connections for the
+// configured database path. It is used by both the singleton constructor and by
+// Restore after replacing the database file.
+func openDBConnections() (*sql.DB, *sql.DB, error) {
+	log.Debug("Opening DataBase", "dbPath", conf.Server.DbPath, "driver", Driver)
+
+	rdb, err := sql.Open(Driver, conf.Server.DbPath)
+	if err != nil {
+		return nil, nil, fmt.Errorf("opening read database: %w", err)
+	}
+	rdb.SetMaxOpenConns(max(4, runtime.NumCPU()))
+
+	wdb, err := sql.Open(Driver, conf.Server.DbPath)
+	if err != nil {
+		_ = rdb.Close()
+		return nil, nil, fmt.Errorf("opening write database: %w", err)
+	}
+	wdb.SetMaxOpenConns(1)
+	return rdb, wdb, nil
+}
+
+// isSQLiteFile checks that the file at path starts with the SQLite header
+// "SQLite format 3\x00" (16 bytes).
+func isSQLiteFile(path string) bool {
+	f, err := os.Open(path)
+	if err != nil {
+		return false
+	}
+	defer f.Close()
+	header := make([]byte, 16)
+	if _, err := io.ReadFull(f, header); err != nil {
+		return false
+	}
+	return string(header) == "SQLite format 3\x00"
+}
+
+// copyFile copies the file at src to dst, truncating dst first.
+func copyFile(src, dst string) error {
+	in, err := os.Open(src)
+	if err != nil {
+		return err
+	}
+	defer in.Close()
+	out, err := os.Create(dst)
+	if err != nil {
+		return err
+	}
+	defer out.Close()
+	if _, err := io.Copy(out, in); err != nil {
+		return err
+	}
+	return out.Sync()
+}
