+package db
+
+import (
+	"context"
+	"database/sql"
+	"os"
+	"path/filepath"
+	"sync"
+	"testing"
+
+	"github.com/mattn/go-sqlite3"
+	"github.com/navidrome/navidrome/conf"
+)
+
+var registerOnce sync.Once
+
+// setupTestDB creates a *db instance backed by a real file-based SQLite
+// database, registers the custom driver (once), and seeds a table with 3 rows.
+// It returns the db instance and a cleanup function.
+func setupTestDB(t *testing.T) (*db, func()) {
+	t.Helper()
+	registerOnce.Do(func() {
+		sql.Register(Driver+"_custom", &sqlite3.SQLiteDriver{})
+	})
+
+	dir := t.TempDir()
+	dbPath := filepath.Join(dir, "test.db")
+	conf.Server.DbPath = dbPath + "?cache=shared&_foreign_keys=on&_journal_mode=WAL&_synchronous=NORMAL"
+
+	rdb, err := sql.Open(Driver+"_custom", conf.Server.DbPath)
+	if err != nil {
+		t.Fatalf("open read: %v", err)
+	}
+	wdb, err := sql.Open(Driver+"_custom", conf.Server.DbPath)
+	if err != nil {
+		t.Fatalf("open write: %v", err)
+	}
+	wdb.SetMaxOpenConns(1)
+	d := &db{readDB: rdb, writeDB: wdb}
+
+	if _, err := wdb.Exec("CREATE TABLE t (id INTEGER PRIMARY KEY, name TEXT)"); err != nil {
+		t.Fatalf("create table: %v", err)
+	}
+	if _, err := wdb.Exec("INSERT INTO t (name) VALUES ('alice'), ('bob'), ('carol')"); err != nil {
+		t.Fatalf("insert: %v", err)
+	}
+
+	cleanup := func() { d.Close() }
+	return d, cleanup
+}
+
+func countRows(t *testing.T, d *db) int {
+	t.Helper()
+	var n int
+	if err := d.readDB.QueryRow("SELECT COUNT(*) FROM t").Scan(&n); err != nil {
+		t.Fatalf("count: %v", err)
+	}
+	return n
+}
+
+func TestBackupCreatesFile(t *testing.T) {
+	d, cleanup := setupTestDB(t)
+	defer cleanup()
+
+	backupDir := t.TempDir()
+	conf.Server.Backup.Path = backupDir
+
+	file, err := d.Backup(context.Background())
+	if err != nil {
+		t.Fatalf("Backup() error: %v", err)
+	}
+	if filepath.Dir(file) != backupDir {
+		t.Fatalf("backup not in backup dir: %s", file)
+	}
+	if _, err := os.Stat(file); err != nil {
+		t.Fatalf("backup file does not exist: %v", err)
+	}
+	if !isSQLiteFile(file) {
+		t.Fatalf("backup file is not a valid SQLite database")
+	}
+
+	bdb, err := sql.Open(Driver, file)
+	if err != nil {
+		t.Fatalf("open backup: %v", err)
+	}
+	defer bdb.Close()
+	var n int
+	if err := bdb.QueryRow("SELECT COUNT(*) FROM t").Scan(&n); err != nil {
+		t.Fatalf("count in backup: %v", err)
+	}
+	if n != 3 {
+		t.Fatalf("expected 3 rows in backup, got %d", n)
+	}
+}
+
+func TestBackupFailsWithoutPath(t *testing.T) {
+	d, cleanup := setupTestDB(t)
+	defer cleanup()
+
+	conf.Server.Backup.Path = ""
+	if _, err := d.Backup(context.Background()); err == nil {
+		t.Fatalf("expected error when backup.path is empty")
+	}
+}
+
+func TestRestoreRoundTrip(t *testing.T) {
+	d, cleanup := setupTestDB(t)
+	defer cleanup()
+
+	backupDir := t.TempDir()
+	conf.Server.Backup.Path = backupDir
+	ctx := context.Background()
+
+	backupFile, err := d.Backup(ctx)
+	if err != nil {
+		t.Fatalf("Backup() error: %v", err)
+	}
+
+	// Simulate data loss so the live DB differs from the backup.
+	if _, err := d.writeDB.Exec("DELETE FROM t WHERE name='alice'"); err != nil {
+		t.Fatalf("delete: %v", err)
+	}
+	if n := countRows(t, d); n != 2 {
+		t.Fatalf("expected 2 rows after mutation, got %d", n)
+	}
+
+	if err := d.Restore(ctx, backupFile); err != nil {
+		t.Fatalf("Restore() error: %v", err)
+	}
+
+	if n := countRows(t, d); n != 3 {
+		t.Fatalf("expected 3 rows after restore, got %d", n)
+	}
+	var alice int
+	if err := d.readDB.QueryRow("SELECT COUNT(*) FROM t WHERE name='alice'").Scan(&alice); err != nil {
+		t.Fatalf("query alice: %v", err)
+	}
+	if alice != 1 {
+		t.Fatalf("expected alice to be present after restore, got %d", alice)
+	}
+}
+
+func TestRestoreRejectsInvalidFile(t *testing.T) {
+	d, cleanup := setupTestDB(t)
+	defer cleanup()
+
+	badFile := filepath.Join(t.TempDir(), "not-sqlite.txt")
+	if err := os.WriteFile(badFile, []byte("this is not sqlite"), 0o600); err != nil {
+		t.Fatalf("write: %v", err)
+	}
+	if err := d.Restore(context.Background(), badFile); err == nil {
+		t.Fatalf("expected error restoring from invalid file")
+	}
+}
+
+func TestPruneKeepsCount(t *testing.T) {
+	backupDir := t.TempDir()
+	conf.Server.Backup.Path = backupDir
+
+	for _, ts := range []string{"20240101_000001", "20240101_000002", "20240101_000003", "20240101_000004", "20240101_000005"} {
+		name := filepath.Join(backupDir, "navidrome_backup_"+ts+".db")
+		if err := os.WriteFile(name, []byte("x"), 0o600); err != nil {
+			t.Fatalf("write: %v", err)
+		}
+	}
+	// A non-backup file that must be ignored.
+	if err := os.WriteFile(filepath.Join(backupDir, "other.txt"), []byte("x"), 0o600); err != nil {
+		t.Fatalf("write: %v", err)
+	}
+
+	conf.Server.Backup.Count = 2
+	n, err := prune(context.Background())
+	if err != nil {
+		t.Fatalf("prune() error: %v", err)
+	}
+	if n != 3 {
+		t.Fatalf("expected 3 pruned, got %d", n)
+	}
+
+	remaining, _ := os.ReadDir(backupDir)
+	if len(remaining) != 3 { // 2 backups + other.txt
+		t.Fatalf("expected 3 files remaining, got %d", len(remaining))
+	}
+	for _, e := range remaining {
+		name := e.Name()
+		if name == "navidrome_backup_20240101_000005.db" || name == "navidrome_backup_20240101_000004.db" || name == "other.txt" {
+			continue
+		}
+		t.Fatalf("unexpected file remaining: %s", name)
+	}
+}
+
+func TestPruneZeroDeletesAll(t *testing.T) {
+	backupDir := t.TempDir()
+	conf.Server.Backup.Path = backupDir
+	for _, ts := range []string{"20240101_000001", "20240101_000002"} {
+		name := filepath.Join(backupDir, "navidrome_backup_"+ts+".db")
+		if err := os.WriteFile(name, []byte("x"), 0o600); err != nil {
+			t.Fatalf("write: %v", err)
+		}
+	}
+	conf.Server.Backup.Count = 0
+	n, err := prune(context.Background())
+	if err != nil {
+		t.Fatalf("prune() error: %v", err)
+	}
+	if n != 2 {
+		t.Fatalf("expected 2 pruned, got %d", n)
+	}
+}
