+func (r *albumRepository) loadAlbumGenres(albums *model.Albums) error {
+	ids := make([]string, 0, len(*albums))
+	m := map[string]*model.Album{}
+	for i := range *albums {
+		a := &(*albums)[i]
+		ids = append(ids, a.ID)
+		m[a.ID] = a
+	}
+	if len(ids) == 0 {
+		return nil
+	}
+	sql := Select("g.*", "ag.album_id").From("genre g").Join("album_genres ag on ag.genre_id = g.id").
+		Where(Eq{"ag.album_id": ids}).OrderBy("ag.album_id", "g.name")
+	var ags []struct {
+		model.Genre
+		AlbumID string `orm:"column(album_id)"`
+	}
+	if err := r.queryAll(sql, &ags); err != nil {
+		return err
+	}
+	for _, ag := range ags {
+		a := m[ag.AlbumID]
+		if a != nil {
+			a.Genres = append(a.Genres, ag.Genre)
+		}
+	}
+	return nil
