+// redactValue redacts a single log field value. It handles map-type fields
+// (including nested maps) and other types after stringifying them with the
+// default Go format. The original keys of a map are preserved, and only the
+// values are replaced.
+func redactValue(v interface{}, redactionKeys []*regexp.Regexp) interface{} {
+	switch val := v.(type) {
+	case map[string]interface{}:
+		return redactMap(val, redactionKeys)
+	case map[string]string:
+		m := make(map[string]interface{}, len(val))
+		for k, v := range val {
+			m[k] = v
+		}
+		return redactMap(m, redactionKeys)
+	default:
+		return redactString(fmt.Sprint(v), redactionKeys)
+	}
+}
+
+func redactMap(m map[string]interface{}, redactionKeys []*regexp.Regexp) map[string]interface{} {
+	for k, v := range m {
+		switch val := v.(type) {
+		case string:
+			m[k] = redactString(val, redactionKeys)
+		default:
+			m[k] = redactValue(val, redactionKeys)
+		}
+	}
+	return m
+}
+
+func redactString(s string, redactionKeys []*regexp.Regexp) string {
+	for _, re := range redactionKeys {
+		s = re.ReplaceAllString(s, "$1[REDACTED]$2")
+	}
+	return s
+}
