 }
+
+type EntryDataMapTest struct {
+	name          string
+	redactionList []string
+	logFields     logrus.Fields
+	expected      logrus.Fields
+	description   string
+}
+
+// Test that sensitive values inside map-type fields (including nested maps)
+// are redacted, preserving the original keys.
+func TestEntryDataMaps(t *testing.T) {
+	tests := []EntryDataMapTest{
+		{
+			name:          "string value inside map",
+			redactionList: []string{"(password=)\\w+"},
+			logFields:     logrus.Fields{"request": map[string]interface{}{"body": "password=supersecret"}},
+			expected:      logrus.Fields{"request": map[string]interface{}{"body": "password=[REDACTED]"}},
+			description:   "Secret inside a map should be redacted, but was not.",
+		},
+		{
+			name:          "nested map",
+			redactionList: []string{"(password=)\\w+"},
+			logFields:     logrus.Fields{"config": map[string]interface{}{"nested": map[string]interface{}{"body": "password=abc123"}}},
+			expected:      logrus.Fields{"config": map[string]interface{}{"nested": map[string]interface{}{"body": "password=[REDACTED]"}}},
+			description:   "Secret inside a nested map should be redacted, but was not.",
+		},
+		{
+			name:          "stringified non-string value",
+			redactionList: []string{"(password=)\\w+"},
+			logFields:     logrus.Fields{"query": []string{"password=secret123"}},
+			expected:      logrus.Fields{"query": "[password=[REDACTED]]"},
+			description:   "Non-string value should be redacted after stringification,",
+		},
+		{
+			name:          "keys are preserved",
+			redactionList: []string{"\\d+"},
+			logFields:     logrus.Fields{"m": map[string]interface{}{"count": "42"}},
+			expected:      logrus.Fields{"m": map[string]interface{}{"count": "[REDACTED]"}},
+			description:   "Map keys must be preserved, only values replaced.",
+		},
+	}
+
+	for _, test := range tests {
+		fn := func(t *testing.T) {
+			logEntry := &logrus.Entry{
+				Data: test.logFields,
+			}
+			h := &Hook{RedactionList: test.redactionList}
+			err := h.Fire(logEntry)
+
+			assert.Nil(t, err)
+			assert.Equal(t, test.expected, logEntry.Data, test.description)
+		}
+		t.Run(test.name, fn)
+	}
+}
