+		return contains(list, "@")
+	}
+	netIP := net.ParseIP(ip)
+	if netIP == nil {
+		return false
+	}
+	for _, entry := range list {
+		entry = strings.TrimSpace(entry)
+		if entry == "" {
+			continue
+		}
+		// Support bare IPs and "IP:port" formats by treating them as a /32 (or /128) network
+		if !strings.Contains(entry, "/") {
+			if strings.Contains(entry, ":") && !strings.Contains(ipOnly(entry), ":") {
+				entry = ipOnly(entry)
+				if entry == "" {
+					continue
+				}
+			}
+			if net.ParseIP(entry) == nil {
+				continue // ignore invalid entries
+			}
+			if strings.Contains(entry, ".") {
+				entry += "/32"
+			} else {
+				entry += "/128"
+			}
+		}
+		_, network, err := net.ParseCIDR(entry)
+		if err != nil {
+			continue // ignore invalid entries
+		}
+		if network.Contains(netIP) {
+			return true
+		}
+	}
+	return false
+}
+
+// ipOnly returns the IP part of an "IP:port" format
+func ipOnly(ipWithPort string) string {
+	host, _, err := net.SplitHostPort(ipWithPort)
+	if err != nil {
+		return ""
+	}
+	return host
+}
+
+func contains(list []string, v string) bool {
+	for _, item := range list {
+		if strings.TrimSpace(item) == v {
+			return true
+		}
+	}
+	return false
+}
+
+// authFromRequest returns the authentication payload if the request comes from a
+// whitelisted reverse proxy that provides a valid user in the configured header.
+// It returns nil if the IP is not whitelisted, or the header is empty, or the
+// user does not exist and cannot be created.
+func authFromRequest(ds model.DataStore, r *http.Request) *map[string]interface{} {
+	whitelist := conf.Server.ReverseProxyWhitelist
+	if strings.TrimSpace(whitelist) == "" {
+		return nil
+	}
+	whitelisted := validateIPAgainstList(utils.RemoteIP(r), strings.Split(whitelist, ","))
+	if !whitelisted {
+		return nil
+	}
+	username := r.Header.Get(conf.Server.ReverseProxyUserHeader)
+	if username == "" {
+		return nil
+	}
+	return handleLoginFromHeaders(ds, r, username)
+}
+
+// handleLoginFromHeaders authenticates a user provided by a reverse proxy in the
+// configured header. If the user does not exist, it is created on first login;
+// the first created user is set as admin.
+func handleLoginFromHeaders(ds model.DataStore, r *http.Request, username string) *map[string]interface{} {
+	ctx := r.Context()
+	userRepo := ds.User(ctx)
+	user, err := userRepo.FindByUsername(username)
+	if err == model.ErrNotFound {
+		user = createReverseProxyUser(ctx, userRepo, username)
+		if user == nil {
+			return nil
+		}
+	} else if err != nil {
+		log.Error(r, "Error getting user", "username", username, err)
+		return nil
+	}
+
+	if err := userRepo.UpdateLastLoginAt(user.ID); err != nil {
+		log.Error(r, "Could not update LastLoginAt", "user", username)
+	}
+
+	tokenString, err := auth.CreateToken(user)
+	if err != nil {
+		log.Error(r, "Error creating token", "user", username, err)
+		return nil
+	}
+
+	// Reverse proxy auth has no password, so we cannot compute a valid subsonic
+	// token; we leave them empty (the UI will not use them).
+	salt := ""
+	token := ""
+	payload := map[string]interface{}{
+		"id":            user.ID,
+		"username":      user.UserName,
+		"name":          user.Name,
+		"token":         tokenString,
+		"isAdmin":       user.IsAdmin,
+		"subsonicSalt":  salt,
+		"subsonicToken": token,
+	}
+	if conf.Server.EnableGravatar && user.Email != "" {
+		payload["avatar"] = gravatar.Url(user.Email, 50)
+	}
+	return &payload
+}
+
+func createReverseProxyUser(ctx context.Context, userRepo model.UserRepository, username string) *model.User {
+	log.Warn("Creating user from reverse proxy", "user", username)
+	c, err := userRepo.CountAll()
+	if err != nil {
+		log.Error("Error counting users", err)
+		return nil
+	}
+	isAdmin := c == 0
+	newUser := model.User{
+		ID:          uuid.NewString(),
+		UserName:    username,
+		Name:        strings.Title(username),
+		IsAdmin:     isAdmin,
+		LastLoginAt: timePtr(),
+	}
+	if err := userRepo.Put(&newUser); err != nil {
+		log.Error("Could not create user", "user", username, err)
+		return nil
+	}
+	return &newUser
+}
+
+func timePtr() *time.Time {
+	now := time.Now()
+	return &now
+}
