+// RemoteIP returns the IP address of the remote client, without the port.
+// For requests received on a Unix socket it returns the special value "@".
+func RemoteIP(r *http.Request) string {
+	if r.RemoteAddr == "@" || r.RemoteAddr == "[::1]" || r.RemoteAddr == "[::1]:0" {
+		return "@"
+	}
+	ip, _, err := net.SplitHostPort(r.RemoteAddr)
+	if err != nil {
+		return r.RemoteAddr
+	}
+	return ip
+}

