new file mode 100644
index 00000000..cea7bc09
--- /dev/null
+++ b/log/e2e_check_test.go
@@ -0,0 +1,40 @@
+package log_test
+
+import (
+	"bytes"
+	"strings"
+	"testing"
+
+	"github.com/navidrome/navidrome/log"
+	"github.com/sirupsen/logrus"
+)
+
+// TestE2E verifies per-component log levels override the global level.
+func TestE2E(t *testing.T) {
+	check := func(name, want string, setup func()) {
+		var buf bytes.Buffer
+		l := logrus.New()
+		l.SetOutput(&buf)
+		l.SetLevel(logrus.TraceLevel)
+		log.SetDefaultLogger(l)
+		setup()
+		log.SetLevel(log.LevelInfo) // global = info
+		log.SetDefaultLogger(l)
+		l.SetLevel(logrus.TraceLevel)
+		log.StableComponent()
+		got := buf.String()
+		emitted := strings.Contains(got, "stable debug message")
+		if want == "emitted" && !emitted {
+			t.Fatalf("%s: expected emission, buf=%q", name, got)
+		}
+		if want == "silent" && emitted {
+			t.Fatalf("%s: expected silence, buf=%q", name, got)
+		}
+		t.Logf("%s: %s OK", name, want)
+	}
+
+	check("global=info only", "silent", func() { log.SetLogLevels(nil) })
+	check("global=info + /app/log=debug", "emitted", func() { log.SetLogLevels(map[string]string{"/app/log": "debug"}) })
+	check("global=info + nothere=debug", "silent", func() { log.SetLogLevels(map[string]string{"nothere": "debug"}) })
+	log.SetLogLevels(nil)
+}
