+export const getMinExpirationTime = (date: Date): Date | undefined => {
+    // If the date is not today, all times are selectable, so there is no minimum time constraint
+    if (!isToday(date)) {
+        return undefined;
+    }
+
+    const now = new Date();
+
+    // The minimum expiration time must be at least 30 minutes in the future
+    const minTime = addMinutes(now, 30);
+
+    // The expiration time must be on a 30-minute interval (XX:00 or XX:30).
+    // Round `now + 30 minutes` up to the next valid interval (keeping the date intact
+    // even across midnight by carrying the extra hour).
+    const step = Math.ceil(minTime.getMinutes() / 30);
+    return addMinutes(minTime, 30 * step - minTime.getMinutes());
+};

