@@ -0,0 +1,69 @@
+import { useMemo } from 'react';
+
+import { c } from 'ttag';
+
+import { useEncryptedSearchContext } from '../../containers/EncryptedSearchProvider';
+import { getElementSenders, isProtonSender } from '../../helpers/elements';
+import { useRecipientLabel } from '../../hooks/contact/useRecipientLabel';
+import { Element } from '../../models/element';
+import { RecipientOrGroup } from '../../models/address';
+import ItemAction from './ItemAction';
+import ItemUnread from './ItemUnread';
+import ProtonBadgeType, { PROTON_BADGE_TYPE } from './ProtonBadgeType';
+
+interface Props {
+    element: Element;
+    conversationMode: boolean;
+    loading: boolean;
+    unread: boolean;
+    displayRecipients: boolean;
+    isSelected?: boolean;
+    labelID?: string;
+}
+
+/**
+ * Renders the sender (or recipient, in sent/draft/scheduled views) of a mail list item,
+ * together with a Proton verification badge when the sender is a verified Proton user.
+ */
+const ItemSenders = ({ element, conversationMode, loading, unread, displayRecipients, isSelected = false, labelID = '' }: Props) => {
+    const { shouldHighlight, highlightMetadata } = useEncryptedSearchContext();
+    const highlightData = shouldHighlight();
+    const { getRecipientLabel } = useRecipientLabel();
+
+    // Centralized: senders (or recipients, in sent/draft/scheduled views) of the element
+    const senders = useMemo(() => getElementSenders(element, conversationMode, displayRecipients), [element, conversationMode, displayRecipients]);
+    const sendersLabels = useMemo(() => senders.map((sender) => getRecipientLabel(sender, true)), [senders, getRecipientLabel]);
+    const sendersAddresses = useMemo(() => senders.map((sender) => sender?.Address ?? '').join(', '), [senders]);
+
+    // The participant to check for Proton verification (first sender, or first recipient in sent/draft views)
+    const [firstSender] = senders;
+    const firstRecipientOrGroup = useMemo<RecipientOrGroup>(() => ({ recipient: firstSender }), [firstSender]);
+
+    const isProton = useMemo(
+        () => !displayRecipients && !!element && isProtonSender(element, firstRecipientOrGroup, displayRecipients),
+        [element, displayRecipients, firstRecipientOrGroup]
+    );
+
+    const senderContent = useMemo(
+        () =>
+            !loading && displayRecipients && !sendersLabels.length
+                ? c('Info').t`(No Recipient)`
+                : highlightData
+                ? highlightMetadata(sendersLabels.join(', '), unread, true).resultJSX
+                : sendersLabels.join(', '),
+        [loading, displayRecipients, sendersLabels, highlightData, highlightMetadata, unread]
+    );
+
+    return (
+        <>
+            <ItemUnread element={element} labelID={labelID} className="mr0-2 item-unread-dot" isSelected={isSelected} />
+            <ItemAction element={element} className="mr0-5 flex-item-noshrink myauto" />
+            <span className="max-w100 text-ellipsis" title={sendersAddresses} data-testid={displayRecipients ? 'message-row:recipient-address' : 'message-row:sender-address'}>
+                {senderContent}
+            </span>
+            {isProton && <ProtonBadgeType badgeType={PROTON_BADGE_TYPE.VERIFIED} selected={isSelected} />}
+        </>
+    );
+};
+
+export default ItemSenders;
