+import { ReactNode } from 'react';
+
+import { c } from 'ttag';
+
+import { BRAND_NAME } from '@proton/shared/lib/constants';
+import verifiedBadge from '@proton/styles/assets/img/illustrations/verified-badge.svg';
+
+import ProtonBadge from './ProtonBadge';
+
+export enum PROTON_BADGE_TYPE {
+    VERIFIED = 'VERIFIED',
+}
+
+interface Props {
+    badgeType: PROTON_BADGE_TYPE;
+    selected?: boolean;
+}
+
+interface BadgeConfig {
+    text: ReactNode;
+    icon?: string;
+}
+
+/**
+ * Renders a specific Proton badge based on the badge type.
+ * New verification types can be added to PROTON_BADGE_TYPE without changing the call sites.
+ */
+const ProtonBadgeType = ({ badgeType, selected = false }: Props) => {
+    const config: BadgeConfig | undefined = {
+        [PROTON_BADGE_TYPE.VERIFIED]: {
+            text: c('Info').t`Verified ${BRAND_NAME} message`,
+            icon: verifiedBadge,
+        },
+    }[badgeType];
+
+    if (!config) {
+        return null;
+    }
+
+    const text: ReactNode = config.icon ? (
+        <img src={config.icon} alt={config.text as string} className="ml0-25 flex-item-noshrink" />
+    ) : (
+        config.text
+    );
+    const tooltipText = config.text as string;
+
+    return <ProtonBadge text={text} tooltipText={tooltipText} selected={selected} />;
+};
+
+export default ProtonBadgeType;
