+/**
+ * Get the senders (or recipients, in sent/draft views) of an element for display in the mail list.
+ * @param element
+ * @param conversationMode
+ * @param displayRecipients when true (sent/draft/scheduled), recipients are returned instead of senders
+ */
+export const getElementSenders = (element: Element, conversationMode: boolean, displayRecipients: boolean): Recipient[] => {
+    if (!element) {
+        return [];
+    }
+
+    const participants = displayRecipients
+        ? isMessage(element)
+            ? getMessageRecipients(element as Message)
+            : ((element as Conversation).Recipients ?? [])
+        : isMessage(element)
+        ? [getSender(element as Message)].filter(Boolean)
+        : (conversationGetSenders(element as Conversation) ?? []);
