+/**
+ * @deprecated Use `isProtonSender` instead, which also considers the element participants.
+ */
 export const isFromProton = (element: Element) => {
     return !!element.IsProton;
 };
+
+/**
+ * Check if an address belongs to a Proton domain.
+ * Kept internal to this module; exported tests should use `isProtonSender`.
+ */
+const isProtonSenderAddress = (address: string): boolean => {
+    try {
+        const [, domain] = (address || '').split('@');
+        return !!domain && PROTONMAIL_DOMAINS.includes(domain.toLowerCase());
+    } catch {
+        return false;
+    }
+};
+
+/**
+ * Check whether the sender (or recipients, in sent/draft views) of an element is a Proton user.
+ * The element-level `IsProton` flag is the source of truth when present; otherwise fall back
+ * to checking the participants addresses.
+ * @param element
+ * @param recipientOrGroup
+ * @param displayRecipients when true (sent/draft/scheduled), recipients are checked instead of the sender
+ */
+export const isProtonSender = (element: Element, recipientOrGroup: RecipientOrGroup, displayRecipients: boolean): boolean => {
+    if (element.IsProton !== undefined) {
+        return !!element.IsProton;
+    }
+
+    // In sent/draft/scheduled views the relevant participant is the recipient; otherwise it is the sender.
+    const address = displayRecipients
+        ? recipientOrGroup.group?.recipients?.map(({ Address }) => Address)?.find(Boolean) || recipientOrGroup.recipient?.Address
+        : recipientOrGroup.recipient?.Address;
+
+    return !!address && isProtonSenderAddress(address);
+};
