@@ -0,0 +1,223 @@
+import { jest } from '@jest/globals';
+
+import { EVENT_ACTIONS } from '@proton/shared/lib/constants';
+import type { Listener } from '@proton/shared/lib/helpers/listeners';
+
+import { interval, maxPollingSteps, pollEvents, type PollingEventManager } from './pollEvents';
+
+type EventItem = { PaymentMethod: string; Action: EVENT_ACTIONS };
+type Event = { PaymentMethods?: EventItem[]; [key: string]: unknown };
+
+interface TestEventManager extends PollingEventManager {
+    emit: (event: Event) => void;
+    subscriberCount: () => number;
+}
+
+const createEventManager = (callImpl: () => Promise<void> = async () => undefined): TestEventManager => {
+    const subscribers = new Set<Listener<[Event], void>>();
+
+    return {
+        call: jest.fn(async () => {
+            await callImpl();
+        }),
+        subscribe: (listener: Listener<[Event], void>) => {
+            subscribers.add(listener);
+            return () => {
+                subscribers.delete(listener);
+            };
+        },
+        emit: (event) => {
+            for (const listener of [...subscribers]) {
+                listener(event);
+            }
+        },
+        subscriberCount: () => subscribers.size,
+    };
+};
+
+// Flush microtasks so the synchronous body of pollEvents() (which schedules the first
+// timer) has finished before we make assertions about armed timers / call counts.
+const flush = () => Promise.resolve();
+
+beforeEach(() => {
+    jest.useFakeTimers();
+});
+
+afterEach(() => {
+    jest.useRealTimers();
+});
+
+describe('pollEvents constants', () => {
+    it('exposes the required interval and maxPollingSteps values', () => {
+        expect(interval).toBe(5000);
+        expect(maxPollingSteps).toBe(5);
+    });
+});
+
+describe('pollEvents', () => {
+    it('calls eventManager.call() once per interval and stops after maxPollingSteps attempts', async () => {
+        const manager = createEventManager();
+        const promise = pollEvents(manager);
+        await flush();
+
+        // First call happens immediately; subsequent calls are spaced exactly one interval apart.
+        expect(manager.call).toHaveBeenCalledTimes(1);
+        for (let i = 1; i < maxPollingSteps; i += 1) {
+            await jest.advanceTimersByTimeAsync(interval);
+            expect(manager.call).toHaveBeenCalledTimes(i + 1);
+        }
+
+        // After the maximum number of attempts, further time elapses without extra calls.
+        await jest.advanceTimersByTimeAsync(interval * 10);
+        expect(manager.call).toHaveBeenCalledTimes(maxPollingSteps);
+
+        await promise;
+        expect(manager.call).toHaveBeenCalledTimes(maxPollingSteps);
+        expect(manager.subscriberCount()).toBe(0);
+    });
+
+    it('does not subscribe when no property/action is given', async () => {
+        const manager = createEventManager();
+        const promise = pollEvents(manager);
+        await flush();
+        expect(manager.subscriberCount()).toBe(0);
+
+        await jest.advanceTimersByTimeAsync(interval * maxPollingSteps);
+        await promise;
+        expect(manager.subscriberCount()).toBe(0);
+        expect(manager.call).toHaveBeenCalledTimes(maxPollingSteps);
+    });
+
+    it('subscribes when a property and action are given and unsubscribes on completion', async () => {
+        const manager = createEventManager();
+        const promise = pollEvents(manager, { property: 'PaymentMethods', action: EVENT_ACTIONS.CREATE });
+        await flush();
+        expect(manager.subscriberCount()).toBe(1);
+
+        // Exhaust the maximum attempts without a matching event.
+        await jest.advanceTimersByTimeAsync(interval * maxPollingSteps);
+        expect(manager.call).toHaveBeenCalledTimes(maxPollingSteps);
+
+        await promise;
+        expect(manager.subscriberCount()).toBe(0);
+    });
+
+    it('stops early when a matching property/action event is observed and ignores later non-matching events', async () => {
+        const manager = createEventManager();
+        const promise = pollEvents(manager, { property: 'PaymentMethods', action: EVENT_ACTIONS.CREATE });
+        await flush();
+
+        // First (immediate) call made.
+        expect(manager.call).toHaveBeenCalledTimes(1);
+
+        // One non-matching event arrives: polling must continue.
+        manager.emit({ PaymentMethods: [{ PaymentMethod: 'other', Action: EVENT_ACTIONS.UPDATE }] });
+        await jest.advanceTimersByTimeAsync(interval);
+        expect(manager.call).toHaveBeenCalledTimes(2);
+        expect(manager.subscriberCount()).toBe(1);
+
+        // A matching event arrives mid-window: polling stops.
+        manager.emit({ PaymentMethods: [{ PaymentMethod: 'new', Action: EVENT_ACTIONS.CREATE }] });
+        expect(manager.call).toHaveBeenCalledTimes(2);
+
+        // No further calls after the early stop.
+        await jest.advanceTimersByTimeAsync(interval * 10);
+        expect(manager.call).toHaveBeenCalledTimes(2);
+
+        await promise;
+        expect(manager.call).toHaveBeenCalledTimes(2);
+        expect(manager.subscriberCount()).toBe(0);
+    });
+
+    it('continues polling when the property key differs', async () => {
+        const manager = createEventManager();
+        const promise = pollEvents(manager, { property: 'PaymentMethods', action: EVENT_ACTIONS.CREATE });
+        await flush();
+
+        // Event for a different property key must be ignored.
+        manager.emit({ Subscription: [{ Action: EVENT_ACTIONS.CREATE }] });
+        await jest.advanceTimersByTimeAsync(interval);
+        expect(manager.call).toHaveBeenCalledTimes(2);
+        expect(manager.subscriberCount()).toBe(1);
+
+        // Remaining attempts still happen until the maximum is reached.
+        await jest.advanceTimersByTimeAsync(interval * (maxPollingSteps - 2));
+        await promise;
+        expect(manager.call).toHaveBeenCalledTimes(maxPollingSteps);
+        expect(manager.subscriberCount()).toBe(0);
+    });
+
+    it('continues polling when the action is not the expected one', async () => {
+        const manager = createEventManager();
+        const promise = pollEvents(manager, { property: 'PaymentMethods', action: EVENT_ACTIONS.CREATE });
+        await flush();
+
+        manager.emit({ PaymentMethods: [{ PaymentMethod: 'other', Action: EVENT_ACTIONS.DELETE }] });
+        await jest.advanceTimersByTimeAsync(interval);
+        expect(manager.call).toHaveBeenCalledTimes(2);
+
+        await jest.advanceTimersByTimeAsync(interval * (maxPollingSteps - 2));
+        await promise;
+        expect(manager.call).toHaveBeenCalledTimes(maxPollingSteps);
+        expect(manager.subscriberCount()).toBe(0);
+    });
+
+    it('ignores events that arrive after polling has finished', async () => {
+        const manager = createEventManager();
+        const promise = pollEvents(manager, { property: 'PaymentMethods', action: EVENT_ACTIONS.CREATE });
+        await flush();
+
+        // Exhaust the maximum attempts.
+        await jest.advanceTimersByTimeAsync(interval * maxPollingSteps);
+        await promise;
+        const callsBeforeLateEvent = manager.call.mock.calls.length;
+
+        // Late event after completion: must not trigger further calls or state changes.
+        manager.emit({ PaymentMethods: [{ PaymentMethod: 'late', Action: EVENT_ACTIONS.CREATE }] });
+        await jest.advanceTimersByTimeAsync(interval * 10);
+        expect(manager.call).toHaveBeenCalledTimes(callsBeforeLateEvent);
+        expect(manager.subscriberCount()).toBe(0);
+    });
+
+    it('does not trigger a second completion or restart polling after finishing', async () => {
+        const manager = createEventManager();
+        const promise = pollEvents(manager, { property: 'PaymentMethods', action: EVENT_ACTIONS.CREATE });
+        await flush();
+
+        manager.emit({ PaymentMethods: [{ PaymentMethod: 'new', Action: EVENT_ACTIONS.CREATE }] });
+        await promise;
+        const callsAfterCompletion = manager.call.mock.calls.length;
+
+        // A second (late) matching event must not cause additional calls.
+        manager.emit({ PaymentMethods: [{ PaymentMethod: 'another', Action: EVENT_ACTIONS.CREATE }] });
+        await jest.advanceTimersByTimeAsync(interval * 10);
+        expect(manager.call).toHaveBeenCalledTimes(callsAfterCompletion);
+        expect(manager.subscriberCount()).toBe(0);
+    });
+
+    it('does not call the event manager again while a call is in flight', async () => {
+        let releaseCall!: () => void;
+        const pendingCall = new Promise<void>((resolve) => {
+            releaseCall = resolve;
+        });
+        const manager = createEventManager(() => pendingCall);
+        const promise = pollEvents(manager);
+        await flush();
+
+        // First call is in flight; advancing timers must not start a second call.
+        await jest.advanceTimersByTimeAsync(interval * 3);
+        expect(manager.call).toHaveBeenCalledTimes(1);
+
+        // Once the call resolves, the next attempt is scheduled and then runs.
+        releaseCall();
+        await jest.advanceTimersByTimeAsync(interval);
+        expect(manager.call).toHaveBeenCalledTimes(2);
+
+        // Remaining attempts up to the maximum.
+        await jest.advanceTimersByTimeAsync(interval * (maxPollingSteps - 2));
+        await promise;
+        expect(manager.call).toHaveBeenCalledTimes(maxPollingSteps);
+        expect(manager.subscriberCount()).toBe(0);
+    });
+
+});
