@@ -0,0 +1,141 @@
+import type { EVENT_ACTIONS } from '@proton/shared/lib/constants';
+import { Listener } from '@proton/shared/lib/helpers/listeners';
+import type { SubscribeFn } from '@proton/shared/lib/eventManager/eventManager';
+
+/** Interval between consecutive polling calls, in milliseconds. */
+export const interval = 5000;
+
+/** Maximum number of `call()` attempts performed by one polling run. */
+export const maxPollingSteps = 5;
+
+/**
+ * A subset of the event manager interface required for polling:
+ * - `call()` fetches the next batch of events from the backend;
+ * - `subscribe(handler)` receives pushed events while polling runs, and returns an unsubscribe function.
+ */
+export interface PollingEventManager {
+    call: () => Promise<void>;
+    subscribe: SubscribeFn;
+}
+
+/** Shape of an event pushed by the event manager while polling. */
+export type PollingEvent = { [key: string]: any };
+
+export interface PollEventsOptions {
+    /**
+     * When both `property` and `action` are provided, polling stops early as soon as an event is observed with
+     * a `property` entry whose `Action` equals `action`.
+     */
+    property?: string;
+    action?: EVENT_ACTIONS;
+    /** Interval between consecutive polling calls, in milliseconds. Defaults to {@link interval}. */
+    intervalMs?: number;
+    /** Maximum number of `call()` attempts. Defaults to {@link maxPollingSteps}. */
+    maxSteps?: number;
+}
+
+/**
+ * Repeatedly invokes `eventManager.call()` at a fixed interval until either a matching
+ * property/action event is observed (when both are provided) or the maximum number of
+ * attempts has been made.
+ *
+ * While polling is in flight, an event handler is subscribed to the event manager. Events
+ * that do not match the requested property/action are ignored; once polling has finished
+ * (by early stop or by exhausting the maximum attempts) the handler is unsubscribed and any
+ * late or out-of-window events are ignored.
+ *
+ * The promise resolves when polling completes and is idempotent: a single run performs at
+ * most one completion and never leaves an active subscription behind, even if the event
+ * manager emits events concurrently with polling timeouts.
+ *
+ * @param eventManager - the event manager to poll and subscribe to
+ * @param options      - optional property/action to match, plus interval/max-attempts overrides
+ */
+export async function pollEvents(
+    eventManager: PollingEventManager,
+    {
+        property,
+        action,
+        intervalMs = interval,
+        maxSteps = maxPollingSteps,
+    }: PollEventsOptions = {}
+): Promise<void> {
+    let finished = false;
+    let stepsRemaining = maxSteps;
+    let timeoutHandle: ReturnType<typeof setTimeout> | undefined;
+
+    const finish = () => {
+        // Idempotent: only the first completion is effective.
+        if (finished) {
+            return;
+        }
+        finished = true;
+
+        if (timeoutHandle !== undefined) {
+            clearTimeout(timeoutHandle);
+        }
+
+        // Subscribe lazily so that no handler is attached (and thus nothing is leaked)
+        // when there is no property/action filter to watch for.
+        if (unsubscribe) {
+            unsubscribe();
+        }
+    };
+
+    const matches = (event: PollingEvent | undefined): boolean => {
+        if (!property || action === undefined) {
+            return false;
+        }
+
+        const items = event?.[property];
+        if (!Array.isArray(items)) {
+            return false;
+        }
+
+        return items.some((item) => item?.Action === action);
+    };
+
+    let unsubscribe: (() => void) | undefined;
+
+    if (property && action !== undefined) {
+        const listener: Listener<[PollingEvent], void> = (event) => {
+            if (finished) {
+                // Late / out-of-window event: ignore, and never trigger another completion.
+                return;
+            }
+            if (matches(event)) {
+                finish();
+            }
+        };
+        unsubscribe = eventManager.subscribe(listener) as () => void;
+    }
+
+    const step = async () => {
+        if (finished) {
+            return;
+        }
+
+        // The call may take longer than the interval; guard against re-entrancy.
+        await eventManager.call().catch(() => undefined);
+
+        if (finished) {
+            return;
+        }
+
+        stepsRemaining -= 1;
+
+        if (stepsRemaining <= 0) {
+            // Maximum attempts exhausted: deterministic completion.
+            finish();
+            return;
+        }
+
+        // Next attempt after a fixed interval, or immediately if a matching event
+        // already finished the run while the call was in flight.
+        timeoutHandle = setTimeout(() => {
+            void step();
+        }, intervalMs);
+    };
+
+    await step();
+}
